// Isolated browser/storage harness; never connects to a real account or database.
const { test, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const Module = require('node:module');
const ts = require('typescript');
const root = path.resolve(__dirname, '..');
const loaded = new Map();
const storage = new Map();
let failure = false;
let cloud = { data: null, error: null };
let save = async () => ({ data: 1, error: null });
let templateIdentitySupport = async () => ({ data: 1, error: null });
let authUser = null;
let authenticate = async () => ({ data: { user: authUser }, error: null });
let loadBookings = async () => [];
let claimsResult = { data: null, error: new Error('Invalid signature') };
let statsRenderTab = null;
let statsRenderSnapshot = null;
const serverAuth = { getClaims: async () => claimsResult, getUser: async () => ({ data: { user: authUser } }) };
const fakeSupabase = {
  from: () => ({ select: () => ({ eq: () => ({ abortSignal() { return this; }, maybeSingle: async () => cloud }) }) }),
  rpc: (...args) => Object.assign(args[0] === "planning_workout_template_identity_version" ? templateIdentitySupport(...args) : save(...args), { abortSignal() { return this; } }),
};
const events = new EventTarget();
global.window = {
  localStorage: {
    getItem: key => storage.get(key) ?? null,
    setItem: (key, value) => { if (failure) throw new Error('Quota exceeded'); storage.set(key, value); },
    removeItem: key => storage.delete(key),
  },
  addEventListener: events.addEventListener.bind(events),
  removeEventListener: events.removeEventListener.bind(events),
  dispatchEvent: events.dispatchEvent.bind(events),
};
function load(file) {
  file = path.resolve(root, file);
  if (loaded.has(file)) return loaded.get(file).exports;
  const instance = new Module(file, module);
  loaded.set(file, instance);
  instance.filename = file;
  instance.paths = module.paths;
  instance.require = name => {
    // Rendering checks use the client snapshot without mounting effects or subscriptions.
    if (name === 'react') return { ...require('react'), useSyncExternalStore: (_subscribe, snapshot) => snapshot(), useState: initial => require('react').useState(file === path.join(root, 'app/dashboard/stats/page.tsx') ? initial === 'overview' && statsRenderTab ? statsRenderTab : typeof initial === 'function' && statsRenderSnapshot ? statsRenderSnapshot : initial : initial) };
    if (name === 'next/navigation') return { useRouter: () => ({ push: () => { throw new Error('Unexpected navigation during isolated render'); } }) };
    // Review-screen tests do not render images; avoid Next Image's browser-document bootstrap in this isolated harness.
    if (name === 'next/image') return { default: () => null };
    if (name === '@/lib/supabaseClient') return { supabase: fakeSupabase, getSupabaseUser: () => authenticate() };
    if (name === '@supabase/ssr') return { createServerClient: () => ({ auth: serverAuth }) };
    if (name === '@/lib/member-services') return { loadMemberSessions: () => loadBookings() };
    if (name.startsWith('@/') || name.startsWith('.')) {
      const resolved = name.startsWith('@/') ? path.join(root, name.slice(2)) : path.resolve(path.dirname(file), name);
      if (fs.existsSync(resolved + '.ts')) return load(resolved + '.ts');
      if (fs.existsSync(resolved + '.tsx')) return load(resolved + '.tsx');
    }
    return require(name);
  };
  // Expose the real Stats snapshot reader only in this in-memory test module.
  const testSource = fs.readFileSync(file, 'utf8') + (file === path.join(root, 'app/dashboard/stats/page.tsx') ? '\nexport const __testReadStats = getStatsFromLocalStorage;\n' : '');
  instance._compile(ts.transpileModule(testSource, {
    fileName: file,
    compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022, jsx: ts.JsxEmit.ReactJSX },
  }).outputText, file);
  return instance.exports;
}
