test('plan deletion protects raw local and cloud completion links and keeps atomic selection changes', async () => {
  authUser = { id: 'deletion-member' }; await store.initializePlanning(authUser.id);
  goals.saveGoalsRecord(sampleGoals());
  const plan = plans.createWorkoutPlan({ status: 'active' }).plan;
  const assigned = plans.assignTemplateToPlanDay({ planId: plan.id, dayId: plan.days[0].id, template: saveAssignmentTemplateFixture({ id: 'deletion-template', title: 'Strength', exercises: [{ id: 'row', name: 'Row' }] }) });
  const originalPlans = plans.readWorkoutPlans();
  const completion = { id: 'completion', title: 'Original', completedAt: '2026-10-12', entries: [] };
  for (const link of [{ planId: plan.id }, { assignmentId: assigned.assignment.id }]) {
    store.writePlanning(store.planningKeys.logs, [{ ...completion, ...link }]);
    let before = store.planningSnapshot();
    assert.throws(() => plans.deleteWorkoutPlan(plan.id), /Archive this week instead/);
    assert.equal(store.planningSnapshot(), before);
    // Reporting hides the cloud identity, but its original plan link still protects history.
    store.writePlanning(store.planningKeys.logs, [completion]);
    availableLogs.publishCloudHistory(authUser.id, [{ ...completion, ...link }], 'Loaded');
    assert.deepEqual(logs.readAvailableWorkoutLogs(), [completion]);
    before = store.planningSnapshot();
    assert.throws(() => plans.deleteWorkoutPlan(plan.id), /Archive this week instead/);
    assert.equal(store.planningSnapshot(), before);
    availableLogs.clearCloudHistory();
  }
  store.writePlanning(store.planningKeys.logs, [{ ...completion, planId: plan.id }]);
  assert.equal(plans.updateWorkoutPlan(plan.id, { status: 'archived' }).plan.status, 'archived');
  assert.throws(() => plans.deleteWorkoutPlan(plan.id), /Archive this week instead/);
  plans.writeWorkoutPlans(originalPlans);
  store.writePlanning(store.planningKeys.active, plan.id);
  store.writePlanning(store.planningKeys.logs, [completion]);
  const beforeQuota = store.planningSnapshot();
  failure = true;
  try { assert.throws(() => plans.deleteWorkoutPlan(plan.id), /Quota exceeded/); }
  finally { failure = false; }
  assert.equal(store.planningSnapshot(), beforeQuota);
  const malformed = { ...originalPlans[0], days: originalPlans[0].days.map((day, index) => index === 1 ? { ...day, id: originalPlans[0].days[0].id } : day) };
  plans.writeWorkoutPlans([malformed]);
  const beforeMalformed = store.planningSnapshot();
  assert.throws(() => plans.deleteWorkoutPlan(plan.id), /original weeks are preserved/);
  assert.equal(store.planningSnapshot(), beforeMalformed);
  plans.writeWorkoutPlans(originalPlans);
  const removed = plans.deleteWorkoutPlan(plan.id);
  assert.deepEqual(removed.plans, []); assert.equal(removed.plan.id, plan.id);
  assert.equal(plans.getActiveWorkoutPlanId(), null);
  assert.deepEqual(logs.readPlanningLogs(), [completion]);
  const beforeMissing = store.planningSnapshot();
  assert.deepEqual(plans.deleteWorkoutPlan(plan.id), { plan: null, plans: [] });
  assert.equal(store.planningSnapshot(), beforeMissing);
});

test('day edits preserve calendar identities and refuse unsupported values or malformed originals', () => {
  goals.saveGoalsRecord(sampleGoals());
  const plan = plans.createWorkoutPlan().plan;
  const day = plan.days[0];
  for (const updates of [null, [], false, { id: 'replacement' }, { date: plan.days[1].date }, { assignments: [] }, { kind: null }, { kind: undefined }, { kind: 'Training' }, { focus: 42 }, { focus: undefined }, { notes: [] }, { notes: null }]) {
    const before = store.planningSnapshot();
    assert.throws(() => plans.updatePlanDay(plan.id, day.id, updates), /only day type|training or rest|must be text/);
    assert.equal(store.planningSnapshot(), before);
  }
  const edited = plans.updatePlanDay(plan.id, day.id, { kind: 'training', focus: 'Strength', notes: 'Keep this instruction' }).plan;
  assert.deepEqual(edited.days[0], { ...day, kind: 'training', focus: 'Strength', notes: 'Keep this instruction' });
  assert.deepEqual(edited.days.slice(1), plan.days.slice(1));
  const beforeQuota = store.planningSnapshot();
  failure = true;
  try { assert.throws(() => plans.updatePlanDay(plan.id, day.id, { notes: '' }), /Quota exceeded/); }
  finally { failure = false; }
  assert.equal(store.planningSnapshot(), beforeQuota);
  const malformed = { ...edited, days: edited.days.map((item, index) => index === 1 ? { ...item, id: day.id } : item) };
  plans.writeWorkoutPlans([malformed]);
  const beforeInvalid = store.planningSnapshot();
  assert.throws(() => plans.updatePlanDay(plan.id, day.id, { notes: 'Repair indirectly' }), /original weeks are preserved/);
  assert.equal(store.planningSnapshot(), beforeInvalid);
});

