test('training foundations use saved goal, week, assignment, and completion evidence instead of draft form percentages', () => {
  const now = new Date(2026, 9, 14, 12);
  const validGoals = { ...sampleGoals(), updatedAt: '2026-10-12T12:00:00Z' };
  const plan = { id: 'week', title: 'Saved week', status: 'draft', weekStartDate: '2026-10-12', days: [{ id: 'monday', date: '2026-10-12', assignments: [] }] };
  const log = { id: 'done', title: 'Actual completion', completedAt: '2026-10-12', entries: [{ exerciseId: 'squat', exerciseName: 'Squat', sets: '1' }] };
  const state = (goals, plans, logs) => trainingJourney.trainingJourneyState({ goals, plans, logs }, now);
  assert.deepEqual(state(sampleGoals(), [plan], [log]), { recorded: { goals: false, plan: true, assignments: false, workout: true }, completion: 0, next: 'Goals' });
  assert.equal(state(validGoals, [], []).completion, 25);
  assert.equal(state(validGoals, [plan], []).completion, 50);
  const assigned = { ...plan, days: [{ ...plan.days[0], assignments: [{ id: 'assignment', templateId: 'workout', templateTitle: 'Strength' }] }] };
  assert.equal(state(validGoals, [assigned], []).completion, 75);
  assert.equal(state(validGoals, [assigned], []).next, 'Sessions');
  const before = JSON.stringify({ validGoals, assigned, log });
  assert.equal(state(validGoals, [assigned], [log]).completion, 100);
  assert.equal(state(validGoals, [assigned], [log]).next, 'Progress');
  assert.equal(state(validGoals, [{ ...assigned, status: 'archived' }], [log]).completion, 25);
  assert.equal(state(validGoals, [{ ...assigned, days: [{ ...assigned.days[0], date: '2026-10-20' }] }], [log]).completion, 25);
  assert.equal(state(validGoals, [assigned], [{ ...log, completedAt: '2026-10-20' }]).completion, 75);
  assert.equal(state(validGoals, [assigned], [{ ...log, completedAt: 'invalid' }]).completion, 75);
  assert.equal(JSON.stringify({ validGoals, assigned, log }), before);
});

