test('nutrition summaries combine actual dated meals and unit-aware water without inventing missing values', () => {
  const meal = { id: 'meal', date: '2026-10-12', calories: null, protein: 30, carbs: null, fat: 0 };
  const rows = [meal, { ...meal, id: 'second', protein: null }, { ...meal, id: 'old', date: '2026-10-11', calories: 500 }];
  const water = [{ id: 'drink', date: meal.date, amount: 8, unit: 'us-fl-oz' }, { id: 'second', date: meal.date, amount: 250, unit: 'ml' }, { id: 'old', date: '2026-10-11', amount: 1000, unit: 'ml' }];
  const day = nutrition.nutritionDay(rows, water, meal.date);
  assert.equal(day.mealCount, 2); assert.equal(day.waterCount, 2); assert.ok(Math.abs(day.waterMl - 486.5882365) < 0.000001);
  assert.deepEqual(day.nutrients.calories, { value: null, reported: 0, meals: 2 });
  assert.deepEqual(day.nutrients.protein, { value: 30, reported: 1, meals: 2 });
  assert.deepEqual(day.nutrients.fat, { value: 0, reported: 2, meals: 2 });
  const missing = nutrition.nutritionDay(rows, water, '2026-10-10'); assert.equal(missing.waterMl, null); assert.equal(missing.mealCount, 0);
  assert.equal(missing.nutrients.protein.value, null);
  assert.throws(() => nutrition.nutritionDay(rows, water, '2026-02-30'), /real local date/);
});

