test('coach drafts atomically retain retry identity and reject stale clearing or storage failures', async () => {
  let editor = memberServices.captureCoachMessageEditor();
  editor = memberServices.saveCoachMessageDraft('My original draft', editor);
  const prepared = memberServices.prepareCoachMessageSend('My original draft', editor);
  assert.equal(store.readPlanning('coachMessageDraft', ''), 'My original draft');
  assert.equal(memberServices.prepareCoachMessageSend('My original draft', prepared.editor).requestId, prepared.requestId);
  const unchanged = memberServices.saveCoachMessageDraft('My original draft', prepared.editor);
  assert.equal(store.readPlanning('coachMessageRequest', null), prepared.requestId);
  const before = store.planningSnapshot();
  failure = true;
  try {
    assert.throws(() => memberServices.finishCoachMessageDraft(unchanged), /Quota/);
    assert.throws(() => memberServices.saveCoachMessageDraft('Changed text', unchanged), /Quota/);
    assert.throws(() => memberServices.prepareCoachMessageSend('Changed text', unchanged), /Quota/);
  } finally { failure = false; }
  assert.equal(store.planningSnapshot(), before);
  assert.equal(memberServices.prepareCoachMessageSend('My original draft', unchanged).requestId, prepared.requestId);
  const newer = memberServices.saveCoachMessageDraft('Newer tab text', unchanged);
  assert.equal(store.readPlanning('coachMessageRequest', null), null);
  const newerSnapshot = store.planningSnapshot();
  for (const action of [() => memberServices.finishCoachMessageDraft(prepared.editor), () => memberServices.saveCoachMessageDraft('Stale text', prepared.editor), () => memberServices.prepareCoachMessageSend('Stale send', prepared.editor)]) assert.throws(action, /another tab/);
  assert.equal(store.planningSnapshot(), newerSnapshot);
  const next = memberServices.prepareCoachMessageSend('Newer tab text', newer);
  assert.notEqual(next.requestId, prepared.requestId);
  const finished = memberServices.finishCoachMessageDraft(next.editor);
  assert.equal(store.readPlanning('coachMessageDraft', null), ''); assert.equal(store.planningSnapshot().coachMessageRequest, null);
  await store.initializePlanning('other-message-owner');
  const other = store.planningSnapshot();
  assert.throws(() => memberServices.saveCoachMessageDraft('Original owner text', finished), /account changed/);
  assert.throws(() => memberServices.prepareCoachMessageSend('Original owner text', finished), /account changed/);
  assert.throws(() => memberServices.finishCoachMessageDraft(finished), /account changed/);
  assert.equal(store.planningSnapshot(), other);
});

test('message confirmation requires the exact member, request and body before allowing draft clearing', async () => {
  authUser = { id: 'confirmed-member' }; await store.initializePlanning(authUser.id);
  const requestId = crypto.randomUUID();
  const row = { id: crypto.randomUUID(), member_id: authUser.id, app_request_id: requestId, sent_by: 'member', body: 'Hello coach', created_at: '2026-10-12T20:40:00Z' };
  let calls = 0;
  for (const data of [null, {}, row, [], [row, row], [{ id: row.id }], ...[
    { id: 1 }, { id: 'invalid' }, { member_id: 'another-member' }, { app_request_id: crypto.randomUUID() },
    { app_request_id: null }, { sent_by: 'coach' }, { body: 'Changed body' }, { created_at: 'bad' }, { created_at: null },
    { created_at: '2026-02-30T12:00:00Z' }, { created_at: '2026-10-12' }, { created_at: '2026-10-12T12:00:00' },
  ].map(change => [{ ...row, ...change }])]) {
    save = async () => { calls++; return { data, error: null }; };
    await assert.rejects(memberServices.sendMemberMessage(' Hello coach ', requestId), /not confirmed sent/);
  }
  const beforeCalls = calls;
  for (const body of [null, [], {}, false, '', ' ', 'x'.repeat(2001)]) await assert.rejects(memberServices.sendMemberMessage(body, requestId), /1–2,000/);
  for (const request of [null, [], {}, '', 'invalid']) await assert.rejects(memberServices.sendMemberMessage(row.body, request), /request needs review/);
  assert.equal(calls, beforeCalls);
  const before = store.planningSnapshot();
  save = async (name, payload) => {
    assert.equal(name, 'send_app_member_message'); assert.equal(payload.message_body, row.body);
    return { data: [row], error: null };
  };
  assert.deepEqual(await memberServices.sendMemberMessage(' Hello coach ', requestId.toUpperCase()), { id: row.id, sent_by: 'member', body: row.body, created_at: row.created_at });
  assert.equal(store.planningSnapshot(), before);
});

test('member services reject account switches during authentication, reads, and message sends', async () => {
  authUser = { id: 'member' }; await store.initializePlanning('member');
  let finishAuth;
  authenticate = () => new Promise(resolve => { finishAuth = resolve; });
  const authenticating = memberServices.sendMemberMessage('Original account draft', crypto.randomUUID());
  await store.initializePlanning('another-member'); authUser = { id: 'another-member' };
  finishAuth({ data: { user: authUser }, error: null });
  await assert.rejects(authenticating, /account changed/);
  authenticate = async () => ({ data: { user: authUser }, error: null });
  const previousFrom = fakeSupabase.from;
  try {
    for (const operation of [memberServices.loadMemberMessages, memberServices.loadMemberSchedule, memberServices.loadMemberSessions, memberServices.loadMemberSessionBalances]) {
      const resolvers = [];
      fakeSupabase.from = table => table === 'planning_documents' ? previousFrom(table) : ({ select() { return this; }, eq() { return this; }, order() { return this; }, limit() { return this; }, single() { return new Promise(resolve => resolvers.push(resolve)); }, abortSignal() { return table === 'profiles' ? this : new Promise(resolve => resolvers.push(resolve)); } });
      const pending = operation();
      await new Promise(resolve => setImmediate(resolve));
      await store.initializePlanning('switched');
      resolvers.forEach(resolve => resolve({ data: [], error: null }));
      await assert.rejects(pending, /account changed/);
      await store.initializePlanning('another-member');
    }
    let finishSend;
    save = async (_name, payload) => {
      assert.equal(payload.expected_member_id, 'another-member');
      return new Promise(resolve => { finishSend = resolve; });
    };
    const sending = memberServices.sendMemberMessage('Hello', crypto.randomUUID());
    await new Promise(resolve => setImmediate(resolve));
    await store.initializePlanning('switched');
    finishSend({ data: [{ id: 'message', body: 'Hello' }], error: null });
    await assert.rejects(sending, /account changed/);
  } finally { fakeSupabase.from = previousFrom; }
});

function memberRowsBackend(records, { cap = 37, profile = {}, pageHook } = {}) {
  const original = fakeSupabase.from; const requests = [];
  fakeSupabase.from = table => {
    if (table === 'planning_documents') return original(table);
    let owner, cursor = null, limit;
    return {
      select() { return this; }, eq(field, value) { owner = value; return this; },
      order(field, options) { if (table !== 'profiles') { assert.equal(field, 'id'); assert.equal(options.ascending, true); } return this; },
      limit(value) { limit = value; return this; }, gt(field, value) { assert.equal(field, 'id'); cursor = value; return this; },
      single() { return Promise.resolve({ data: { id: owner, ...profile }, error: null }); },
      abortSignal(signal) {
        assert.ok(signal instanceof AbortSignal);
        if (table === 'profiles') return this;
        const request = { table, owner, cursor, limit }; requests.push(request);
        const data = (records[table] || []).filter(row => row.member_id === owner && (!cursor || row.id > cursor)).sort((a, b) => a.id.localeCompare(b.id)).slice(0, Math.min(limit, cap));
        return Promise.resolve().then(async () => await pageHook?.(request, data) || { data, error: null });
      },
    };
  };
  return { requests, restore: () => { fakeSupabase.from = original; } };
}
const memberSessionRow = (index, owner = 'member-pages') => ({ id: String(index).padStart(6, '0'), member_id: owner, starts_at: new Date(Date.UTC(2026, 9, 1, 12) + index * 60000).toISOString(), duration_minutes: 60, service_type: 'Training', location: null, coach_name: null, status: 'scheduled' });

