test('website pagination rejects later-page failures, ownership changes, invalid values, and repeated cursors without returning partial data', async () => {
  authUser = { id: 'member-pages' }; await store.initializePlanning(authUser.id);
  const cases = [
    (_request, data) => ({ data, error: new Error('Offline') }),
    (_request, data) => ({ data: [{ ...data[0], member_id: 'someone-else' }], error: null }),
    (_request, data) => ({ data: [{ ...data[0], duration_minutes: 0 }], error: null }),
    (_request, data) => ({ data: [{ ...data[0], starts_at: 'invalid' }], error: null }),
    (_request, data) => ({ data: [{ ...data[0], id: '000000' }], error: null }),
    () => ({ data: null, error: null }),
    async () => { await store.initializePlanning('switched'); return { data: [], error: null }; },
  ];
  for (const corrupt of cases) {
    await store.initializePlanning(authUser.id);
    const backend = memberRowsBackend({ member_sessions: [memberSessionRow(0), memberSessionRow(1)] }, { cap: 1, pageHook: (request, data) => request.cursor ? corrupt(request, data) : undefined });
    try { await assert.rejects(memberServices.loadMemberSessions()); assert.equal(backend.requests.length, 2); }
    finally { backend.restore(); }
  }
});

