test('weekly feedback requires reported ratings and preserves account-scoped history', async () => {
  const now = new Date(2026, 9, 12, 12);
  const week = checkIns.checkInWeek(now);
  assert.equal(week, '2026-10-12');
  assert.equal(checkIns.checkInWeek(new Date(2026, 9, 18, 23)), week);
  assert.equal(checkIns.checkInReadiness(checkIns.emptyCheckIn()), null);
  assert.throws(() => checkIns.saveWeeklyCheckIn(checkIns.emptyCheckIn(), week, undefined, now), /Rate energy/);
  const draft = { energy: 7, sleep: 8, stress: 4, soreness: 3, habits: [checkIns.CHECK_IN_HABITS[0]], notes: 'My own notes' };
  for (const rating of [0, 11, 1.5, '7']) assert.throws(() => checkIns.saveWeeklyCheckIn({ ...draft, energy: rating }, week, undefined, now), /Rate energy/);
  assert.throws(() => checkIns.saveWeeklyCheckIn({ ...draft, notes: 'x'.repeat(4001) }, week, undefined, now), /4,000/);
  const first = checkIns.saveWeeklyCheckIn(draft, week, undefined, now);
  assert.throws(() => checkIns.saveWeeklyCheckIn(draft, week, undefined, now), /another tab/);
  const updated = checkIns.saveWeeklyCheckIn({ ...draft, notes: 'Updated' }, week, JSON.stringify(first), now);
  assert.equal(updated.id, first.id); assert.equal(checkIns.readWeeklyCheckIns().length, 1);
  failure = true;
  assert.throws(() => checkIns.saveWeeklyCheckIn({ ...draft, notes: 'Unsaved' }, week, JSON.stringify(updated), now), /Quota/);
  assert.equal(checkIns.currentWeeklyCheckIn(week).notes, 'Updated'); failure = false;
  const next = new Date(2026, 9, 19, 12);
  assert.throws(() => checkIns.saveWeeklyCheckIn(draft, week, JSON.stringify(updated), next), /week changed/);
  checkIns.saveWeeklyCheckIn(draft, checkIns.checkInWeek(next), undefined, next);
  assert.equal(checkIns.readWeeklyCheckIns().length, 2);
  assert.equal(importValidation.validatePlanningImport({ [checkIns.WEEKLY_CHECK_INS_KEY]: checkIns.readWeeklyCheckIns() }), null);
  await store.initializePlanning('another-member');
  assert.deepEqual(checkIns.readWeeklyCheckIns(), []);
});

