test('weekly draft stale editors, account switches, and later weeks preserve recoverable answers', async () => {
  const now = new Date(2026, 9, 12, 12); const next = new Date(2026, 9, 19, 12);
  const week = checkIns.checkInWeek(now); const account = store.planningOwner();
  const answers = { ...checkIns.emptyCheckIn(), notes: 'First tab' };
  const original = checkIns.weeklyDraftVersion(week);
  const version = checkIns.saveWeeklyCheckInDraft(answers, week, original, undefined, account, store.planningAccountGeneration(), now);
  assert.throws(() => checkIns.saveWeeklyCheckInDraft({ ...answers, notes: 'Stale tab' }, week, original, undefined, account, store.planningAccountGeneration(), now), /another tab/);
  assert.throws(() => checkIns.discardWeeklyCheckInDraft(week, original, account, store.planningAccountGeneration()), /another tab/);
  assert.throws(() => checkIns.saveWeeklyCheckIn({ energy: 7, sleep: 7, stress: 3, soreness: 3, habits: [], notes: 'Stale final save' }, week, undefined, now, { generation: store.planningAccountGeneration(), account, draftVersion: original }), /another tab/);
  assert.throws(() => checkIns.saveWeeklyCheckInDraft(answers, week, version, undefined, account, store.planningAccountGeneration(), next), /week changed/);
  checkIns.saveWeeklyCheckInDraft({ ...answers, notes: 'Next week' }, checkIns.checkInWeek(next), 'null', undefined, account, store.planningAccountGeneration(), next);
  assert.equal(Object.keys(checkIns.readWeeklyCheckInDrafts()).length, 2);
  failure = true; assert.throws(() => checkIns.discardWeeklyCheckInDraft(week, version, account, store.planningAccountGeneration()), /Quota/); failure = false;
  assert.equal(checkIns.readWeeklyCheckInDraft(week).notes, 'First tab');
  checkIns.discardWeeklyCheckInDraft(week, version, account, store.planningAccountGeneration());
  assert.equal(Object.keys(checkIns.readWeeklyCheckInDrafts()).length, 1);
  await store.initializePlanning('other');
  assert.throws(() => checkIns.saveWeeklyCheckInDraft(answers, week, 'null', undefined, account, store.planningAccountGeneration(), now), /account changed/);
  assert.deepEqual(checkIns.readWeeklyCheckInDrafts(), {});
});

