test('progress week boundaries respect local date-only completions across DST and year changes', () => {
  const previous = process.env.TZ;
  try {
    for (const zone of ['America/Los_Angeles', 'Pacific/Auckland']) {
      process.env.TZ = zone;
      for (const [now, monday, sunday] of [[new Date(2026, 2, 9, 12), '2026-03-09', '2026-03-15'], [new Date(2027, 0, 1, 12), '2026-12-28', '2027-01-03']]) {
        const summary = progress.buildProgressSummary({ logs: [{ id: 'local-day', title: 'Workout', completedAt: monday, entries: [{ exerciseId: 'squat', exerciseName: 'Squat', sets: '1' }] }], goals: {}, plans: [], checkIns: [], journal: [] }, now);
        assert.equal(summary.weekStart, monday); assert.equal(summary.weekEnd, sunday); assert.equal(summary.weeklySessions, 1, zone);
      }
    }
  } finally { if (previous === undefined) delete process.env.TZ; else process.env.TZ = previous; }
});

test('pain reports require explicit ratings and preserve history through retries and storage failure', async () => {
  const account = store.planningOwner();
  assert.equal(painLogs.readPainLogs(), painLogs.readPainLogs(), 'empty subscription snapshot is stable');
  const report = { id: 'pain-report', level: 0, area: 'No specific area', notes: 'No discomfort reported' };
  for (const level of [null, -1, 11, 1.5, '3']) assert.throws(() => painLogs.savePainLog({ ...report, level }, account, store.planningAccountGeneration()), /Choose a pain rating/);
  assert.throws(() => painLogs.savePainLog({ ...report, area: '' }, account, store.planningAccountGeneration()), /body area/);
  assert.throws(() => painLogs.savePainLog({ ...report, notes: 'x'.repeat(4001) }, account, store.planningAccountGeneration()), /4,000/);
  failure = true;
  assert.throws(() => painLogs.savePainLog(report, account, store.planningAccountGeneration()), /Quota/);
  assert.equal(painLogs.readPainLogs().length, 0); failure = false;
  const saved = painLogs.savePainLog(report, account, store.planningAccountGeneration());
  assert.equal(saved.level, 0, 'an explicit zero rating is a report');
  assert.deepEqual(painLogs.savePainLog(report, account, store.planningAccountGeneration()), saved); assert.equal(painLogs.readPainLogs().length, 1);
  assert.throws(() => painLogs.savePainLog({ ...report, level: 4 }, account, store.planningAccountGeneration()), /different answers/);
  painLogs.savePainLog({ ...report, id: 'second', level: 4, area: 'Left knee' }, account, store.planningAccountGeneration());
  assert.equal(painLogs.readPainLogs().length, 2);
  const summary = progress.buildProgressSummary({ logs: [], goals: {}, plans: [], checkIns: [], journal: [], painLogs: painLogs.readPainLogs() });
  assert.equal(summary.feedbackProgress.find(item => item.label === 'Pain Reports').value, '2');
  assert.equal(importValidation.validatePlanningImport({ [painLogs.PAIN_LOGS_KEY]: painLogs.readPainLogs() }), null);
  assert.match(importValidation.validatePlanningImport({ [painLogs.PAIN_LOGS_KEY]: [{ ...saved, recordedAt: 'invalid' }] }), /unsupported structure/);
  await store.initializePlanning('another-member');
  assert.deepEqual(painLogs.readPainLogs(), []);
  assert.throws(() => painLogs.savePainLog(report, account, store.planningAccountGeneration()), /account changed/);
  store.writePlanning('other-edit', 'local');
  store.refreshPlanningFromStorage({ key: 'soundFitnessPlanning:v1:another-member', newValue: JSON.stringify({ values: { other: true }, revision: 0, dirty: true }) });
  assert.throws(() => painLogs.savePainLog(report, store.planningOwner(), store.planningAccountGeneration()), /sync conflict/);
});

