test('malformed current library collections pause all edits without filtering or replacing originals', () => {
  const account = store.planningOwner();
  for (const id of ['nutrition', 'recovery', 'mobility', 'performance']) {
    const [stateKey, draftKey] = libraries.libraryKeys[id];
    for (const [key, value] of [[stateKey, null], [stateKey, { favorites: ['keep', {}], recent: [] }], [stateKey, { favorites: [], recent: false }], [draftKey, null], [draftKey, { items: [false] }], [draftKey, [{ id: 'a', title: 'A' }, { id: 'a', title: 'Duplicate' }]], [store.planningKeys.libraryFavorites, ['keep', {}]]]) {
      store.writePlanningValues({ [stateKey]: { favorites: [], recent: [] }, [draftKey]: [], [store.planningKeys.libraryFavorites]: [] });
      store.writePlanning(key, value); const original = store.planningSnapshot();
      assert.ok(libraries.libraryReviewIssue(id));
      assert.deepEqual(libraries.readLibraryState(id), { favorites: [], recent: [] }); assert.deepEqual(libraries.readLibraryDraft(id), []);
      const version = libraries.libraryVersion(id); const draftVersion = libraries.libraryDraftVersion(id);
      for (const action of [() => libraries.toggleLibraryFavorite(id, 'new', version, account, store.planningAccountGeneration()), () => libraries.addLibraryDraftItem(id, { id: 'new', title: 'New' }, version, draftVersion, account, store.planningAccountGeneration()), () => libraries.removeLibraryDraftItem(id, 'old', draftVersion, account, store.planningAccountGeneration()), () => libraries.importLegacyLibrary(id, version, draftVersion, account, store.planningAccountGeneration())]) assert.throws(action, /Saved library data needs review/);
      assert.equal(store.planningSnapshot(), original); assert.deepEqual(original[key], value);
    }
  }
});

