test('explicit library import preserves originals and current account items, validates shapes, and rolls back on failure', () => {
  const account = store.planningOwner();
  storage.set(store.planningKeys.nutritionLibrary, JSON.stringify({ favorites: ['old'], recent: ['old'] }));
  storage.set(store.planningKeys.libraryFavorites, JSON.stringify(['nutrition:global-old', 'recovery:private-other-library']));
  storage.set(store.planningKeys.nutritionDraft, JSON.stringify([{ id: 'old', title: 'Older meal' }]));
  const originals = [...storage.entries()].filter(([key]) => [store.planningKeys.nutritionLibrary, store.planningKeys.libraryFavorites, store.planningKeys.nutritionDraft].includes(key));
  libraries.addLibraryDraftItem('nutrition', { id: 'new', title: 'Current meal' }, libraries.libraryVersion('nutrition'), libraries.libraryDraftVersion('nutrition'), account, store.planningAccountGeneration());
  assert.equal(libraries.legacyLibraryAvailable('nutrition'), true);
  failure = true; assert.throws(() => libraries.importLegacyLibrary('nutrition', libraries.libraryVersion('nutrition'), libraries.libraryDraftVersion('nutrition'), account, store.planningAccountGeneration()), /Quota/); failure = false;
  assert.deepEqual(libraries.readLibraryState('nutrition').favorites, []); assert.equal(libraries.readLibraryDraft('nutrition').length, 1);
  libraries.importLegacyLibrary('nutrition', libraries.libraryVersion('nutrition'), libraries.libraryDraftVersion('nutrition'), account, store.planningAccountGeneration());
  assert.deepEqual(libraries.readLibraryState('nutrition').favorites, ['old', 'global-old']); assert.equal(libraries.readLibraryDraft('nutrition').length, 2);
  assert.deepEqual(store.readPlanning(store.planningKeys.libraryFavorites, []), ['nutrition:global-old']); assert.equal(libraries.legacyLibraryAvailable('nutrition'), false);
  for (const [key, value] of originals) assert.equal(storage.get(key), value);
  storage.set(store.planningKeys.nutritionDraft, JSON.stringify([{ id: 'new', title: 'Conflicting old meal' }]));
  assert.throws(() => libraries.importLegacyLibrary('nutrition', libraries.libraryVersion('nutrition'), libraries.libraryDraftVersion('nutrition'), account, store.planningAccountGeneration()), /conflicts/);
  storage.set(store.planningKeys.nutritionDraft, '{broken');
  assert.throws(() => libraries.importLegacyLibrary('nutrition', libraries.libraryVersion('nutrition'), libraries.libraryDraftVersion('nutrition'), account, store.planningAccountGeneration()), /cannot be read/);
  assert.equal(libraries.readLibraryDraft('nutrition').length, 2);
});

