  const original = { id: 'legacy-labels', title: { originalTitle: 'Evening strength' }, completedAt: '2026-10-12', syncError: { originalError: 'Needs review' }, entries: [{ exerciseId: 'legacy', exerciseName: { originalName: 'Goblet squat' }, sets: '3', reps: '8', weight: '0' }] };
