test('legacy phase identities are stable, distinct, collision-safe, and remain read-only until saved', async () => {
  const key = store.planningKeys.phases, account = store.planningOwner();
  const source = [{ title: 'Older block', active: true, startDate: '2026-10-01' }, { name: 'Same title' }, { name: 'Same title' }, { id: 'legacy-phase:0', name: 'Existing identity' }];
  store.writePlanning(key, source);
  const first = phaseRecords.phaseRecords(source); const second = phaseRecords.phaseRecords(store.readPlanning(key, []));
  assert.deepEqual(first, second); assert.equal(new Set(first.map(row => row.id)).size, 4); assert.notEqual(first[0].id, 'legacy-phase:0');
  assert.deepEqual(store.readPlanning(key, []), source);
  const version = phaseContext.phaseRecordVersion(source, first[0].id); assert.ok(version);
  assert.equal(phaseContext.phaseRecordVersion(source.map(row => Object.fromEntries(Object.entries(row).reverse())), first[0].id), version);
  const baseline = store.planningRecordVersion(key); failure = true;
  assert.throws(() => phaseMutations.commitPhaseRecords(first, account, baseline, store.planningAccountGeneration()), /Quota/); failure = false;
  assert.deepEqual(store.readPlanning(key, []), source);
  phaseMutations.commitPhaseRecords(first, account, baseline, store.planningAccountGeneration());
  await store.initializePlanning(null);
  assert.deepEqual(phaseRecords.phaseRecords(store.readPlanning(key, [])), first);
  const edited = first.map((row, index) => index === 0 ? { ...row, name: 'Updated block' } : row);
  phaseMutations.commitPhaseRecords(edited, account, store.planningRecordVersion(key), store.planningAccountGeneration());
  assert.equal(store.readPlanning(key, [])[0].id, first[0].id);
});

test('phase saves retain wrapper fields, unknown record fields, and unnamed records the page cannot edit', () => {
  const key = store.planningKeys.phases, account = store.planningOwner();
  const source = { phases: [{ id: 'visible', name: 'Visible', coachContext: { note: 'Keep' } }, { futureData: ['Preserve'], other: 'Unknown record' }], schemaVersion: 8, coach: { id: 'context' } };
  store.writePlanning(key, source);
  const projected = phaseRecords.phaseRecords(source);
  phaseMutations.commitPhaseRecords([{ id: 'visible', name: 'Edited' }], account, store.planningRecordVersion(key), store.planningAccountGeneration());
  const saved = store.readPlanning(key, null);
  assert.equal(saved.schemaVersion, 8); assert.deepEqual(saved.coach, source.coach); assert.deepEqual(saved.phases[0].coachContext, source.phases[0].coachContext);
  assert.deepEqual(saved.phases[1], projected[1]);
  phaseMutations.commitPhaseRecords([], account, store.planningRecordVersion(key), store.planningAccountGeneration());
  const removed = store.readPlanning(key, null); assert.deepEqual(removed.phases, [projected[1]]); assert.equal(removed.schemaVersion, 8);
});

test('ambiguous or malformed phase collections refuse replacement and preserve originals', () => {
  const key = store.planningKeys.phases, account = store.planningOwner();
  for (const source of [[{ id: 'duplicate', name: 'First' }, { id: 'duplicate', name: 'Second' }], [{ id: 5, name: 'Invalid identity' }], [{ name: 'Valid' }, 'Unreadable'], { phases: 'Unreadable', keep: 'Preserve' }]) {
    store.writePlanning(key, source); const version = store.planningRecordVersion(key);
    assert.throws(() => phaseMutations.commitPhaseRecords([], account, version, store.planningAccountGeneration()), /need review/); assert.deepEqual(store.readPlanning(key, null), source);
  }
  store.writePlanning(key, []);
  assert.throws(() => phaseMutations.commitPhaseRecords([{ id: 'same' }, { id: 'same' }], account, store.planningRecordVersion(key), store.planningAccountGeneration()), /identities need review/);
});

