test('phase recovery evidence shares strict recommendation parsing and preserves explicit zero', () => {
  for (const value of [null, undefined, [], false, 'reported']) {
    assert.deepEqual(phaseContext.phaseRecoverySignals(value), { readinessReported: false, hotAreas: 0 });
  }
  for (const value of [true, false, [], ['5'], {}, '0x5', '0b1', 'bad', Infinity, NaN, -1, 25, '', ' ']) {
    const body = { painLevel: value, sorenessLevel: value, averageSleepHours: value, hoursSlept: value };
    assert.deepEqual(recommendations.profileRecoveryReports(body), { pain: null, soreness: null, sleep: null });
    assert.deepEqual(phaseContext.phaseRecoverySignals(body), { readinessReported: false, hotAreas: 0 });
  }
  const body = { painLevel: 0, sorenessLevel: '0', averageSleepHours: '0', hoursSlept: '8' };
  const before = JSON.stringify(body);
  assert.deepEqual(recommendations.profileRecoveryReports(body), { pain: 0, soreness: 0, sleep: 0 });
  assert.deepEqual(phaseContext.phaseRecoverySignals(body), { readinessReported: true, hotAreas: 1 });
  assert.equal(recommendations.recommendPlan({ bodyStatus: body }, sampleGoals()).split, 'Flexible');
  assert.deepEqual(phaseContext.phaseRecoverySignals({ painLevel: '2', sorenessLevel: '5', averageSleepHours: 'bad', hoursSlept: '6' }), { readinessReported: true, hotAreas: 3 });
  assert.deepEqual(phaseContext.phaseRecoverySignals({ painLevel: 0, sorenessLevel: 0, averageSleepHours: 8 }), { readinessReported: true, hotAreas: 0 });
  assert.equal(JSON.stringify(body), before);
});

