test('phase schedules reject unbounded duration and out-of-range scheduled weeks', () => {
  const phase = { name: 'Build', durationWeeks: '6', volumeTarget: '36', intensityTarget: '7', deloadWeek: '5', testingWeek: '6' };
  assert.equal(phaseContext.validatePhaseSchedule(phase), null);
  assert.match(phaseContext.validatePhaseSchedule({ ...phase, durationWeeks: '1000000' }), /52/);
  assert.match(phaseContext.validatePhaseSchedule({ ...phase, durationWeeks: '4' }), /within/);
  assert.equal(phaseContext.validatePhaseSchedule({ ...phase, deloadWeek: '', testingWeek: '' }), null);
});

test('phase goal editors reject changed targets, switched accounts and invalid goals without writes', async () => {
  goals.saveGoalsRecord(sampleGoals());
  const editor = phaseMutations.capturePhaseGoalEditor();
  assert.equal(phaseMutations.assertPhaseGoalEditor(editor).targetWeeklySets, '36');
  const saved = store.readPlanning(store.planningKeys.goals, {});
  store.writePlanning(store.planningKeys.goals, { ...saved, targetWeeklySets: '48' });
  let before = store.planningSnapshot();
  assert.throws(() => phaseMutations.assertPhaseGoalEditor(editor), /Goals changed/);
  assert.equal(store.planningSnapshot(), before);
  const refreshed = phaseMutations.capturePhaseGoalEditor();
  assert.equal(phaseMutations.assertPhaseGoalEditor(refreshed).targetWeeklySets, '48');
  store.writePlanning(store.planningKeys.goals, Object.fromEntries(Object.entries(store.readPlanning(store.planningKeys.goals, {})).reverse()));
  assert.equal(phaseMutations.assertPhaseGoalEditor(refreshed).targetWeeklySets, '48');
  store.writePlanning(store.planningKeys.goals, { ...saved, targetWeeklySets: ['36'] });
  const invalid = phaseMutations.capturePhaseGoalEditor(); before = store.planningSnapshot();
  assert.throws(() => phaseMutations.assertPhaseGoalEditor(invalid), /Goals/);
  assert.equal(store.planningSnapshot(), before);
  await store.initializePlanning('another-phase-member');
  before = store.planningSnapshot();
  assert.throws(() => phaseMutations.assertPhaseGoalEditor(editor), /account changed/);
  assert.equal(store.planningSnapshot(), before);
});

test('phase schedule numeric validation refuses coercible values and keeps missing targets unset', () => {
  const phase = { name: 'Build', durationWeeks: '6', volumeTarget: '36', intensityTarget: '7', deloadWeek: '5', testingWeek: '6' };
  const before = JSON.stringify(phase);
  for (const field of ['durationWeeks', 'volumeTarget', 'intensityTarget', 'deloadWeek', 'testingWeek']) {
    for (const value of [true, false, [], ['1'], {}, '0x1', '0b1', Infinity, NaN, null, undefined]) {
      assert.ok(phaseContext.validatePhaseSchedule({ ...phase, [field]: value }), `${field} must refuse ${String(value)}`);
    }
  }
  assert.match(phaseContext.validatePhaseSchedule({ ...phase, volumeTarget: '' }), /weekly set target/);
  assert.equal(phaseContext.validatePhaseSchedule({ ...phase, volumeTarget: '3.6e1', intensityTarget: '7.5', deloadWeek: '', testingWeek: ' ' }), null);
  assert.match(phaseContext.validatePhaseSchedule({ ...phase, name: {} }), /phase name/);
  assert.equal(JSON.stringify(phase), before);
});

test('booked sessions cannot be edited or copied into planning records', async () => {
  await store.initializePlanning('booking-member');
  loadBookings = async () => [{ id: 'one', starts_at: new Date(2026, 9, 12, 12).toISOString(), duration_minutes: 60, service_type: 'Strength', status: 'scheduled' }];
  await bookings.refreshBookedSessions();
  const items = calendar.readIndependentCalendar();
  assert.equal(items[0].bookingId, 'one');
  assert.throws(() => calendar.saveCalendarItems(items.map(item => ({ ...item, time: '15:00' }))), /Manage booked/);
  assert.throws(() => calendar.saveCalendarItems([]), /Manage booked/);
  for (const change of [{ bookingId: undefined }, { bookingId: 'other' }, { id: 'independent-copy' }]) {
    const before = store.planningSnapshot();
    assert.throws(() => calendar.saveCalendarItems(items.map(item => ({ ...item, ...change }))), /Website bookings changed/);
    assert.equal(store.planningSnapshot(), before);
  }
  calendar.saveCalendarItems(items);
  assert.equal(store.readPlanning(store.planningKeys.calendar, []).length, 0);
  assert.equal(dashboardCalendar.planningDashboardCalendarItems()[0].manageHref, '/dashboard/sessions/booking');
  const editor = calendar.captureCalendarEditor();
  loadBookings = async () => [{ id: 'one', starts_at: new Date(2026, 9, 12, 14).toISOString(), duration_minutes: 60, service_type: 'Strength', status: 'scheduled' }];
  await bookings.refreshBookedSessions();
  const before = store.planningSnapshot();
  assert.throws(() => calendar.saveCalendarItems(items, editor), /Calendar records changed/);
  assert.equal(store.planningSnapshot(), before);
});

