test('import validation catches nested plan/log failures and duplicate template identities', () => {
  const workout = { id: 'duplicate', title: 'Workout', exercises: [] };
  assert.match(importValidation.validatePlanningImport({ [store.planningKeys.templates]: [workout, workout] }), /unsupported structure/);
  assert.match(importValidation.validatePlanningImport({ [store.planningKeys.plans]: [{ id: 'plan', title: 'Week', weekStartDate: '2026-10-12', days: [{ id: 'day', date: '2026-10-12', assignments: null }] }] }), /unsupported structure/);
  assert.match(importValidation.validatePlanningImport({ [store.planningKeys.logs]: [{ id: 'log', title: 'Workout', completedAt: '2026-10-12', entries: [null] }] }), /unsupported structure/);
  assert.match(importValidation.validatePlanningImport({ [store.planningKeys.exerciseStats]: [{ exerciseId: 'squat', exerciseName: 'Squat', date: '2026-02-30' }] }), /unsupported structure/);
  assert.equal(importValidation.validatePlanningImport({ [store.planningKeys.phases]: { phases: [{ name: 'Build' }] }, [store.planningKeys.profile]: { birthday: '1990-01-01' } }), null);
  const assignment = { id: 'same-assignment', templateTitle: 'Workout' };
  const plan = { id: 'plan', title: 'Week', weekStartDate: '2026-10-12', days: [{ id: 'one', date: '2026-10-12', assignments: [assignment] }] };
  assert.equal(importValidation.validatePlanningImport({ [store.planningKeys.plans]: [plan] }), null);
  assert.match(importValidation.validatePlanningImport({ [store.planningKeys.plans]: [{ ...plan, days: [...plan.days, { id: 'two', date: '2026-10-13', assignments: [assignment] }] }] }), /unsupported structure/);
  assert.match(importValidation.validatePlanningImport({ [store.planningKeys.plans]: [plan, { ...plan, id: 'other', days: [] }] }), /unsupported structure/);
});
test('plan import calendar checks reject inconsistent dates, rest assignments, and invalid planned counts without repair', () => {
  const key = store.planningKeys.plans;
  const assignment = { id: 'assignment', templateTitle: 'Workout', templateExerciseCount: 2, setsPerExercise: 3, time: '09:00' };
  const day = { id: 'monday', date: '2026-10-12', dayOfWeek: 'Monday', kind: 'training', assignments: [assignment] };
  const plan = { id: 'plan', title: 'Partial older week', weekStartDate: '2026-10-12', status: 'draft', mode: 'custom', days: [day] };
  assert.equal(importValidation.validatePlanningImport({ [key]: [plan] }), null);
  const invalid = [
    { ...plan, weekStartDate: '2026-10-13' }, { ...plan, status: 'unknown' }, { ...plan, mode: 'unknown' },
    ...[['draft'], ['active'], ['archived'], {}, true, 1].map(status => ({ ...plan, status })),
    ...[['custom'], ['coach'], ['hybrid'], {}, false, 1].map(mode => ({ ...plan, mode })),
    ...[['training'], ['rest'], {}, true, 1].map(kind => ({ ...plan, days: [{ ...day, kind }] })),
    { ...plan, days: [day, { ...day, id: 'duplicate-date', assignments: [] }] },
    ...[{ date: '2026-10-11' }, { date: '2026-10-19' }, { dayOfWeek: 'Tuesday' }, { kind: 'rest' }, { kind: 'unknown' }].map(change => ({ ...plan, days: [{ ...day, ...change }] })),
    ...[{ time: '25:00' }, { time: '9am' }, { setsPerExercise: 0 }, { setsPerExercise: 21 }, { setsPerExercise: '3' }, { templateExerciseCount: -1 }, { templateExerciseCount: true }, { templateExerciseCount: 1.5 }].map(change => ({ ...plan, days: [{ ...day, assignments: [{ ...assignment, ...change }] }] })),
  ];
  for (const record of invalid) {
    const before = JSON.stringify(record);
    assert.match(importValidation.validatePlanningImport({ [key]: [record] }), /unsupported structure/);
    assert.equal(JSON.stringify(record), before);
  }
  const nextWeek = { ...plan, id: 'other', weekStartDate: '2026-10-19', days: [{ ...day, date: '2026-10-19', assignments: [] }] };
  assert.match(importValidation.validatePlanningImport({ [key]: [plan, nextWeek] }), /unsupported structure/, 'day identities cannot collide across weeks');
  for (const monday of ['2026-12-28', '2026-03-02', '2026-10-26']) {
    const sunday = new Date(`${monday}T12:00:00`); sunday.setDate(sunday.getDate() + 6);
    const valid = { ...plan, weekStartDate: monday, days: [{ ...day, date: dates.localDate(sunday), dayOfWeek: 'Sunday' }] };
    assert.equal(importValidation.validatePlanningImport({ [key]: [valid] }), null);
  }
});

test('generic plan saves reject invalid calendars and cross-week identities before activation or persistence', () => {
  goals.saveGoalsRecord(sampleGoals());
  const plan = plans.createWorkoutPlan({ status: 'active' }).plan;
  const original = store.planningSnapshot();
  const nextMonday = dates.localDate(new Date(`${plan.weekStartDate}T12:00:00`));
  const badDays = [
    [{ ...plan.days[0], date: '2026-02-30' }],
    [plan.days[0], { ...plan.days[1], date: plan.days[0].date }],
    [{ ...plan.days[0], dayOfWeek: 'Sunday' }],
    [{ ...plan.days[0], kind: 'rest', assignments: [{ id: 'invalid-rest', templateTitle: 'Workout' }] }],
    [{ ...plan.days[0], assignments: [{ id: 'invalid-time', templateTitle: 'Workout', time: '25:00' }] }],
  ];
  for (const days of badDays) {
    assert.throws(() => plans.updateWorkoutPlan(plan.id, { days, status: 'active' }), /Review the plan/);
    assert.equal(store.planningSnapshot(), original);
    const next = new Date(`${nextMonday}T12:00:00`); next.setDate(next.getDate() + 7);
    assert.throws(() => plans.createWorkoutPlan({ weekStartDate: dates.localDate(next), days, status: 'active' }), /Review the plan/);
    assert.equal(store.planningSnapshot(), original);
  }
  const second = plans.duplicatePlanToNextWeek(plan.id).plan;
  const beforeCollision = store.planningSnapshot();
  assert.throws(() => plans.updateWorkoutPlan(second.id, { days: [{ ...second.days[0], id: plan.days[0].id }] }), /Review the plan/);
  assert.equal(store.planningSnapshot(), beforeCollision);
  const partial = plans.updateWorkoutPlan(second.id, { days: [second.days[4], second.days[0]] }).plan;
  assert.deepEqual(partial.days.map(day => day.id), [second.days[4].id, second.days[0].id]);
  assert.equal(plans.getActiveWorkoutPlanId(), plan.id);
});

test('generic plan inputs reject explicit invalid defaults and cannot clear active status through legacy import tolerance', () => {
  goals.saveGoalsRecord(sampleGoals());
  const plan = plans.createWorkoutPlan({ status: 'active' }).plan;
  const nextDate = new Date(`${plan.weekStartDate}T12:00:00`); nextDate.setDate(nextDate.getDate() + 7);
  const invalidFields = [
    ...['', null, undefined, false, 0, [], ['active'], {}].map(status => ({ status })),
    ...['', null, undefined, false, 0, [], ['custom'], {}].map(mode => ({ mode })),
    ...[null, undefined, false, 0, {}, 'Monday'].map(days => ({ days })),
    ...[null, undefined, false, 0, [], {}].map(title => ({ title })),
  ];
  const original = store.planningSnapshot();
  for (const fields of invalidFields) {
    assert.throws(() => plans.createWorkoutPlan({ weekStartDate: dates.localDate(nextDate), ...fields }), /original weeks are preserved/);
    assert.equal(store.planningSnapshot(), original);
    assert.throws(() => plans.updateWorkoutPlan(plan.id, fields), /original weeks are preserved/);
    assert.equal(store.planningSnapshot(), original);
    assert.equal(plans.getActiveWorkoutPlanId(), plan.id);
    assert.equal(plans.getActiveWorkoutPlan().status, 'active');
  }
  for (const fields of [null, [], false]) {
    assert.throws(() => plans.createWorkoutPlan(fields), /original weeks are preserved/);
    assert.throws(() => plans.updateWorkoutPlan(plan.id, fields), /original weeks are preserved/);
    assert.equal(store.planningSnapshot(), original);
  }
  const defaults = plans.createWorkoutPlan({ weekStartDate: dates.localDate(nextDate) }).plan;
  assert.equal(defaults.status, 'draft'); assert.equal(defaults.mode, 'custom'); assert.equal(defaults.days.length, 7);
  assert.equal(plans.getActiveWorkoutPlanId(), plan.id);
  const changed = plans.updateWorkoutPlan(plan.id, { mode: 'coach', title: ' Reviewed plan ' }).plan;
  assert.equal(changed.mode, 'coach'); assert.equal(changed.title, 'Reviewed plan'); assert.equal(changed.status, 'active');
  assert.equal(plans.getActiveWorkoutPlanId(), plan.id);
});

test('hydration imports require literal supported units and preserve rejected originals', () => {
  const entry = { id: 'water', date: '2026-10-12', unit: 'ml', amount: 250, notes: '', recordedAt: '2026-10-12T08:00:00Z', updatedAt: '2026-10-12T08:00:00Z' };
  const draft = { id: 'draft', date: '', unit: 'ml', amount: '250', notes: '', baseVersion: null };
  for (const unit of ['ml', 'us-fl-oz']) {
    assert.equal(importValidation.validatePlanningImport({ soundFitnessHydrationEntries: [{ ...entry, unit, amount: unit === 'ml' ? 250 : 8 }], soundFitnessHydrationDraft: { ...draft, unit } }), null);
  }
  for (const unit of [['ml'], ['us-fl-oz'], {}, true, 1, '', null]) {
    for (const values of [{ soundFitnessHydrationEntries: [{ ...entry, unit }] }, { soundFitnessHydrationDraft: { ...draft, unit } }]) {
      const original = JSON.stringify(values);
      assert.match(importValidation.validatePlanningImport(values), /unsupported structure/);
      assert.equal(JSON.stringify(values), original);
    }
  }
});

test('duplicating partial and reordered weeks preserves weekday dates and source assignments', () => {
  goals.saveGoalsRecord(sampleGoals());
  const original = plans.createWorkoutPlan().plan;
  const assigned = plans.assignTemplateToPlanDay({ planId: original.id, dayId: original.days[4].id, template: saveAssignmentTemplateFixture({ id: 'template', title: 'Friday workout', exercises: [{ id: 'squat', name: 'Squat' }] }) }).plan;
  const partial = { ...assigned, days: [assigned.days[4], assigned.days[0], assigned.days[6]] };
  plans.writeWorkoutPlans([partial]);
  const before = JSON.stringify(partial);
  const duplicate = plans.duplicatePlanToNextWeek(partial.id).plan;
  assert.deepEqual(duplicate.days.map(day => day.dayOfWeek), ['Friday', 'Monday', 'Sunday']);
  partial.days.forEach((day, index) => {
    const next = new Date(`${day.date}T12:00:00`); next.setDate(next.getDate() + 7);
    assert.equal(duplicate.days[index].date, dates.localDate(next));
    assert.notEqual(duplicate.days[index].id, day.id);
  });
  assert.equal(duplicate.days[0].assignments[0].templateId, 'template');
  assert.notEqual(duplicate.days[0].assignments[0].id, partial.days[0].assignments[0].id);
  assert.equal(duplicate.days[0].assignments[0].time, partial.days[0].assignments[0].time);
  assert.equal(importValidation.validatePlanningImport({ [store.planningKeys.plans]: plans.readWorkoutPlans() }), null);
  assert.equal(JSON.stringify(plans.readWorkoutPlans().find(plan => plan.id === partial.id)), before);
  plans.writeWorkoutPlans([{ ...partial, days: [{ ...partial.days[0], dayOfWeek: 'Tuesday' }] }]);
  const snapshot = store.planningSnapshot();
  assert.throws(() => plans.duplicatePlanToNextWeek(partial.id), /saved dates and assignments/);
  assert.equal(store.planningSnapshot(), snapshot);
});

test('active plan reads require recorded active status and preserve stale pointers for explicit review', () => {
  goals.saveGoalsRecord(sampleGoals());
  const selected = plans.createWorkoutPlan({ status: 'active' }).plan;
  const other = plans.duplicatePlanToNextWeek(selected.id).plan;
  const originals = plans.readWorkoutPlans();
  for (const status of ['draft', 'archived', undefined, null, 'invalid']) {
    plans.writeWorkoutPlans(originals.map(plan => plan.id === selected.id ? { ...plan, status } : { ...plan, status: 'active' }));
    const before = store.planningSnapshot();
    assert.equal(plans.getActiveWorkoutPlan(), null);
    assert.equal(plans.getActiveWorkoutPlanId(), selected.id);
    assert.equal(store.planningSnapshot(), before);
  }
  plans.writeWorkoutPlans(originals);
  const before = store.planningSnapshot();
  assert.deepEqual(plans.getActiveWorkoutPlan(), selected);
  assert.equal(store.planningSnapshot(), before);
  store.writePlanning(store.planningKeys.active, 'missing');
  assert.equal(plans.getActiveWorkoutPlan(), null);
  store.writePlanning(store.planningKeys.active, other.id);
  assert.equal(plans.getActiveWorkoutPlan(), null);
  store.writePlanning(store.planningKeys.active, null);
  assert.equal(plans.getActiveWorkoutPlan(), null);
});

