test('plan activation stays atomic across creation, duplication, status changes, clearing, and quota failures', () => {
  goals.saveGoalsRecord(sampleGoals());
  const first = plans.createWorkoutPlan({ status: 'active' }).plan;
  assert.equal(plans.getActiveWorkoutPlanId(), first.id);
  assert.equal(plans.getActiveWorkoutPlan().status, 'active');
  const next = plans.duplicatePlanToNextWeek(first.id, { status: 'active' }).plan;
  assert.equal(plans.getActiveWorkoutPlanId(), next.id);
  assert.deepEqual(plans.readWorkoutPlans().filter(plan => plan.status === 'active').map(plan => plan.id), [next.id]);
  assert.equal(plans.readWorkoutPlans().find(plan => plan.id === first.id).status, 'draft');
  plans.updateWorkoutPlan(first.id, { status: 'active' });
  assert.equal(plans.getActiveWorkoutPlanId(), first.id);
  assert.deepEqual(plans.readWorkoutPlans().filter(plan => plan.status === 'active').map(plan => plan.id), [first.id]);
  plans.updateWorkoutPlan(first.id, { status: 'draft' });
  assert.equal(plans.getActiveWorkoutPlanId(), null);
  plans.setActiveWorkoutPlan(next.id);
  const before = store.planningSnapshot();
  failure = true;
  try {
    assert.throws(() => plans.clearActiveWorkoutPlan(), /Quota exceeded/);
    assert.equal(store.planningSnapshot(), before);
    assert.throws(() => plans.updateWorkoutPlan(first.id, { status: 'active' }), /Quota exceeded/);
    assert.equal(store.planningSnapshot(), before);
    assert.throws(() => plans.duplicatePlanToNextWeek(next.id, { status: 'active' }), /Quota exceeded/);
    assert.equal(store.planningSnapshot(), before);
  } finally { failure = false; }
  plans.clearActiveWorkoutPlan();
  assert.equal(plans.getActiveWorkoutPlanId(), null);
  assert.equal(plans.readWorkoutPlans().filter(plan => plan.status === 'active').length, 0);
});

test('clearing active selection preserves malformed original collections and avoids redundant writes', () => {
  goals.saveGoalsRecord(sampleGoals());
  const active = plans.createWorkoutPlan({ status: 'active' }).plan;
  const valid = plans.readWorkoutPlans();
  for (const value of [{ retained: 'original' }, 'original', false, [null],
    [{ ...active, days: active.days.map((day, index) => index === 0 ? { ...day, date: '2026-02-30' } : day) }],
    [active, { ...active, id: 'collision', status: 'archived' }]]) {
    store.writePlanning(store.planningKeys.plans, value);
    const before = store.planningSnapshot();
    assert.throws(() => plans.clearActiveWorkoutPlan(), /original weeks are preserved/);
    assert.equal(store.planningSnapshot(), before);
    assert.equal(plans.getActiveWorkoutPlanId(), active.id);
  }
  plans.writeWorkoutPlans(valid);
  const unrelated = { retained: true };
  store.writePlanning('unrelated', unrelated);
  plans.clearActiveWorkoutPlan();
  assert.equal(plans.getActiveWorkoutPlanId(), null);
  assert.equal(plans.readWorkoutPlans()[0].status, 'draft');
  assert.deepEqual(plans.readWorkoutPlans()[0].days, active.days);
  assert.equal(store.planningSnapshot().unrelated, unrelated);
  const cleared = store.planningSnapshot();
  failure = true;
  try { plans.clearActiveWorkoutPlan(); assert.equal(store.planningSnapshot(), cleared); }
  finally { failure = false; }
});

test('activation and duplication refuse invalid collections or explicit states without changing the active pointer', () => {
  goals.saveGoalsRecord(sampleGoals());
  const first = plans.createWorkoutPlan({ status: 'active' }).plan;
  const second = plans.duplicatePlanToNextWeek(first.id).plan;
  const valid = plans.readWorkoutPlans();
  for (const status of ['', null, false, 0, ['active'], 'unknown']) {
    const before = store.planningSnapshot();
    assert.throws(() => plans.duplicatePlanToNextWeek(second.id, { status }), /original weeks are preserved/);
    assert.equal(store.planningSnapshot(), before);
    assert.equal(plans.getActiveWorkoutPlanId(), first.id);
  }
  const invalidCollections = [
    valid.map(item => item.id === second.id ? { ...item, status: 'invalid' } : item),
    valid.map(item => item.id === second.id ? { ...item, days: item.days.map((day, index) => index === 0 ? { ...day, date: '2026-02-30' } : day) } : item),
    [...valid, { ...first, id: 'duplicate-week', status: 'draft', days: first.days.map(day => ({ ...day, id: `duplicate-${day.id}` })) }],
    valid.map(item => item.id === second.id ? { ...item, days: item.days.map((day, index) => index === 0 ? { ...day, id: first.days[0].id } : day) } : item),
  ];
  for (const collection of invalidCollections) {
    plans.writeWorkoutPlans(collection);
    const before = store.planningSnapshot();
    assert.throws(() => plans.setActiveWorkoutPlan(second.id), /original weeks are preserved/);
    assert.equal(store.planningSnapshot(), before);
    assert.equal(plans.getActiveWorkoutPlanId(), first.id);
    assert.throws(() => plans.duplicatePlanToNextWeek(second.id), /saved dates and assignments/);
    assert.equal(store.planningSnapshot(), before);
  }
  plans.writeWorkoutPlans(valid);
  plans.setActiveWorkoutPlan(second.id);
  assert.equal(plans.getActiveWorkoutPlanId(), second.id);
  assert.deepEqual(plans.readWorkoutPlans().filter(item => item.status === 'active').map(item => item.id), [second.id]);
});

test('configured plan save commits schedule, suggested workouts, and activation together or preserves the original', () => {
  goals.saveGoalsRecord(sampleGoals());
  const settings = { split: 'Full Body', weeklyTarget: '2 workouts', primaryFocus: 'Strength', secondaryFocus: 'Mobility', progression: 'Double Progression', phase: 'Foundation', notes: 'Saved rules' };
  const template = { id: 'bodyweight', title: 'Strength', exercises: [{ id: 'squat', name: 'Squat', equipment: 'Bodyweight' }], createdAt: '2026-10-12', updatedAt: '2026-10-12' };
  store.writePlanning(store.planningKeys.templates, [template]);
  const input = { planId: null, title: 'Configured week', goal: 'Strength', weekStartDate: dates.localDate(), settings,
    trainingDays: [{ day: 'Monday', focus: 'Strength', notes: 'First' }, { day: 'Friday', focus: 'Strength', notes: 'Second' }],
    editor: plans.capturePlanEditor(), assignMatches: true, templates: [template], profile: {} };
  let before = store.planningSnapshot();
  failure = true;
  try { assert.throws(() => plans.saveWorkoutPlanConfiguration(input), /Quota exceeded/); assert.equal(store.planningSnapshot(), before); }
  finally { failure = false; }
  const saved = plans.saveWorkoutPlanConfiguration(input).plan;
  assert.equal(plans.readWorkoutPlans().length, 1); assert.equal(plans.getActiveWorkoutPlanId(), saved.id);
  assert.equal(saved.status, 'active'); assert.deepEqual(saved.settings, settings);
  assert.deepEqual(saved.days.filter(day => day.kind === 'training').map(day => day.dayOfWeek), ['Monday', 'Friday']);
  assert.equal(saved.days.flatMap(day => day.assignments).length, 2);
  assert.equal(saved.days[0].assignments[0].templateId, template.id);
  logs.recordPlanningLog({ id: 'completed-monday', assignmentId: saved.days[0].assignments[0].id, title: 'Strength', completedAt: '2026-10-12', entries: [] });
  const edit = { ...input, planId: saved.id, title: 'Changed rules', settings: { ...settings, weeklyTarget: '1 workout' }, editor: plans.capturePlanEditor(saved), trainingDays: [{ day: 'Friday', focus: 'Strength', notes: 'Changed' }] };
  before = store.planningSnapshot(); failure = true;
  try { assert.throws(() => plans.saveWorkoutPlanConfiguration(edit), /Quota exceeded/); assert.equal(store.planningSnapshot(), before); }
  finally { failure = false; }
  const updated = plans.saveWorkoutPlanConfiguration(edit).plan;
  assert.equal(updated.days[0].kind, 'training'); assert.deepEqual(updated.days[0].assignments, saved.days[0].assignments);
  assert.equal(updated.title, 'Changed rules');
  const stale = { ...edit, editor: plans.capturePlanEditor(updated) };
  store.writePlanning(store.planningKeys.goals, { ...goals.readGoals(), targetWeeklySets: '48' });
  before = store.planningSnapshot();
  assert.throws(() => plans.saveWorkoutPlanConfiguration(stale), /Goals changed since this editor/);
  assert.equal(store.planningSnapshot(), before);
  assert.throws(() => plans.saveWorkoutPlanConfiguration({ ...stale, editor: plans.capturePlanEditor(), planId: 'deleted' }), /no longer available/);
});

