test('damaged device caches retain exact originals until a valid cloud copy can recover them', async () => {
  for (const raw of ['invalid JSON', JSON.stringify({ values: { [store.planningKeys.logs]: [{}] }, revision: 0, dirty: true })]) {
    storage.clear(); storage.set('soundFitnessPlanning:v1:member', raw);
    cloud = { data: null, error: new Error('Offline') };
    await store.initializePlanning('member');
    assert.throws(() => store.writePlanning('draft', 'replacement'), /needs recovery/);
    assert.throws(() => store.exportPlanningBackup('member', new Date(), store.planningAccountGeneration()), /needs recovery/, 'damaged originals cannot be misrepresented by an empty export');
    assert.equal(storage.get('soundFitnessPlanning:v1:member'), raw);
    cloud = { data: { payload: { draft: 'recovered' }, revision: 3 }, error: null };
    await store.syncPlanning();
    assert.equal(store.readPlanning('draft', ''), 'recovered');
    assert.equal(JSON.parse(store.exportPlanningBackup('member', new Date(), store.planningAccountGeneration())).values.draft, 'recovered');
    assert.ok([...storage.entries()].some(([key, value]) => key.includes(':invalid-backup:') && value === raw));
  }
});

