test('exercise set summaries use canonical completions and preserve unknown exercise identity without inferring volume', () => {
  const now = new Date(2026, 9, 14, 12);
  const entry = (exerciseId, exerciseName, sets) => ({ exerciseId, exerciseName, sets });
  const row = (id, date, entries) => ({ id, title: 'Workout', completedAt: date, entries });
  const records = [
    row('newer', '2026-10-14', [entry('squat', 'Renamed squat', '3'), entry('', 'Walk', '2'), entry('', '', '1'), entry('', '', '2')]),
    row('older', '2026-10-12', [entry('squat', 'Old squat', '4'), entry('', 'Walk', '1'), entry('invalid', 'Invalid', true), entry('fraction', 'Fraction', '1.5')]),
    row('newer', '2026-10-13', [entry('duplicate', 'Duplicate', '999')]),
    row('future', '2026-10-15', [entry('future', 'Future', '999')]),
    row('outside', '2026-10-11', [entry('outside', 'Outside', '999')]),
  ];
  const before = JSON.stringify(records);
  const summary = history.workoutExerciseSetSummary(records, '2026-10-12', '2026-10-18', now);
  assert.deepEqual(summary.map(item => [item.name, item.sets]), [['Renamed squat', 7], ['Walk', 3], ['Unnamed exercise', 2], ['Unnamed exercise', 1]]);
  assert.equal(summary[0].lastCompletedAt, '2026-10-14');
  assert.equal(new Set(summary.map(item => item.id)).size, summary.length);
  assert.equal(summary.reduce((sum, item) => sum + item.sets, 0), 13);
  assert.ok(summary.every(item => !Object.hasOwn(item, 'volume') && !Object.hasOwn(item, 'readiness')));
  assert.equal(JSON.stringify(records), before);
  assert.throws(() => history.workoutExerciseSetSummary(records, '2026-10-18', '2026-10-12', now), /valid date range/);
});

