test('template conflict choices preserve both versions and rebase only the selected local edit', () => {
  for (const preferred of ['local', 'cloud']) {
    store.writePlanning(store.planningKeys.templates, []);
    const local = persistence.saveWorkoutTemplateToLocalStorage({ id: 'original', title: 'Local workout', exercises: [{ id: 'squat', name: 'Squat' }], createdAt: '', updatedAt: '', cloudRevision: 1 }).data;
    const cloudVersion = { ...local, title: 'Cloud workout', exercises: [{ id: 'row', name: 'Row' }], cloudRevision: 3, syncPending: false };
    const review = { account: store.planningOwner(), generation: store.planningAccountGeneration(), local, cloud: cloudVersion };
    persistence.resolveWorkoutTemplateConflict(review, preferred);
    const versions = store.readPlanning(store.planningKeys.templates, []);
    assert.equal(versions.length, 2);
    const original = versions.find(item => item.id === 'original');
    const backup = versions.find(item => item.id !== 'original');
    assert.equal(original.title, preferred === 'local' ? 'Local workout' : 'Cloud workout');
    assert.equal(original.cloudRevision, 3); assert.equal(original.syncPending, preferred === 'local');
    assert.equal(backup.syncPending, true); assert.equal(backup.cloudRevision, 0);
    assert.equal(backup.exercises[0].id, preferred === 'local' ? 'row' : 'squat');
    assert.notEqual(backup.syncKey, original.syncKey);
    assert.throws(() => persistence.resolveWorkoutTemplateConflict(review, preferred), /changed/);
  }
});

