test('Stats exercise volume includes canonical cloud completions without duplicating local completion copies', () => {
  const account = store.planningOwner();
  const local = { exerciseId: 'squat', exerciseName: 'Squat', date: '2026-10-12T10:00:00Z', weight: '20', reps: '10', sets: '2', source: 'workout-session' };
  const remote = { exerciseId: 'row', exerciseName: 'Row', date: '2026-10-12T11:00:00Z', weight: '40', reps: '8', sets: '3', source: 'workout-session' };
  const standalone = { ...local, weight: '10', reps: '5', sets: '1', source: 'exercise-library' };
  const localLog = { id: 'local-volume', cloudLogId: 'cloud-local-volume', title: 'Local', completedAt: local.date, entries: [local] };
  store.writePlanning(store.planningKeys.logs, [localLog]); store.writePlanning(store.planningKeys.exerciseStats, [local, standalone]);
  availableLogs.publishCloudHistory(account, [{ ...localLog, id: 'cloud-local-volume', entries: [{ ...local }] }, { id: 'remote-volume', title: 'Cloud', completedAt: remote.date, entries: [remote] }], 'Loaded');
  const snapshot = store.planningSnapshot(); const cloud = JSON.stringify(availableLogs.cloudHistorySnapshot());
  const merged = statsSource.mergeStatsExerciseEntries(store.readPlanning(store.planningKeys.exerciseStats, []));
  assert.equal(merged.length, 3); assert.equal(merged[0], local); assert.equal(merged[1], standalone); assert.deepEqual(merged[2], remote); assert.notEqual(merged[2], remote);
  assert.equal(merged.reduce((total, entry) => total + Number(entry.sets), 0), 6);
  assert.equal(merged.reduce((total, entry) => total + Number(entry.sets) * Number(entry.reps) * Number(entry.weight), 0), 1410);
  assert.equal(store.planningSnapshot(), snapshot); assert.equal(JSON.stringify(availableLogs.cloudHistorySnapshot()), cloud);
});

test('Stats exercise merging matches occurrences and numeric/timestamp representations without collapsing distinct sources or unknown load', () => {
  const entry = { exerciseId: 'row', exerciseName: 'Row', date: '2026-10-12T11:00:00Z', weight: '0', reps: '8', sets: '3', source: 'workout-session' };
  const equivalent = { ...entry, exerciseName: ' ROW ', date: '2026-10-12T11:00:00+00:00', weight: 0, reps: 8, sets: 3, source: undefined };
  const log = { id: 'occurrences', title: 'Repeated rows', completedAt: entry.date, entries: [equivalent, equivalent] };
  const saved = [entry]; const original = JSON.stringify({ saved, log });
  const repeated = statsSource.mergeStatsExerciseEntries(saved, [log]); assert.equal(repeated.length, 2); assert.equal(repeated[0], entry); assert.equal(repeated[1], equivalent);
  assert.equal(statsSource.mergeStatsExerciseEntries([entry, entry], [log]).length, 2);
  for (const change of [{ weight: '' }, { weight: false }, { weight: '1' }, { source: 'exercise-library' }, { date: '2026-10-12T11:01:00Z' }, { exerciseId: 'different-row' }]) {
    assert.equal(statsSource.mergeStatsExerciseEntries([entry], [{ ...log, entries: [{ ...equivalent, ...change }] }]).length, 2);
  }
  assert.equal(statsSource.mergeStatsExerciseEntries([null], [{ ...log, entries: [null] }]).length, 2, 'malformed originals remain inspectable');
  assert.equal(JSON.stringify({ saved, log }), original);
});

