test('Stats reporting weeks match Monday-start check-ins across DST, Sundays and year boundaries', () => {
  const previous = process.env.TZ;
  try {
    for (const zone of ['America/Los_Angeles', 'America/New_York', 'UTC']) {
      process.env.TZ = zone;
      for (const [date, start, end] of [['2026-03-08', '2026-03-02', '2026-03-08'], ['2026-03-09', '2026-03-09', '2026-03-15'], ['2026-11-01', '2026-10-26', '2026-11-01'], ['2026-11-02', '2026-11-02', '2026-11-08'], ['2027-01-01', '2026-12-28', '2027-01-03']]) {
        const now = new Date(`${date}T12:00:00`); const original = now.getTime();
        const bounds = statsEvidence.statsWeekBounds(now);
        assert.equal(dates.localDate(bounds.start), start, zone); assert.equal(dates.localDate(bounds.end), end, zone);
        assert.equal(bounds.start.getDay(), 1); assert.equal(bounds.start.getHours(), 0); assert.equal(bounds.end.getDay(), 0); assert.equal(bounds.end.getHours(), 23);
        assert.equal(checkIns.checkInWeek(now), start); assert.equal(now.getTime(), original);
      }
    }
  } finally { if (previous === undefined) delete process.env.TZ; else process.env.TZ = previous; }
});

test('Stats history windows use local calendar boundaries and exclude future or invalid times', () => {
  const previous = process.env.TZ;
  try {
    for (const zone of ['America/Los_Angeles', 'America/New_York', 'UTC']) {
      process.env.TZ = zone; const now = new Date('2026-11-02T12:00:00'); const stamp = date => new Date(date + 'T00:00:00').getTime();
      assert.equal(statsEvidence.statsHistoryIncludes(stamp('2026-11-02'), 'This week', now), true);
      assert.equal(statsEvidence.statsHistoryIncludes(stamp('2026-11-01'), 'This week', now), false);
      assert.equal(statsEvidence.statsHistoryIncludes(stamp('2026-10-04'), 'Last 30 days', now), true);
      assert.equal(statsEvidence.statsHistoryIncludes(stamp('2026-10-03'), 'Last 30 days', now), false);
      assert.equal(statsEvidence.statsHistoryIncludes(stamp('2025-01-01'), 'Lifetime', now), true);
      for (const filter of ['This week', 'Last 30 days', 'Lifetime']) for (const timestamp of [now.getTime() + 1, NaN, Infinity, -1e20, false, true, '0', [], null]) assert.equal(statsEvidence.statsHistoryIncludes(timestamp, filter, now), false);
    }
  } finally { if (previous === undefined) delete process.env.TZ; else process.env.TZ = previous; }
});

test('Stats streaks count consecutive reported local days through DST and year changes', () => {
  const previous = process.env.TZ;
  try {
    for (const zone of ['America/Los_Angeles', 'America/New_York', 'UTC']) {
      process.env.TZ = zone;
      for (const days of [['2026-03-07', '2026-03-08', '2026-03-09'], ['2026-10-31', '2026-11-01', '2026-11-02'], ['2026-12-31', '2027-01-01', '2027-01-02']]) {
        const timestamps = days.map(day => new Date(day + 'T10:00:00').getTime()); const original = JSON.stringify(timestamps); const now = new Date(days[2] + 'T12:00:00');
        assert.equal(statsEvidence.statsCurrentStreak([...timestamps, timestamps[0], now.getTime() + 1000, NaN], now), 3, zone);
        assert.equal(statsEvidence.statsCurrentStreak(timestamps.slice(0, 2), now), 2, zone);
        assert.equal(statsEvidence.statsCurrentStreak([timestamps[0]], now), 0, zone);
        assert.equal(JSON.stringify(timestamps), original);
      }
    }
  } finally { if (previous === undefined) delete process.env.TZ; else process.env.TZ = previous; }
});

