test('Stats volume increases require a real prior date for the same exercise and variation', () => {
  const now = new Date('2026-10-12T18:00:00Z');
  const base = { exerciseId: 'bench', exerciseName: 'Bench Press', timestamp: now.getTime() - 1000, volume: 100 };
  assert.deepEqual(statsEvidence.statsVolumeIncreases([base], now), []);
  assert.deepEqual(statsEvidence.statsVolumeIncreases([base, { ...base, volume: 200 }], now), [], 'same-date rows are one measurement');
  for (const patch of [{ exerciseId: 'dumbbell-bench' }, { exerciseName: 'Incline Bench Press' }]) assert.deepEqual(statsEvidence.statsVolumeIncreases([base, { ...base, ...patch, timestamp: now.getTime(), volume: 200 }], now), []);
  const later = { ...base, timestamp: now.getTime(), volume: 150 };
  assert.deepEqual(statsEvidence.statsVolumeIncreases([later, base], now), [{ exerciseName: base.exerciseName, change: 50, latestAt: later.timestamp, previousAt: base.timestamp, latestVolume: 150, previousVolume: 100 }]);
});

