test('Stats volume increase cannot skip a latest decline or substitute unknown zero and invalid volume', () => {
  const now = new Date('2026-10-12T18:00:00Z');
  const base = { exerciseId: 'lift', exerciseName: 'Lift', timestamp: now.getTime() - 2000, volume: 100 };
  const previous = { ...base, timestamp: now.getTime() - 1000, volume: 200 };
  for (const volume of [0, -1, NaN, Infinity, 150, 200]) assert.deepEqual(statsEvidence.statsVolumeIncreases([base, previous, { ...base, timestamp: now.getTime(), volume }], now), []);
  assert.deepEqual(statsEvidence.statsVolumeIncreases([{ ...base, volume: 0 }, previous], now), []);
  assert.deepEqual(statsEvidence.statsVolumeIncreases([base, { ...previous, timestamp: now.getTime() + 1 }], now), []);
});

