test('canonical load units round-trip locally and through set mapping without assigning units to older records', () => {
  const date = new Date().toISOString(); const base = { exerciseId: 'squat', exerciseName: 'Squat', date, sets: '3', reps: '8', weight: '0' };
  for (const weightUnit of ['lb', 'kg']) {
    const entry = { ...base, weightUnit }; const original = JSON.stringify(entry);
    const result = persistence.saveCompletedWorkoutLogToLocalStorage({ sessionId: 'unit-' + weightUnit, title: 'Workout', completedAt: date, entries: [entry] });
    assert.equal(result.success, true); assert.equal(result.data.entries[0].weightUnit, weightUnit);
    const mapped = persistence.mapLocalStatEntryToSetLogInsert(entry, 'log', 'member', 0);
    assert.equal(mapped.weight_unit, weightUnit); assert.equal(mapped.weight, 0);
    const restored = persistence.mapSetLogRowToLocalStatEntry({ ...mapped, id: 'set', performed_at: date });
    assert.equal(restored.weightUnit, weightUnit); assert.equal(restored.weight, '0');
    assert.deepEqual(statsEvidence.statsExerciseMetrics(entry), { sets: 3, reps: 8, weight: 0 });
    assert.deepEqual(history.workoutEntryIssues(entry), []); assert.equal(history.workoutRecordedLoad(entry), '0 ' + weightUnit);
    assert.equal(JSON.stringify(entry), original);
  }
  const mapped = persistence.mapLocalStatEntryToSetLogInsert(base, 'log', 'member', 0);
  assert.equal(Object.hasOwn(mapped, 'weight_unit'), false);
  assert.equal(Object.hasOwn(persistence.mapSetLogRowToLocalStatEntry({ ...mapped, id: 'old', weight_unit: null }), 'weightUnit'), false);
  assert.equal(history.workoutRecordedLoad(base), '0 (unit not recorded)');
});

test('cloud exercise merging preserves distinct and malformed unit evidence without changing originals', async () => {
  authUser = { id: 'unit-merge-member' }; await store.initializePlanning(authUser.id);
  const date = new Date().toISOString();
  const base = { exerciseId: 'squat', exerciseName: 'Squat', date, sets: '3', reps: '8', weight: '20', source: 'workout-session' };
  const local = [{ ...base, weightUnit: 'KG' }, { ...base, weightUnit: 'lb' }, { ...base }];
  store.writePlanning(store.planningKeys.exerciseStats, local); const original = store.planningSnapshot();
  const previousFrom = fakeSupabase.from;
  try {
    fakeSupabase.from = table => {
      if (table === 'planning_documents') return previousFrom(table);
      let after = false;
      return { select() { return this; }, eq() { return this; }, order() { return this; }, limit() { return this; }, in() { return this; }, gt() { after = true; return this; }, abortSignal() {
        const rows = table === 'workout_logs' ? [{ id: 'cloud-log', profile_id: authUser.id, completed_at: date }] : [{ id: 'cloud-set', workout_log_id: 'cloud-log', profile_id: authUser.id, exercise_id: 'squat', exercise_name: 'Squat', weight: 20, weight_unit: 'kg', reps: 8, sets: 3, performed_at: date, source: 'workout-session', order_index: 0 }];
        return Promise.resolve({ data: after ? [] : rows, error: null });
      } };
    };
    const result = await persistence.loadWorkoutLogEntriesWithFallback();
    assert.equal(result.success, true); assert.equal(result.data.length, 4);
    assert.deepEqual(new Set(result.data.map(entry => entry.weightUnit)), new Set(['kg', 'KG', 'lb', undefined]));
    assert.equal(store.planningSnapshot(), original);
  } finally { fakeSupabase.from = previousFrom; }
});

test('explicit unit uploads require confirmed backend capability and preserve payload units', async () => {
  authUser = { id: 'unit-capability-member' }; await store.initializePlanning(authUser.id);
  const date = new Date().toISOString(); const entry = { exerciseId: 'squat', exerciseName: 'Squat', date, sets: '3', reps: '8', weight: '20', weightUnit: 'kg' };
  const input = { sessionId: 'unit-capability', title: 'Workout', completedAt: date, entries: [entry] };
  assert.equal(persistence.saveCompletedWorkoutLogToLocalStorage(input).success, true);
  const original = store.planningSnapshot();
  for (const support of [{ data: null, error: { message: 'Function missing' } }, { data: 0, error: null }, { data: '1', error: null }, { data: 2, error: null }]) {
    const calls = []; save = async (name, payload) => { if (name === 'save_planning_document') return { data: 1, error: null }; calls.push({ name, payload }); return support; };
    const result = await persistence.saveCompletedWorkoutLogToSupabase(input);
    assert.equal(result.success, false); assert.match(result.error, /load-unit support is unavailable/);
    assert.deepEqual(calls.map(call => call.name), ['planning_workout_load_unit_version']);
    assert.equal(store.planningSnapshot(), original); assert.equal(result.data.entries[0].weightUnit, 'kg');
  }
  const calls = []; save = async (name, payload) => {
    if (name === 'save_planning_document') return { data: 1, error: null };
    calls.push({ name, payload }); return { data: name === 'planning_workout_load_unit_version' ? 1 : '22222222-3333-4444-8555-666666666666', error: null };
  };
  const result = await persistence.saveCompletedWorkoutLogToSupabase(input);
  assert.equal(result.success, true); assert.deepEqual(calls.map(call => call.name), ['planning_workout_load_unit_version', 'save_completed_planning_workout']);
  assert.equal(calls[1].payload.set_payloads[0].weight, 20); assert.equal(calls[1].payload.set_payloads[0].weight_unit, 'kg');
  assert.equal(store.planningSnapshot(), original);
});

