test('Stats exercise metrics reject malformed, fractional counts and conflicting aliases without rounding', () => {
  const base = { sets: '3', reps: '8', weight: '12.5' }; const original = JSON.stringify(base);
  assert.deepEqual(statsEvidence.statsExerciseMetrics(base), { sets: 3, reps: 8, weight: 12.5 });
  assert.equal(JSON.stringify(base), original);
  for (const value of [true, false, [], {}, '12oops', '1,000', '0x10', '-1', Infinity]) {
    for (const field of ['sets', 'reps', 'weight']) assert.equal(statsEvidence.statsExerciseMetrics({ ...base, [field]: value }), null, field + ': ' + String(value));
  }
  for (const field of ['sets', 'reps']) {
    assert.equal(statsEvidence.statsExerciseMetrics({ ...base, [field]: '1.5' }), null);
    assert.equal(statsEvidence.statsExerciseMetrics({ ...base, [field]: Number.MAX_SAFE_INTEGER + 1 }), null);
  }
  assert.equal(statsEvidence.statsExerciseMetrics({ ...base, setCount: 4 }), null);
  assert.equal(statsEvidence.statsExerciseMetrics({ ...base, weight: '1e308' }), null, 'volume overflow is not recorded work');
});

