test('Stats exercise records keep lifts and variations separate instead of matching movement patterns', () => {
  const now = new Date('2026-10-12T13:00:00Z');
  const base = { exerciseId: 'bench', exerciseName: 'Bench Press', weight: 100, weightUnit: 'lb', reps: 5, timestamp: now.getTime() - 1000 };
  const heavier = { ...base, weight: 120, reps: 3, timestamp: now.getTime() - 2000 };
  const moreReps = { ...base, weight: 80, reps: 10 };
  const pushup = { ...base, exerciseId: 'pushup', exerciseName: 'Push-Up', weight: 0, reps: 30 };
  const pulldown = { ...base, exerciseId: 'pulldown', exerciseName: 'Lat Pulldown', weight: 200, reps: 12 };
  const pullup = { ...base, exerciseId: 'pullup', exerciseName: 'Pull-Up', weight: 0, reps: 4 };
  const original = [base, heavier, moreReps, pushup, pulldown, pullup]; const before = JSON.stringify(original);
  const records = statsEvidence.statsExerciseRecords(original, now);
  assert.equal(records.length, 4); assert.equal(records[0].load, heavier); assert.equal(records[0].reps, moreReps);
  assert.equal(records[1].load, null); assert.equal(records[1].reps, pushup);
  assert.equal(records[2].load, pulldown); assert.equal(records[3].reps, pullup);
  assert.equal(JSON.stringify(original), before);
  const variants = statsEvidence.statsExerciseRecords([base, { ...base, exerciseName: 'Incline Bench Press' }, { ...base, exerciseId: 'dumbbell-bench' }], now);
  assert.equal(variants.length, 3);
});

