test('unit-aware workload reports known subsets, measured zero and unknown data separately', () => {
  const now = new Date(2026, 9, 12, 12); const timestamp = now.getTime();
  const entries = [
    { timestamp, sets: 3, reps: 8, recordedLoadInPounds: 50 },
    { timestamp, sets: 2, reps: 10, recordedLoadInPounds: 10 / 0.45359237 },
    { timestamp, sets: 3, reps: 8, recordedLoadInPounds: null },
    { timestamp, sets: 3, reps: 8, recordedLoadInPounds: 0 },
  ];
  const json = JSON.stringify(entries); const summary = unitWorkload.unitWorkloadSummary(entries, 'This week', now);
  assert.equal(summary.knownEntries, 3); assert.equal(summary.unknownEntries, 1); assert.equal(summary.eligibleEntries, 4); assert.equal(summary.complete, false);
  assert.ok(Math.abs(summary.volumePounds * 0.45359237 - 744.310844) < 1e-9);
  assert.equal(unitWorkload.unitWorkloadLabel(summary, 'kg'), '744.31 kg·reps');
  const zero = unitWorkload.unitWorkloadSummary([entries[3]], 'Lifetime', now);
  assert.equal(zero.complete, true); assert.equal(zero.volumePounds, 0); assert.equal(unitWorkload.unitWorkloadLabel(zero, 'lb'), '0 lb·reps');
  const unknown = unitWorkload.unitWorkloadSummary([entries[2]], 'Lifetime', now);
  assert.equal(unknown.volumePounds, null); assert.equal(unitWorkload.unitWorkloadLabel(unknown, 'lb'), 'Unavailable');
  assert.equal(unitWorkload.unitWorkloadSummary([], 'This week', now).volumePounds, null);
  assert.equal(JSON.stringify(entries), json);
});

test('unit workload follows local planning weeks, excludes future dates, and refuses missing counts or overflow', () => {
  const now = new Date(2026, 9, 12, 12); const base = { timestamp: now.getTime(), sets: 1, reps: 1, recordedLoadInPounds: 20 };
  const old = { ...base, timestamp: new Date(2026, 9, 4, 12).getTime() };
  const future = { ...base, timestamp: now.getTime() + 1 };
  assert.equal(unitWorkload.unitWorkloadSummary([base, old, future], 'This week', now).eligibleEntries, 1);
  assert.equal(unitWorkload.unitWorkloadSummary([base, old, future], 'Lifetime', now).eligibleEntries, 2);
  for (const patch of [{ sets: 0 }, { reps: 0 }, { sets: 1.5 }, { reps: Infinity }, { recordedLoadInPounds: NaN }, { recordedLoadInPounds: -1 }, { recordedLoadInPounds: null }]) {
    const summary = unitWorkload.unitWorkloadSummary([{ ...base, ...patch }], 'Lifetime', now);
    assert.equal(summary.knownEntries, 0); assert.equal(summary.unknownEntries, 1); assert.equal(summary.volumePounds, null);
  }
  const overflow = unitWorkload.unitWorkloadSummary([{ ...base, recordedLoadInPounds: 1e308 }, { ...base, recordedLoadInPounds: 1e308 }], 'Lifetime', now);
  assert.equal(overflow.overflow, true); assert.equal(overflow.volumePounds, null); assert.equal(overflow.complete, false);
});

