test('Stats date-only evidence follows local days across DST and year boundaries', () => {
  const previous = process.env.TZ;
  try {
    for (const zone of ['America/Los_Angeles', 'America/New_York', 'UTC']) {
      process.env.TZ = zone;
      for (const date of ['2026-03-08', '2026-11-01', '2026-12-31', '2027-01-01']) {
        const now = new Date(`${date}T12:00:00`);
        const timestamp = statsEvidence.statsRecordedTimestamp(date, now);
        assert.equal(dates.localDate(new Date(timestamp)), date, zone);
        assert.equal(new Date(timestamp).getHours(), 0, zone);
      }
    }
  } finally { if (previous === undefined) delete process.env.TZ; else process.env.TZ = previous; }
});

