test('cloud assignment conflicts preserve local completions and drafts without upload acknowledgement or blocking other queued workouts', async () => {
  authUser = { id: 'completion-conflict-member' }; await store.initializePlanning(authUser.id);
  const input = { sessionId: 'conflicting-session', assignmentId: 'already-saved-assignment', title: 'Device workout', completedAt: '2026-10-12T12:00:00Z', entries: [{ exerciseId: 'squat', exerciseName: 'Squat', sets: '3', reps: '8', weight: '20', date: '2026-10-12T12:00:00Z' }] };
  const draft = { id: input.sessionId, logs: { 2: { sets: '3', reps: '8', weight: '20' } } };
  store.writePlanning('loggerDraft:default', draft);
  const uploaded = [];
  save = async (name, payload) => {
    if (name === 'save_planning_document') return { data: 1, error: null };
    uploaded.push(payload.session_key);
    return payload.session_key === input.sessionId ? { data: null, error: { code: '23505', message: 'This plan assignment was already completed by another session. Refresh History before reconciling.' } } : { data: '33333333-3333-4333-8333-333333333333', error: null };
  };
  const result = await persistence.saveCompletedWorkoutLogWithFallback(input);
  assert.equal(result.success, false); assert.equal(result.conflict, true); assert.match(result.error, /another session/);
  let saved = logs.readPlanningLogs().find(log => log.id === input.sessionId);
  assert.deepEqual(saved.entries, input.entries.map(entry => ({ ...entry, source: 'workout-session' }))); assert.equal(saved.cloudLogId, undefined); assert.equal(saved.syncedAt, undefined); assert.match(saved.syncError, /another session/);
  assert.deepEqual(store.readPlanning('loggerDraft:default', null), draft);
  logs.recordPlanningLog({ id: 'independent-queued-session', title: 'Another workout', completedAt: input.completedAt, entries: input.entries });
  await persistence.syncPendingPlanningWorkouts();
  saved = logs.readPlanningLogs().find(log => log.id === input.sessionId);
  assert.equal(logs.planningLogUploadConfirmed(saved), false);
  assert.equal(logs.planningLogUploadConfirmed(logs.readPlanningLogs().find(log => log.id === 'independent-queued-session')), true);
  assert.deepEqual(uploaded, [input.sessionId, input.sessionId, 'independent-queued-session']);
  assert.deepEqual(store.readPlanning('loggerDraft:default', null), draft);
});

