test('history ignores late parent and set responses instead of merging them into another account', async () => {
  const previousFrom = fakeSupabase.from;
  try {
    for (const delayed of ['workout_logs', 'workout_set_logs']) {
      authUser = { id: 'first' }; await store.initializePlanning('first');
      let finish; const filters = []; const cursors = {};
      const rows = table => table === 'workout_logs' ? [{ id: 'old-log', profile_id: 'first' }] : [{ id: 'old-set', workout_log_id: 'old-log', profile_id: 'first', exercise_name: 'Private old workout', performed_at: '2026-10-12', sets: 3 }];
      fakeSupabase.from = table => table === 'planning_documents' ? previousFrom(table) : ({ select() { return this; }, eq(key, value) { filters.push([table, key, value]); return this; }, in() { return this; }, order() { return this; }, limit() { return this; }, gt(key, value) { cursors[table] = value; return this; }, abortSignal(signal) {
        assert.ok(signal instanceof AbortSignal);
        return table === delayed ? new Promise(resolve => { finish = () => resolve({ data: rows(table), error: null }); }) : Promise.resolve({ data: cursors[table] ? [] : rows(table), error: null });
      } });
      const pending = persistence.loadWorkoutLogEntriesWithFallback();
      await new Promise(resolve => setImmediate(resolve));
      authUser = { id: 'second' }; await store.initializePlanning('second');
      store.writePlanning(store.planningKeys.exerciseStats, [{ exerciseId: 'walk', exerciseName: 'Current account', date: '2026-10-13', sets: '1' }]);
      finish();
      const result = await pending;
      assert.equal(result.success, false); assert.deepEqual(result.data, []); assert.match(result.error, /Account changed/);
      if (delayed === 'workout_set_logs') assert.ok(filters.some(([table, key, value]) => table === delayed && key === 'profile_id' && value === 'first'));
    }
  } finally { fakeSupabase.from = previousFrom; }
});

