  assert.equal(conflicts.length, 1); assert.equal(conflicts[0].kind, 'identity');
  assert.equal(conflicts[0].planning, local); assert.equal(conflicts[0].cloud, remote);
  assert.equal(JSON.stringify([local, remote]), original);
  for (const cloudRecord of [{ ...remote, id: 'different' }, { ...remote, id: local.cloudLogId, cloudLogId: undefined }, { ...remote, id: 'different', cloudLogId: local.id }, { ...remote, assignmentId: null }]) {
    assert.equal(availableLogs.workoutCompletionConflicts([local], [cloudRecord])[0].kind, 'identity');
  }
  assert.equal(availableLogs.workoutCompletionConflicts([local], [{ ...local, title: 'Renamed' }])[0].kind, 'content');
  assert.deepEqual(availableLogs.workoutCompletionConflicts([local], [{ ...local, id: local.cloudLogId, cloudLogId: undefined }]), []);
  assert.deepEqual(availableLogs.workoutCompletionConflicts([local], [{ ...local, id: 'cloud-view', cloudLogId: local.id }]), []);
