test('cloud refresh is read-only, deduplicated in flight, retains cached rows on failure, and rejects stale responses', async () => {
  authUser = { id: 'member' }; await store.initializePlanning('member');
  const previousFrom = fakeSupabase.from; const calls = [];
  const row = { id: 'log', profile_id: 'member', title: 'Cloud only', status: 'completed', completed_at: '2026-10-10T12:00:00Z' };
  try {
    fakeSupabase.from = paginatedHistoryBackend(previousFrom, { workout_logs: [row], workout_set_logs: [] }, calls);
    const before = store.planningSnapshot();
    await cloudHistory.refreshCloudWorkoutHistory();
    assert.equal(availableLogs.cloudHistorySnapshot().logs.length, 1); assert.match(availableLogs.cloudHistorySnapshot().status, /updated/);
    assert.equal(store.planningSnapshot(), before); assert.deepEqual(logs.readPlanningLogs(), []);
    fakeSupabase.from = () => { throw Error('Offline'); };
    await cloudHistory.refreshCloudWorkoutHistory();
    assert.equal(availableLogs.cloudHistorySnapshot().logs.length, 1); assert.match(availableLogs.cloudHistorySnapshot().status, /last loaded/);
    let finish; let started = 0;
    fakeSupabase.from = paginatedHistoryBackend(previousFrom, { workout_logs: [row], workout_set_logs: [] }, calls, call => {
      if (call.table === 'workout_logs' && !call.cursor) { started++; return new Promise(resolve => { finish = () => resolve({ data: [row], error: null }); }); }
      return null;
    });
    const pending = cloudHistory.refreshCloudWorkoutHistory();
    await new Promise(resolve => setImmediate(resolve));
    await cloudHistory.refreshCloudWorkoutHistory(); assert.equal(started, 1);
    cloudHistory.resetCloudWorkoutHistory();
    authUser = { id: 'other' }; await store.initializePlanning('other');
    finish(); await pending;
    assert.deepEqual(availableLogs.cloudHistorySnapshot().logs, []);
    assert.deepEqual(logs.readAvailableWorkoutLogs(), []);
  } finally { fakeSupabase.from = previousFrom; cloudHistory.resetCloudWorkoutHistory(); }
});

function paginatedHistoryBackend(previousFrom, rows, calls, intercept = () => null) {
  return table => {
    if (table === 'planning_documents') return previousFrom(table);
    const request = { table, filters: {}, cursor: null, parents: null, limit: null };
    return {
      select() { return this; },
      eq(key, value) { request.filters[key] = value; return this; },
      in(key, values) { assert.equal(key, 'workout_log_id'); request.parents = values; return this; },
      order(key, options) { assert.equal(key, 'id'); assert.equal(options.ascending, true); return this; },
      limit(value) { request.limit = value; return this; },
      gt(key, value) { assert.equal(key, 'id'); request.cursor = value; return this; },
      async abortSignal(signal) {
        assert.ok(signal instanceof AbortSignal); calls.push(request);
        const intercepted = await intercept(request);
        if (intercepted) return intercepted;
        const data = rows[table].filter(row => row.profile_id === request.filters.profile_id && (!request.cursor || row.id > request.cursor) && (!request.parents || request.parents.includes(row.workout_log_id))).sort((a, b) => a.id.localeCompare(b.id)).slice(0, Math.min(request.limit, 37));
        return { data, error: null };
      },
    };
  };
}

test('cloud history pages beyond backend caps and bounds exercise parent filters without mutating local data', async () => {
  authUser = { id: 'member' }; await store.initializePlanning('member');
  const before = store.planningSnapshot();
  const logs = Array.from({ length: 205 }, (_, index) => ({ id: `log-${String(index).padStart(4, '0')}`, profile_id: 'member', completed_at: index === 204 ? '2026-10-13T12:00:00Z' : '2026-10-12T12:00:00Z' }));
  const sets = logs.flatMap(log => Array.from({ length: 6 }, (_, index) => ({ id: `set-${log.id}-${index}`, profile_id: 'member', workout_log_id: log.id, performed_at: '2026-10-12T12:00:00Z', order_index: index })));
  const previousFrom = fakeSupabase.from; const calls = [];
  try {
    fakeSupabase.from = paginatedHistoryBackend(previousFrom, { workout_logs: logs, workout_set_logs: sets }, calls);
    const result = await persistence.loadWorkoutLogRowsFromSupabase();
    assert.equal(result.success, true); assert.equal(result.data.logs.length, 205); assert.equal(result.data.setLogs.length, 1230);
    assert.equal(result.data.logs[0].id, 'log-0204');
    assert.equal(new Set(result.data.setLogs.map(row => row.id)).size, 1230);
    assert.ok(calls.filter(call => call.table === 'workout_logs').length > 2, 'continues after short nonempty pages');
    assert.ok(calls.filter(call => call.parents).every(call => call.parents.length <= 100));
    assert.deepEqual([...new Set(calls.filter(call => call.parents).flatMap(call => call.parents))].sort(), logs.map(log => log.id));
    assert.ok(calls.every(call => call.filters.profile_id === 'member'));
    assert.equal(store.planningSnapshot(), before, 'read-only history does not create planning records');
  } finally { fakeSupabase.from = previousFrom; }
});

test('cloud history never exposes partial pages after errors, account changes, or invalid rows', async () => {
  const previousFrom = fakeSupabase.from;
  try {
    for (const failure of ['log-page', 'set-page', 'account', 'owner', 'order', 'parent']) {
      authUser = { id: 'member' }; await store.initializePlanning('member');
      const logs = Array.from({ length: 40 }, (_, index) => ({ id: `log-${String(index).padStart(4, '0')}`, profile_id: 'member' }));
      const sets = logs.map(log => ({ id: `set-${log.id}`, profile_id: 'member', workout_log_id: log.id }));
      const calls = [];
      fakeSupabase.from = paginatedHistoryBackend(previousFrom, { workout_logs: logs, workout_set_logs: sets }, calls, async call => {
        if (failure === 'log-page' && call.table === 'workout_logs' && call.cursor || failure === 'set-page' && call.table === 'workout_set_logs' && call.cursor) return { data: null, error: new Error('Later page unavailable') };
        if (failure === 'account' && call.cursor) { authUser = { id: 'second' }; await store.initializePlanning('second'); }
        if (failure === 'owner') return { data: [{ id: 'private', profile_id: 'other' }], error: null };
        if (failure === 'order' && call.cursor) return { data: [{ id: call.cursor, profile_id: 'member' }], error: null };
        if (failure === 'parent' && call.parents) return { data: [{ id: 'set-other', profile_id: 'member', workout_log_id: 'unrequested' }], error: null };
        return null;
      });
      const result = await persistence.loadWorkoutLogRowsFromSupabase();
      assert.equal(result.success, false, failure); assert.deepEqual(result.data, { logs: [], setLogs: [] }, failure);
      assert.ok(result.error); assert.deepEqual(store.readPlanning(store.planningKeys.logs, []), []);
    }
  } finally { fakeSupabase.from = previousFrom; }
});

