test('legacy sync refuses stale source snapshots after discovery, upload auth, or an earlier upload', async () => {
  authUser = { id: 'legacy-revision-member' }; await store.initializePlanning(authUser.id);
  const entries = ['2026-10-11', '2026-10-12'].map(date => ({ exerciseId: 'squat', exerciseName: 'Squat', date, sets: '3' }));
  const previousFrom = fakeSupabase.from; const previousAuthenticate = authenticate;
  try {
    fakeSupabase.from = table => table === 'planning_documents' ? previousFrom(table) : ({ select() { return this; }, eq() { return this; }, order() { return this; }, limit() { return this; }, gt() { return this; }, abortSignal() { return Promise.resolve({ data: [], error: null }); } });
    for (const source of ['exerciseStats', 'logs']) {
      for (const stage of ['discovery', 'upload-auth', 'earlier-upload']) {
        store.writePlanning(store.planningKeys.logs, []);
        store.writePlanning(store.planningKeys.exerciseStats, entries);
        const changed = source === 'exerciseStats' ? [{ ...entries[0], sets: '5' }]
          : [{ id: 'new-canonical', completedAt: entries[1].date, entries: [entries[1]] }];
        const change = () => store.writePlanning(store.planningKeys[source], changed);
        let authCalls = 0; const writes = [];
        authenticate = async () => {
          authCalls++;
          if (stage === 'discovery' && authCalls === 1 || stage === 'upload-auth' && authCalls === 3) change();
          return { data: { user: authUser }, error: null };
        };
        save = async (name, payload) => {
          if (name === 'save_planning_document') return { data: 1, error: null };
          writes.push(payload);
          if (stage === 'earlier-upload') change();
          return { data: '22222222-3333-4444-8555-666666666666', error: null };
        };
        const result = await persistence.syncLocalWorkoutLogsToSupabase();
        assert.equal(result.success, false, `${source}/${stage}`);
        assert.match(result.error, /history changed during sync/);
        assert.equal(writes.length, stage === 'earlier-upload' ? 1 : 0, `${source}/${stage}`);
        assert.deepEqual(store.readPlanning(store.planningKeys[source], []), changed);
        assert.deepEqual(store.readPlanning(store.planningKeys[source === 'logs' ? 'exerciseStats' : 'logs'], []), source === 'logs' ? entries : []);
      }
    }
  } finally { fakeSupabase.from = previousFrom; authenticate = previousAuthenticate; }
});

