test('a forged cookie with a future expiry cannot bypass protected-route authentication', async () => {
  const { NextRequest } = require('next/server');
  const originalUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const originalBypass = process.env.SF_LOCAL_AUTH_BYPASS;
  process.env.NEXT_PUBLIC_SUPABASE_URL = 'https://test.supabase.co';
  process.env.SF_LOCAL_AUTH_BYPASS = '0';
  try {
    const payload = Buffer.from(JSON.stringify({ exp: Math.floor(Date.now() / 1000) + 3600, sub: 'forged' })).toString('base64url');
    const request = new NextRequest('https://app.example/dashboard', { headers: { cookie: `sb-test-auth-token=${encodeURIComponent(JSON.stringify({ access_token: `header.${payload}.forged` }))}` } });
    const denied = await proxy.proxy(request);
    assert.equal(denied.status, 307);
    assert.match(denied.headers.get('location'), /next=%2Fdashboard/);
    claimsResult = { data: { claims: { sub: 'verified-member' } }, error: null };
    assert.equal((await proxy.proxy(request)).status, 200);
  } finally {
    if (originalUrl === undefined) delete process.env.NEXT_PUBLIC_SUPABASE_URL; else process.env.NEXT_PUBLIC_SUPABASE_URL = originalUrl;
    if (originalBypass === undefined) delete process.env.SF_LOCAL_AUTH_BYPASS; else process.env.SF_LOCAL_AUTH_BYPASS = originalBypass;
  }
});

