test('background workout replay preserves malformed rows and duplicate identities while syncing independent sessions', async () => {
  authUser = { id: 'mixed-queue-member' }; await store.initializePlanning(authUser.id);
  const original = { id: 'independent-session', title: 'Press', completedAt: '2026-10-12T12:00:00Z', entries: [{ exerciseName: 'Press', sets: '2', date: '2026-10-12T12:00:00Z' }] };
  const duplicate = { ...original, id: 'repeated-session' };
  const malformed = [null, false, 0, 'broken', [], {}, { id: '' }];
  const originals = [...malformed, duplicate, { ...duplicate, title: 'Different saved content' }, original];
  store.writePlanning(store.planningKeys.logs, originals);
  const requests = []; const cloudId = '88888888-8888-4888-8888-888888888888';
  save = async (name, payload) => { if (name === 'save_planning_document') return { data: 1, error: null }; requests.push(payload.session_key); return { data: cloudId, error: null }; };
  await persistence.syncPendingPlanningWorkouts();
  const saved = logs.readPlanningLogs();
  assert.deepEqual(saved.slice(0, -1), originals.slice(0, -1));
  assert.equal(saved.at(-1).cloudLogId, cloudId); assert.deepEqual(saved.at(-1).entries, original.entries);
  assert.deepEqual(requests, [original.id]);
  await persistence.syncPendingPlanningWorkouts(); assert.deepEqual(requests, [original.id]);
  const snapshot = store.planningSnapshot();
  assert.throws(() => logs.assertPlanningLogVersion(duplicate.id, logs.planningLogVersion(duplicate)), /identity needs review/);
  assert.throws(() => logs.markPlanningLogSynced(duplicate.id, cloudId), /duplicated/);
  assert.throws(() => logs.markPlanningLogSyncError(duplicate.id, 'Offline', logs.planningLogVersion(duplicate)), /identity needs review/);
  assert.equal(store.planningSnapshot(), snapshot);
  const manual = await persistence.syncLocalWorkoutLogsToSupabase();
  assert.equal(manual.success, false); assert.match(manual.error, /need review/); assert.deepEqual(requests, [original.id]);
  assert.equal(store.planningSnapshot(), snapshot);
  for (const container of [false, 0, 'broken', {}]) {
    store.writePlanning(store.planningKeys.logs, container); const before = store.planningSnapshot();
    await persistence.syncPendingPlanningWorkouts(); const result = await persistence.syncLocalWorkoutLogsToSupabase();
    assert.equal(result.success, false); assert.match(result.error, /need review/);
    assert.equal(store.planningSnapshot(), before); assert.deepEqual(requests, [original.id]);
  }
});

