test('background replay skips later queue snapshots changed, removed, or confirmed during an earlier upload', async () => {
  authUser = { id: 'queue-member' }; await store.initializePlanning(authUser.id);
  const first = { id: 'first-queued', title: 'First', completedAt: '2026-10-12T12:00:00Z', entries: [{ exerciseId: 'squat', exerciseName: 'Squat', sets: '3', date: '2026-10-12T12:00:00Z' }] };
  const second = { ...first, id: 'second-queued', title: 'Second' };
  for (const mode of ['changed', 'removed', 'confirmed']) {
    store.writePlanning(store.planningKeys.logs, [first, second]);
    let finish; const keys = [];
    save = async (name, payload) => { if (name === 'save_planning_document') return { data: 1, error: null }; keys.push(payload.session_key); if (payload.session_key === first.id) return new Promise(resolve => { finish = resolve; }); return { data: 'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb', error: null }; };
    const pending = persistence.syncPendingPlanningWorkouts(); await new Promise(resolve => setImmediate(resolve));
    const replacement = mode === 'changed' ? { ...second, title: 'New saved values' } : { ...second, cloudLogId: 'cccccccc-cccc-4ccc-8ccc-cccccccccccc', syncedAt: '2026-10-12T12:01:00Z' };
    store.writePlanning(store.planningKeys.logs, mode === 'removed' ? [first] : [first, replacement]);
    finish({ data: 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', error: null }); await pending;
    assert.deepEqual(keys, [first.id]); assert.equal(logs.planningLogUploadConfirmed(logs.readPlanningLogs()[0]), true);
    assert.deepEqual(logs.readPlanningLogs().slice(1), mode === 'removed' ? [] : [replacement]);
  }
});

