test('legacy history sync preserves undated originals and uploads only recorded exercise dates', async () => {
  authUser = { id: 'legacy-date-member' }; await store.initializePlanning(authUser.id);
  const base = { exerciseId: 'squat', exerciseName: 'Squat', sets: '3' };
  const originals = ['', null, undefined, false, '2026-02-30T12:00:00Z'].map((date, index) => ({ ...base, exerciseId: `review-${index}`, date }));
  const recorded = { ...base, date: '2024-02-29T12:00:00.123456+00:00' };
  const entries = [...originals, recorded];
  store.writePlanning(store.planningKeys.exerciseStats, entries);
  const previousFrom = fakeSupabase.from; const writes = [];
  try {
    fakeSupabase.from = table => table === 'planning_documents' ? previousFrom(table) : ({ select() { return this; }, eq() { return this; }, order() { return this; }, limit() { return this; }, gt() { return this; }, abortSignal() { return Promise.resolve({ data: [], error: null }); } });
    save = async (name, payload) => {
      if (name === 'save_planning_document') return { data: 1, error: null };
      writes.push(payload); return { data: '22222222-3333-4444-8555-666666666666', error: null };
    };
    const result = await persistence.syncLocalWorkoutLogsToSupabase();
    assert.equal(result.success, false); assert.equal(result.data.localItems, 6);
    assert.equal(result.data.failedItems, 5); assert.equal(result.data.syncedItems, 1);
    assert.match(result.error, /date needs review/); assert.equal(writes.length, 1);
    assert.equal(writes[0].log_payload.completed_at, recorded.date);
    assert.deepEqual(writes[0].set_payloads.map(entry => entry.performed_at), [recorded.date]);
    assert.deepEqual(store.readPlanning(store.planningKeys.exerciseStats, []), entries);
    assert.deepEqual(logs.readPlanningLogs(), []);
    const direct = await persistence.saveCompletedWorkoutLogToSupabase({ entries: [originals[0]] });
    assert.equal(direct.success, false); assert.match(direct.error, /date needs review/);
    assert.deepEqual(direct.data.entries, [{ ...originals[0], source: 'workout-session' }]);
    assert.equal(writes.length, 1);
  } finally { fakeSupabase.from = previousFrom; }
});

