test('malformed exercise metadata stays in recovery while valid pending workouts continue', async () => {
  authUser = { id: 'metadata-review-member' }; await store.initializePlanning(authUser.id);
  const entry = { exerciseId: 'squat', exerciseName: 'Squat', sets: '3', date: '2026-10-12T12:00:00Z' };
  const patches = [
    ...['', ' \t\n ', true, 42, {}, [], null].map(exerciseName => ({ exerciseName })),
    ...['exerciseId', 'body', 'pattern', 'equipment'].flatMap(field => [true, 42, {}, []].map(value => ({ [field]: value }))),
    ...['weightUnit', 'weight_unit', 'loadUnit', 'load_unit', 'unit', 'weightKg', 'weightPounds', 'weightLb', 'loadKg', 'loadLb'].flatMap(field => ['kg', 'lb', 0, '20', true, {}, []].filter(value => field !== 'weightUnit' || !['kg', 'lb'].includes(value)).map(value => ({ [field]: value }))),
  ];
  const records = [
    ...patches.map((patch, index) => ({ id: `metadata-review-${index}`, title: 'Original', completedAt: entry.date, entries: [{ ...entry, ...patch }] })),
    ...[null, false, 0, 'legacy entry', []].map((value, index) => ({ id: `entry-review-${index}`, title: 'Original', completedAt: entry.date, entries: [value] })),
  ];
  const valid = { id: 'metadata-valid-last', title: 'Valid', completedAt: entry.date, entries: [{ ...entry, exerciseId: null, body: null, pattern: '', equipment: 'Bodyweight' }] };
  store.writePlanning(store.planningKeys.logs, [...records, valid]);
  const payloads = [];
  save = async (name, payload) => {
    if (name === 'save_planning_document') return { data: 1, error: null };
    payloads.push(payload); return { data: '22222222-3333-4444-8555-666666666666', error: null };
  };
  for (const record of records) {
    const result = await persistence.saveCompletedWorkoutLogToSupabase({ ...record, sessionId: record.id });
    assert.equal(result.success, false); assert.match(result.error, /Saved exercise .* needs review/);
  }
  assert.deepEqual(payloads, []);
  await persistence.syncPendingPlanningWorkouts();
  assert.deepEqual(payloads.map(payload => payload.session_key), [valid.id]);
  const saved = logs.readPlanningLogs();
  saved.slice(0, -1).forEach((record, index) => {
    const { syncError, ...original } = record;
    assert.match(syncError, /Saved exercise .* needs review/); assert.deepEqual(original, records[index]);
  });
  assert.ok(logs.planningLogUploadConfirmed(saved.at(-1)));
  assert.equal(payloads[0].set_payloads[0].exercise_id, null);
  assert.equal(payloads[0].set_payloads[0].body, null);
});

test('malformed exercise containers receive upload diagnostics while valid pending workouts continue', async () => {
  authUser = { id: 'container-review-member' }; await store.initializePlanning(authUser.id);
  const entry = { exerciseId: 'squat', exerciseName: 'Squat', sets: '3', date: '2026-10-12T12:00:00Z' };
  const records = [undefined, null, false, 0, 'legacy exercises', { original: 'exercise container' }].map((entries, index) => ({ id: `container-review-${index}`, title: 'Original', completedAt: entry.date, entries }));
  const valid = { id: 'container-valid-last', title: 'Valid', completedAt: entry.date, entries: [entry] };
  const payloads = [];
  save = async (name, payload) => {
    if (name === 'save_planning_document') return { data: 1, error: null };
    payloads.push(payload); return { data: '22222222-3333-4444-8555-666666666666', error: null };
  };
  for (const record of records) {
    const result = await persistence.saveCompletedWorkoutLogToSupabase({ ...record, sessionId: record.id });
    assert.equal(result.success, false); assert.match(result.error, /exercise list is malformed/);
  }
  assert.deepEqual(payloads, []);
  store.writePlanning(store.planningKeys.logs, [...records, valid]);
  store.writePlanning(store.planningKeys.exerciseStats, [entry]);
  await persistence.syncPendingPlanningWorkouts();
  assert.deepEqual(payloads.map(payload => payload.session_key), [valid.id]);
  logs.readPlanningLogs().slice(0, -1).forEach((record, index) => { const { syncError, ...original } = record; assert.match(syncError, /exercise list is malformed/); assert.deepEqual(original, records[index]); });
  const legacyResult = await persistence.syncLocalWorkoutLogsToSupabase();
  assert.equal(legacyResult.success, false); assert.match(legacyResult.error, /exercise lists need review/);
  assert.deepEqual(payloads.map(payload => payload.session_key), [valid.id], 'ambiguous canonical lists cannot cause duplicate legacy uploads');
  assert.deepEqual(store.readPlanning(store.planningKeys.exerciseStats, []), [entry]);
});

test('malformed workout titles return review diagnostics without blocking later pending sessions', async () => {
  authUser = { id: 'title-review-member' }; await store.initializePlanning(authUser.id);
  const entry = { exerciseName: 'Squat', sets: '3', date: '2026-10-12T12:00:00Z' };
  const records = [false, 0, true, 42, {}, []].map((title, index) => ({ id: `bad-title-${index}`, title, completedAt: entry.date, entries: [entry] }));
  const payloads = [];
  save = async (name, payload) => {
    if (name === 'save_planning_document') return { data: 1, error: null };
    payloads.push(payload); return { data: '22222222-3333-4444-8555-666666666666', error: null };
  };
  for (const record of records) {
    const result = await persistence.saveCompletedWorkoutLogToSupabase({ ...record, sessionId: record.id });
    assert.equal(result.success, false); assert.match(result.error, /Saved workout title needs review/);
    const local = persistence.saveCompletedWorkoutLogToLocalStorage({ ...record, sessionId: record.id });
    assert.equal(local.success, false); assert.match(local.error, /Saved workout title needs review/);
  }
  assert.deepEqual(logs.readPlanningLogs(), []);
  assert.deepEqual(store.readPlanning(store.planningKeys.exerciseStats, []), []);
  assert.deepEqual(payloads, []);
  const valid = [null, undefined, '', '   ', ' Strength '].map((title, index) => ({ id: `valid-title-${index}`, title, completedAt: entry.date, entries: [entry] }));
  store.writePlanning(store.planningKeys.logs, [...records, ...valid]);
  await persistence.syncPendingPlanningWorkouts();
  assert.deepEqual(payloads.map(payload => payload.session_key), valid.map(record => record.id));
  assert.deepEqual(payloads.map(payload => payload.log_payload.title), ['Workout Session', 'Workout Session', 'Workout Session', 'Workout Session', 'Strength']);
  const saved = logs.readPlanningLogs();
  records.forEach((record, index) => {
    const { syncError, ...original } = saved[index];
    assert.match(syncError, /Saved workout title needs review/); assert.deepEqual(original, record);
  });
  assert.ok(saved.slice(records.length).every(logs.planningLogUploadConfirmed));
});

test('completion retries refuse ambiguous session and assignment matches without choosing an original', async () => {
  authUser = { id: 'ambiguous-retry-member' }; await store.initializePlanning(authUser.id);
  let requests = 0; save = async () => { requests++; return { data: null, error: null }; };
  const record = { id: 'saved-session', assignmentId: 'saved-assignment', title: 'Original', completedAt: '2026-10-12T12:00:00Z', entries: [{ exerciseName: 'Squat', sets: '2', date: '2026-10-12T12:00:00Z' }], cloudLogId: '11111111-1111-4111-8111-111111111111', syncedAt: '2026-10-12T12:01:00Z' };
  const variants = [
    { records: [record, { ...record, title: 'Different original' }], input: { sessionId: record.id } },
    { records: [record, { ...record, id: 'other-session' }], input: { sessionId: 'retry-session', assignmentId: record.assignmentId } },
    { records: [record, { ...record, id: 'other-session', assignmentId: 'other-assignment' }], input: { sessionId: record.id, assignmentId: 'other-assignment' } },
  ];
  for (const { records, input } of variants) {
    store.writePlanning(store.planningKeys.logs, records); store.writePlanning('loggerDraft:default', { id: 'retry-session', logs: { 0: { sets: '3' } } });
    const before = store.planningSnapshot();
    for (const result of [persistence.saveCompletedWorkoutLogToLocalStorage({ ...input, entries: [] }), await persistence.saveCompletedWorkoutLogWithFallback({ ...input, entries: [] })]) {
      assert.equal(result.success, false); assert.equal(result.data.workoutLogId, null); assert.match(result.error, /Multiple saved workouts/);
    }
    assert.equal(store.planningSnapshot(), before); assert.equal(requests, 0);
  }
});

test('local and fallback completion handle malformed lists without throwing and retain immutable retries', async () => {
  authUser = { id: 'completion-list-member' }; await store.initializePlanning(authUser.id);
  const payloads = [];
  save = async (name, payload) => { if (name === 'save_planning_document') return { data: 1, error: null }; payloads.push(payload); return { data: '22222222-3333-4444-8555-666666666666', error: null }; };
  const original = store.planningSnapshot();
  for (const entries of [undefined, null, false, 0, 'exercises', { length: 1 }]) {
    const input = { sessionId: 'invalid-new-list', title: 'Workout', entries };
    const local = persistence.saveCompletedWorkoutLogToLocalStorage(input);
    assert.equal(local.success, false); assert.match(local.error, /Exercise list is malformed/);
    const fallback = await persistence.saveCompletedWorkoutLogWithFallback(input);
    assert.equal(fallback.success, false); assert.match(fallback.error, /Exercise list is malformed/);
    assert.equal(input.entries, entries); assert.equal(store.planningSnapshot(), original);
  }
  const empty = await persistence.saveCompletedWorkoutLogWithFallback({ sessionId: 'empty-new-list', title: 'Workout', entries: [] });
  assert.equal(empty.success, false); assert.match(empty.error, /at least one exercise/);
  assert.equal(store.planningSnapshot(), original); assert.deepEqual(payloads, []);
  const saved = { id: 'already-complete', title: 'Original immutable workout', completedAt: '2026-10-12T12:00:00Z', entries: [{ exerciseName: 'Squat', sets: '3', date: '2026-10-12T12:00:00Z' }], cloudLogId: '22222222-3333-4444-8555-666666666666', syncedAt: '2026-10-12T12:01:00Z' };
  store.writePlanning(store.planningKeys.logs, [saved]);
  const snapshot = store.planningSnapshot();
  for (const entries of [undefined, null, false, {}, []]) {
    const retry = await persistence.saveCompletedWorkoutLogWithFallback({ sessionId: saved.id, title: 'Changed caller title', entries });
    assert.equal(retry.success, true); assert.equal(retry.data.workoutLogId, saved.cloudLogId); assert.deepEqual(retry.data.entries, saved.entries);
    assert.equal(store.planningSnapshot(), snapshot);
  }
  assert.deepEqual(payloads, []);
});

test('new local completions reject malformed exercise details and dates before any durable write', () => {
  const entry = { exerciseName: 'Squat', sets: '3', date: '2026-10-12T12:00:00Z' };
  const originalLogs = logs.readPlanningLogs();
  const originalStats = store.readPlanning(store.planningKeys.exerciseStats, []);
  const malformed = [null, false, 0, 'legacy', [], ...['', '  ', true, {}].map(exerciseName => ({ ...entry, exerciseName })),
    ...['exerciseId', 'body', 'pattern', 'equipment'].flatMap(field => [false, 0, {}, []].map(value => ({ ...entry, [field]: value }))),
    { ...entry, date: '2026-02-30T12:00:00Z' }, ...[true, false, 0, '', '   '].map(date => ({ ...entry, date }))];
  for (const invalid of malformed) {
    const result = persistence.saveCompletedWorkoutLogToLocalStorage({ sessionId: 'invalid-new-completion', title: 'Strength', completedAt: entry.date, entries: [entry, invalid] });
    assert.equal(result.success, false); assert.match(result.error, /needs review/);
    assert.deepEqual(logs.readPlanningLogs(), originalLogs);
    assert.deepEqual(store.readPlanning(store.planningKeys.exerciseStats, []), originalStats);
  }
  for (const changes of [{ completedAt: '2026-02-30T12:00:00Z' }, ...[true, false, 0, '', '   '].map(completedAt => ({ completedAt })), { startedAt: 'invalid' }, { startedAt: '2026-10-12T13:00:00Z' }]) {
    const result = persistence.saveCompletedWorkoutLogToLocalStorage({ sessionId: 'invalid-new-completion', completedAt: entry.date, entries: [entry], ...changes });
    assert.equal(result.success, false); assert.match(result.error, /needs review/);
    assert.deepEqual(logs.readPlanningLogs(), originalLogs);
    assert.deepEqual(store.readPlanning(store.planningKeys.exerciseStats, []), originalStats);
  }
  const undated = { exerciseName: 'Press', sets: '2' };
  const input = { sessionId: 'valid-new-completion', entries: [undated] };
  const before = JSON.stringify(input);
  const valid = persistence.saveCompletedWorkoutLogToLocalStorage(input);
  assert.equal(valid.success, true);
  assert.ok(Number.isFinite(Date.parse(valid.data.entries[0].date)));
  assert.equal(JSON.stringify(input), before);
  const saved = logs.readPlanningLogs().find(record => record.id === input.sessionId);
  const replay = persistence.saveCompletedWorkoutLogToLocalStorage({ ...input, entries: [null] });
  assert.equal(replay.success, true); assert.deepEqual(replay.data.entries, saved.entries);
});

test('explicit blank or falsy workout dates cannot become current timestamps or exercise-date fallbacks', async () => {
  authUser = { id: 'explicit-date-member' }; await store.initializePlanning(authUser.id);
  let requests = 0; save = async () => { requests++; return { data: '11111111-1111-4111-8111-111111111111', error: null }; };
  const entry = { exerciseName: 'Press', sets: '2', date: '2026-10-12T12:00:00Z' };
  for (const value of [false, 0, '', '   ']) for (const field of ['completedAt', 'date']) {
    const input = { sessionId: 'invalid-explicit-date', completedAt: entry.date, entries: [{ ...entry }], ...(field === 'completedAt' ? { completedAt: value } : { entries: [{ ...entry, date: value }] }) };
    const snapshot = store.planningSnapshot(); const original = JSON.stringify(input);
    for (const result of [await persistence.saveCompletedWorkoutLogToSupabase(input), await persistence.saveCompletedWorkoutLogWithFallback(input)]) {
      assert.equal(result.success, false); assert.match(result.error, /date needs review/);
    }
    assert.equal(requests, 0); assert.equal(store.planningSnapshot(), snapshot); assert.equal(JSON.stringify(input), original);
  }
  const result = persistence.saveCompletedWorkoutLogToLocalStorage({ sessionId: 'unreported-dates', completedAt: null, entries: [{ ...entry, date: null }] });
  assert.equal(result.success, true); assert.ok(Number.isFinite(Date.parse(result.data.entries[0].date)));
});

test('completion storage and malformed history failures return review results without writes or RPCs', async () => {
  authUser = { id: 'completion-storage-member' }; await store.initializePlanning(authUser.id);
  let requests = 0; save = async () => { requests++; return { data: null, error: null }; };
  const input = { sessionId: 'storage-retry', title: 'Press', entries: [{ exerciseName: 'Press', sets: '2', date: '2026-10-12T12:00:00Z' }] };
  const originalStats = [{ exerciseName: 'Older squat', sets: '1', date: '2026-10-11T12:00:00Z' }];
  store.writePlanning(store.planningKeys.exerciseStats, originalStats);
  const snapshot = store.planningSnapshot(); failure = true;
  try {
    for (const result of [persistence.saveCompletedWorkoutLogToLocalStorage(input), await persistence.saveCompletedWorkoutLogWithFallback(input)]) {
      assert.equal(result.success, false); assert.equal(result.data.workoutLogId, null); assert.match(result.error, /Quota/);
    }
  } finally { failure = false; }
  assert.equal(store.planningSnapshot(), snapshot); assert.equal(requests, 0);
  for (const damaged of [false, 0, 'broken', {}, [null], [false], [[]], [{}], [{ id: '' }]]) {
    store.writePlanning(store.planningKeys.logs, damaged); const before = store.planningSnapshot();
    for (const result of [persistence.saveCompletedWorkoutLogToLocalStorage(input), await persistence.saveCompletedWorkoutLogWithFallback(input)]) {
      assert.equal(result.success, false); assert.match(result.error, /history needs review/);
    }
    assert.equal(store.planningSnapshot(), before); assert.equal(requests, 0);
  }
  store.writePlanning(store.planningKeys.logs, []);
  const retry = persistence.saveCompletedWorkoutLogToLocalStorage(input);
  assert.equal(retry.success, true); assert.equal(retry.data.workoutLogId, input.sessionId);
  assert.equal(logs.readPlanningLogs().length, 1);
  assert.equal(store.readPlanning(store.planningKeys.exerciseStats, []).length, 2);
  const confirmed = { ...logs.readPlanningLogs()[0], cloudLogId: '11111111-1111-4111-8111-111111111111', syncedAt: '2026-10-12T12:01:00Z' };
  store.writePlanning(store.planningKeys.logs, [null, confirmed]); const mixedSnapshot = store.planningSnapshot();
  const existing = await persistence.saveCompletedWorkoutLogWithFallback({ ...input, entries: [] });
  assert.equal(existing.success, true); assert.equal(existing.data.workoutLogId, confirmed.cloudLogId);
  assert.equal(store.planningSnapshot(), mixedSnapshot); assert.equal(requests, 0);
});

test('workout numeric mapping preserves exponent values, decimal weights, explicit zero, and unknown blanks', () => {
  const entry = { exerciseId: 'squat', exerciseName: 'Squat', reps: '1e2', sets: '3.0', weight: ' 12.75 ', date: '2026-10-12T12:00:00Z' };
  const mapped = persistence.mapLocalStatEntryToSetLogInsert(entry, 'log', 'member', 0);
  assert.equal(mapped.reps, 100); assert.equal(mapped.sets, 3); assert.equal(mapped.weight, 12.75);
  for (const blank of ['', '   ', null, undefined]) {
    const unknown = persistence.mapLocalStatEntryToSetLogInsert({ ...entry, reps: blank, sets: blank, weight: blank }, 'log', 'member', 0);
    assert.equal(unknown.reps, null); assert.equal(unknown.sets, null); assert.equal(unknown.weight, null);
  }
  assert.equal(persistence.mapLocalStatEntryToSetLogInsert({ ...entry, weight: '0' }, 'log', 'member', 0).weight, 0);
});

test('invalid workout numbers never create completion or stats and never reach the workout RPC', async () => {
  authUser = { id: 'numeric-member' }; await store.initializePlanning(authUser.id);
  const entry = { exerciseId: 'squat', exerciseName: 'Squat', reps: '8', sets: '3', weight: '20', date: '2026-10-12T12:00:00Z' };
  const invalid = [['reps', '8 reps'], ['sets', '3.5'], ['reps', '0'], ['sets', '-1'], ['reps', '2147483648'], ['sets', Infinity], ['weight', '-1'], ['weight', '0x10'], ['weight', 'NaN'], ['weight', true]];
  const calls = []; save = async (name) => { calls.push(name); return { data: null, error: null }; };
  for (const [field, value] of invalid) {
    const input = { sessionId: 'invalid-number', entries: [{ ...entry, [field]: value }] };
    const local = await persistence.saveCompletedWorkoutLogWithFallback(input);
    assert.equal(local.success, false); assert.match(local.error, /must be/); assert.deepEqual(local.data.entries, []);
    const cloud = await persistence.saveCompletedWorkoutLogToSupabase(input); assert.equal(cloud.success, false); assert.match(cloud.error, /must be/);
    assert.deepEqual(logs.readPlanningLogs(), []); assert.deepEqual(store.readPlanning(store.planningKeys.exerciseStats, []), []);
  }
  assert.deepEqual(calls, []);
});

