test('invalid older workout values do not block later valid uploads and errors retain original data', async () => {
  authUser = { id: 'queue-diagnostics' }; await store.initializePlanning(authUser.id);
  const entry = { exerciseId: 'squat', exerciseName: 'Squat', sets: '3', reps: '8', weight: '20', date: '2026-10-12T12:00:00Z' };
  const bad = { id: 'invalid-first', title: 'Needs review', completedAt: entry.date, entries: [{ ...entry, reps: '8 reps' }] };
  const good = { ...bad, id: 'valid-second', title: 'Valid completion', entries: [entry] };
  logs.recordPlanningLog(bad); logs.recordPlanningLog(good);
  const keys = []; save = async (name, payload) => { if (name === 'save_planning_document') return { data: 1, error: null }; keys.push(payload.session_key); return { data: 'ffffffff-ffff-4fff-8fff-ffffffffffff', error: null }; };
  await persistence.syncPendingPlanningWorkouts(); await persistence.syncPendingPlanningWorkouts();
  const records = logs.readPlanningLogs(); const { syncError, ...preserved } = records[0]; assert.deepEqual(preserved, bad); assert.match(syncError, /Reps/); assert.equal(logs.planningLogUploadConfirmed(records[0]), false);
  assert.equal(logs.planningLogUploadConfirmed(records[1]), true); assert.equal(records[1].syncError, undefined); assert.deepEqual(keys, ['valid-second']);
  assert.equal(store.readPlanning(store.planningKeys.exerciseStats, []).length, 2);
});

test('workout sync diagnostics guard revisions, storage failure, and confirmed records', () => {
  const original = { id: 'diagnostic', title: 'Original', completedAt: '2026-10-12T12:00:00Z', entries: [] };
  logs.recordPlanningLog(original); const version = logs.planningLogVersion(original);
  failure = true; assert.throws(() => logs.markPlanningLogSyncError(original.id, 'Offline', version), /Quota/); assert.deepEqual(logs.readPlanningLogs()[0], original); failure = false;
  logs.markPlanningLogSyncError(original.id, 'Offline', version); const saved = logs.readPlanningLogs()[0]; assert.equal(saved.syncError, 'Offline');
  assert.throws(() => logs.markPlanningLogSyncError(original.id, 'Stale response', version), /changed/); assert.deepEqual(logs.readPlanningLogs()[0], saved);
  logs.markPlanningLogSynced(original.id, '11111111-2222-4333-8444-555555555555', logs.planningLogVersion(saved)); const confirmed = logs.readPlanningLogs()[0]; assert.equal(confirmed.syncError, undefined);
  logs.markPlanningLogSyncError(original.id, 'Late error', logs.planningLogVersion(confirmed)); assert.deepEqual(logs.readPlanningLogs()[0], confirmed);
});

test('connection failures record a retry reason, stop the queue, and clear the reason after confirmation', async () => {
  authUser = { id: 'queue-offline' }; await store.initializePlanning(authUser.id);
  const entry = { exerciseId: 'squat', exerciseName: 'Squat', sets: '3', date: '2026-10-12T12:00:00Z' };
  const original = { id: 'offline-first', title: 'First', completedAt: entry.date, entries: [entry] };
  logs.recordPlanningLog(original); logs.recordPlanningLog({ ...original, id: 'offline-second' });
  const keys = []; let online = false;
  save = async (name, payload) => { if (name === 'save_planning_document') return { data: 1, error: null }; keys.push(payload.session_key); return online ? { data: '22222222-3333-4444-8555-666666666666', error: null } : { data: null, error: new Error('Offline test connection') }; };
  await persistence.syncPendingPlanningWorkouts(); assert.deepEqual(keys, ['offline-first']); assert.match(logs.readPlanningLogs()[0].syncError, /Offline/); assert.equal(logs.readPlanningLogs()[1].syncError, undefined);
  online = true; await persistence.syncPendingPlanningWorkouts(); assert.deepEqual(keys, ['offline-first', 'offline-first', 'offline-second']); assert.ok(logs.readPlanningLogs().every(log => logs.planningLogUploadConfirmed(log) && !log.syncError));
});

test('thrown background upload failures save bounded diagnostics without altering completion data', async () => {
  authUser = { id: 'thrown-diagnostic' }; await store.initializePlanning(authUser.id);
  const original = { id: 'throw-session', title: 'Original', completedAt: '2026-10-12T12:00:00Z', entries: [{ exerciseId: 'squat', exerciseName: 'Squat', sets: '3', date: '2026-10-12T12:00:00Z' }] };
  logs.recordPlanningLog(original);
  save = async name => { if (name === 'save_planning_document') return { data: 1, error: null }; throw new Error('Offline ' + 'x'.repeat(3000)); };
  await persistence.syncPendingPlanningWorkouts(); const saved = logs.readPlanningLogs()[0]; const { syncError, ...preserved } = saved;
  assert.deepEqual(preserved, original); assert.equal(syncError.length, 2000); assert.match(syncError, /^Offline/);
  failure = true; assert.doesNotThrow(() => logs.markPlanningLogSyncError(saved.id, syncError, logs.planningLogVersion(saved))); failure = false;
});

