test('recommendations require exact experience evidence and disclose unknown or conflicting profile answers', () => {
  const goal = { primaryGoal: 'Strength', targetWeeklySessions: '6' };
  for (const value of [undefined, '', false, 1, [], {}, 'not advanced', 'Advanced beginner', 'returning advanced', 'Intermediateish']) {
    const profile = { trainingAge: value };
    const before = JSON.stringify(profile);
    assert.deepEqual(recommendations.profileTrainingExperience(profile), { level: null, conflicting: false });
    const rec = recommendations.recommendPlan(profile, goal);
    assert.equal(rec.split, 'Full Body'); assert.equal(rec.phase, 'Foundation');
    assert.ok(rec.reasons.some(reason => /experience is unknown/.test(reason)));
    assert.equal(rec.sessions, 6); assert.equal(JSON.stringify(profile), before);
  }
  const advanced = recommendations.recommendPlan({ trainingAge: ' ADVANCED ' }, goal);
  assert.equal(advanced.split, 'Push / Pull / Legs'); assert.equal(advanced.phase, 'Build');
  assert.equal(recommendations.recommendPlan({ trainingAge: 'invalid', experienceLevel: 'Intermediate' }, goal).split, 'Upper / Lower');
  for (const profile of [{ trainingAge: 'Advanced', experienceLevel: 'Returning' }, { trainingAge: 'Returning', experienceLevel: 'Advanced' }]) {
    const before = JSON.stringify(profile);
    assert.deepEqual(recommendations.profileTrainingExperience(profile), { level: 'Returning', conflicting: true });
    const rec = recommendations.recommendPlan(profile, goal);
    assert.equal(rec.split, 'Full Body'); assert.equal(rec.phase, 'Foundation');
    assert.ok(rec.reasons.some(reason => /answers differ/.test(reason)));
    assert.equal(JSON.stringify(profile), before);
  }
  assert.deepEqual(recommendations.profileTrainingExperience({ trainingAge: 'Beginner', experienceLevel: ' beginner ' }), { level: 'Beginner', conflicting: false });
  assert.equal(recommendations.recommendPlan({ experienceLevel: 'Competitive Athlete' }, goal).split, 'Upper / Lower');
});

test('recommendations tolerate malformed legacy profile lists without inventing age, weekday preference, or recovery reports', () => {
  const goal = { primaryGoal: 'Strength', targetWeeklySessions: '1' };
  const malformed = { age: true, trainingAge: {}, preferredDays: [' ', null, {}, 'Mondayish'], availableEquipment: 'Dumbbells', equipment: { length: 1 }, injuries: 'none', sessionLength: {}, bodyStatus: { hoursSlept: ' ', painLevel: true, sorenessLevel: 99 } };
  const rec = recommendations.recommendPlan(malformed, goal); assert.equal(rec.age, null); assert.equal(rec.split, 'Full Body'); assert.equal(rec.days.find(day => day.training).day, 'Wednesday'); assert.ok(rec.reasons.every(reason => !reason.includes('[object Object]') && !reason.includes('Available equipment:')));
  assert.equal(recommendations.profileAge({ age: ['30'] }), null); assert.equal(recommendations.profileAge({ age: '0x20' }), null); assert.equal(recommendations.profileAge(null), null);
  assert.equal(recommendations.recommendPlan(null, goal).sessions, 1);
  const real = recommendations.recommendPlan({ age: '30', preferredDays: [' fri ', 'Friday', 'WED'], availableEquipment: ['Dumbbells', null, 'Dumbbells'], bodyStatus: { hoursSlept: '5' } }, { ...goal, targetWeeklySessions: '2' });
  assert.equal(real.split, 'Flexible'); assert.deepEqual(real.days.filter(day => day.training).map(day => day.day), ['Wednesday', 'Friday']); assert.ok(real.reasons.some(reason => reason.includes('equipment answers need review')));
});

test('workout matching excludes malformed workout equipment and requires review for malformed Profile equipment', () => {
  const workout = (id, equipment) => ({ id, title: 'Strength workout', exercises: [{ id: 'squat', name: 'Squat', equipment }] });
  const templates = [workout('dumbbell', ' Dumbbells '), workout('barbell', 'Barbell'), workout('unknown', {}), workout('bodyweight', 'Bodyweight')];
  const matches = matching.rankWorkoutTemplates(templates, { availableEquipment: [' ', null, {}], equipment: ['Dumbbell', 'Dumbbells', null] }, 'Strength');
  assert.equal(matches.find(item => item.template.id === 'dumbbell').equipmentConfirmed, false); assert.equal(matches.find(item => item.template.id === 'barbell').equipmentConfirmed, false); assert.equal(matches.some(item => item.template.id === 'unknown'), false); assert.ok(matches.every(item => item.reasons.some(reason => /equipment answers need review/.test(reason))));
  const unknown = matching.rankWorkoutTemplates(templates, { availableEquipment: 'Dumbbells', equipment: {} }, 'Strength'); assert.equal(unknown.find(item => item.template.id === 'dumbbell').equipmentConfirmed, false); assert.equal(unknown.find(item => item.template.id === 'bodyweight').equipmentConfirmed, false); const legacy = matching.rankWorkoutTemplates(templates, { equipment: ['Dumbbells'] }, 'Strength'); assert.equal(legacy.find(item => item.template.id === 'dumbbell').equipmentConfirmed, true); assert.equal(legacy.some(item => item.template.id === 'barbell'), false);
  assert.ok(matches.every(item => item.reasons.some(reason => /duration is unavailable/.test(reason))));
});

test('workout equipment matching reconciles exact Profile and catalog labels without inferring broad categories', () => {
  const workout = (id, equipment) => ({ id, title: 'Strength', exercises: [{ id: 'squat', name: 'Squat', equipment }] });
  const aliases = [['Machines', 'Machine'], ['Med Ball', 'Medicine Ball'], ['Pull-Up', 'Pull-Up Bar'], ['Suspension', 'Suspension Trainer'], ['Cables', 'Cable'], ['Bands', 'Resistance Band'], ['Dumbbells', 'Dumbbell'], ['Kettlebells', 'Kettlebell'], ['Barbells', 'Barbell'], ['Cardio', 'Cardio Equipment']];
  for (const [profileLabel, catalogLabel] of aliases) {
    for (const [available, required] of [[profileLabel, catalogLabel], [catalogLabel, profileLabel]]) {
      const matches = matching.rankWorkoutTemplates([workout('match', required)], { availableEquipment: [` ${available.toUpperCase()} `] }, 'Strength');
      assert.equal(matches.length, 1, `${available} should match ${required}`);
      assert.equal(matches[0].equipmentConfirmed, true);
    }
  }
  for (const [available, required] of [['Cardio', 'Treadmill'], ['Machines', 'Cable'], ['Med Ball', 'Slam Ball'], ['Dumbbells', 'Adjustable Dumbbells'], ['Bodyweight', 'Pull-Up Bar'], ['Resistance Band', 'Resistance Bandage']]) {
    assert.deepEqual(matching.rankWorkoutTemplates([workout('unconfirmed', required)], { equipment: [available] }, 'Strength'), []);
  }
  const original = workout('machine', 'Machine'); const profile = { availableEquipment: ['Machines'] };
  const before = JSON.stringify({ original, profile });
  matching.rankWorkoutTemplates([original], profile, 'Strength');
  assert.equal(JSON.stringify({ original, profile }), before);
});

