test('Full Body evidence requires both upper and lower regions or explicit full-body exercise evidence', () => {
  const workout = (id, names) => ({ id, title: 'Full Body workout', exercises: names.map((name, index) => ({ id: `${id}-${index}`, name, equipment: 'Bodyweight' })) });
  const lower = workout('lower', ['Squat']); const upper = workout('upper', ['Push']);
  const both = workout('both', ['Squat', 'Push']); const tagged = workout('tagged', ['Full-body circuit']);
  const matches = matching.rankWorkoutTemplates([lower, upper, both, tagged], {}, 'Full Body');
  assert.deepEqual(matches.filter(item => item.focusSupported).map(item => item.template.id).sort(), ['both', 'tagged']);
  assert.equal(matches.find(item => item.template.id === 'lower').focusSupported, false);
  assert.match(matches.find(item => item.template.id === 'lower').reasons[0], /only part/);
  const named = workout('named', ['Chest exercise', 'Leg exercise']); named.title = 'Session';
  assert.equal(matching.rankWorkoutTemplates([named], {}, 'FULL-BODY')[0].focusSupported, true);
  const balance = workout('balance', ['Squat', 'Push', 'Balance practice']);
  assert.equal(matching.rankWorkoutTemplates([both], {}, 'Full Body + Balance')[0].focusSupported, false);
  assert.equal(matching.rankWorkoutTemplates([balance], {}, 'Full Body + Balance')[0].focusSupported, true);
  const cardio = workout('cardio', ['Cardio']);
  assert.equal(matching.rankWorkoutTemplates([cardio], {}, 'Full Body / Conditioning')[0].focusSupported, true);
});

