test('workout matching skips malformed templates and empty focus and uses stable ids to resolve equal ranks', () => {
  const workout = id => ({ id, title: 'Strength workout', exercises: [{ id: 'squat', name: 'Squat', equipment: 'Bodyweight' }] });
  const bad = [null, {}, { id: 'no-exercises', title: 'Strength', exercises: null }, { id: 'bad-exercise', title: 'Strength', exercises: [null] }, { id: 'missing-id', title: 'Strength', exercises: [{ name: 'Squat' }] }, { ...workout('blank'), title: ' ' }];
  const matches = matching.rankWorkoutTemplates([...bad, workout('z'), workout('a')], null, 'Strength'); assert.deepEqual(matches.map(item => item.template.id), ['a', 'z']);
  assert.deepEqual(matching.rankWorkoutTemplates([workout('valid')], {}, ''), []); assert.deepEqual(matching.rankWorkoutTemplates([workout('valid')], {}, '  '), []); assert.deepEqual(matching.rankWorkoutTemplates(null, {}, 'Strength'), []);
});

