test('manual assignment refuses deleted, stale, or malformed saved workouts without changing the week', () => {
  goals.saveGoalsRecord(sampleGoals());
  const plan = plans.createWorkoutPlan().plan;
  const template = { id: 'manual', title: 'Reviewed workout', exercises: [{ id: 'squat', name: 'Squat' }] };
  const assign = () => plans.assignTemplateToPlanDay({ planId: plan.id, dayId: plan.days[0].id, template });
  for (const library of [[], [{ ...template, title: 'Changed' }], [{ ...template, exercises: [{ id: 'squat', name: 'Changed movement' }] }]]) {
    store.writePlanning(store.planningKeys.templates, library);
    const before = store.planningSnapshot();
    assert.throws(assign, /changed or is no longer available/); assert.equal(store.planningSnapshot(), before);
  }
  const malformed = { ...template, exercises: [{ id: 'squat' }] };
  store.writePlanning(store.planningKeys.templates, [malformed]);
  let before = store.planningSnapshot();
  assert.throws(() => plans.assignTemplateToPlanDay({ planId: plan.id, dayId: plan.days[0].id, template: malformed }), /Review this saved workout/);
  assert.equal(store.planningSnapshot(), before);
  store.writePlanning(store.planningKeys.templates, [{ ...template, cloudRevision: 5 }]);
  before = store.planningSnapshot(); failure = true;
  try { assert.throws(assign, /Quota exceeded/); assert.equal(store.planningSnapshot(), before); }
  finally { failure = false; }
  const saved = assign(); assert.equal(saved.assignment.templateTitle, template.title); assert.equal(saved.assignment.templateExerciseCount, 1);
});

test('reviewing an assigned template preserves scheduling, notes, source, custom data and ordering', () => {
  goals.saveGoalsRecord(sampleGoals());
  const plan = plans.createWorkoutPlan().plan;
  const template = saveAssignmentTemplateFixture({ id: 'reviewed', title: 'Strength', exercises: [{ id: 'squat', name: 'Squat' }] });
  const input = { planId: plan.id, dayId: plan.days[0].id, template };
  const first = plans.assignTemplateToPlanDay({ ...input, focus: 'Custom focus', notes: 'Keep this instruction', source: 'builder-template' }).assignment;
  plans.updatePlanAssignment(plan.id, plan.days[0].id, first.id, { time: '14:45', setsPerExercise: 5 });
  const originals = plans.readWorkoutPlans();
  originals[0].days[0].assignments[0].customData = { original: true };
  plans.writeWorkoutPlans(originals);
  const before = store.planningSnapshot();
  for (const fields of [{ source: 'invalid' }, { source: null }, { source: ['manual'] }, { notes: null }, { notes: {} }, { focus: false }]) {
    assert.throws(() => plans.assignTemplateToPlanDay({ ...input, ...fields }));
    assert.equal(store.planningSnapshot(), before);
  }
  const changed = { ...template, title: 'Reviewed Strength', exercises: [{ id: 'squat', name: 'Reviewed squat' }] };
  store.writePlanning(store.planningKeys.templates, [changed]);
  const savedOriginal = plans.readWorkoutPlans()[0].days[0].assignments[0];
  const refreshed = plans.assignTemplateToPlanDay({ ...input, template: changed }).assignment;
  assert.deepEqual(refreshed, { ...savedOriginal, templateTitle: changed.title, templateContentVersion: refreshed.templateContentVersion, updatedAt: refreshed.updatedAt });
  assert.notEqual(refreshed.templateContentVersion, savedOriginal.templateContentVersion);
  assert.equal(plans.assignmentTemplateIssue(refreshed, changed), null);
  const cleared = plans.assignTemplateToPlanDay({ ...input, template: changed, focus: '', notes: '', source: 'manual' }).assignment;
  assert.equal(cleared.focus, ''); assert.equal(cleared.notes, ''); assert.equal(cleared.source, 'manual');
  assert.equal(cleared.time, '14:45'); assert.equal(cleared.setsPerExercise, 5); assert.deepEqual(cleared.customData, { original: true });
});

