test('assigned workout content changes require explicit reassignment before launch and preserve originals', () => {
  goals.saveGoalsRecord(sampleGoals());
  const plan = plans.createWorkoutPlan().plan;
  const template = saveAssignmentTemplateFixture({ id: 'versioned', title: 'Strength', exercises: [{ id: 'squat', name: 'Squat' }] });
  const input = { planId: plan.id, dayId: plan.days[0].id, template };
  const first = plans.assignTemplateToPlanDay(input).assignment;
  assert.equal(typeof first.templateContentVersion, 'string');
  const changed = { ...template, exercises: [{ id: 'squat', name: 'Different squat' }] };
  store.writePlanning(store.planningKeys.templates, [changed]);
  let before = store.planningSnapshot();
  assert.match(plans.assignmentTemplateIssue(first, changed), /changed since assignment/);
  assert.throws(() => plans.startPlanWorkout(plan.id, plan.days[0].id, first.id, changed), /changed since assignment/);
  assert.equal(store.planningSnapshot(), before);
  const refreshed = plans.assignTemplateToPlanDay({ ...input, template: changed }).assignment;
  assert.equal(refreshed.id, first.id); assert.notEqual(refreshed.templateContentVersion, first.templateContentVersion);
  assert.equal(plans.assignmentTemplateIssue(refreshed, changed), null);
  plans.startPlanWorkout(plan.id, plan.days[0].id, refreshed.id, changed);
  const legacy = { ...first }; delete legacy.templateContentVersion;
  assert.equal(plans.assignmentTemplateIssue(legacy, changed), null, 'legacy same-count edits have no invented baseline');
  assert.match(plans.assignmentTemplateIssue(legacy, { ...changed, title: 'New title' }), /title or exercise count/);
  assert.match(plans.assignmentTemplateIssue(legacy, undefined), /unavailable/);
});

