  const item = calendar.plannedCalendarItems().find(item => item.assignmentId === assignment.id);
  let editor = calendar.captureCalendarEditor();
  const previousLaunch=plans.startPlanWorkout(plan.id,plan.days[0].id,assignment.id,template);store.writePlanning(store.planningKeys.context, { ...previousLaunch.context,id: 'preserve-session', notes: 'My original session' });editor=calendar.captureCalendarEditor();
