  const started = plans.startPlanWorkout(plan.id, plan.days[0].id, assignment.id, template);
  const editor = drafts.writeWorkoutDraft(drafts.captureWorkoutDraftEditor(started.sessionTemplate), { id: started.context.id, logs: { 2: { weight: '0', reps: '8', sets: '3' } } });
  drafts.resumeWorkoutDraft(editor.key, editor.draftVersion, store.planningOwner(), store.planningAccountGeneration());
