test('checkout return origin uses configured server address and rejects cross-origin or malformed callers', () => {
  const { checkoutOrigin } = load('lib/checkoutOrigin.ts');
  const environment = { APP_URL: 'https://fitness.example/', NEXT_PUBLIC_APP_URL: 'https://ignored.example', NODE_ENV: 'production' };
  const request = origin => new Request('https://spoofed-host.example/api/stripe/embedded-checkout', { headers: origin == null ? {} : { origin } });
  assert.equal(checkoutOrigin(request('https://fitness.example'), environment), 'https://fitness.example');
  assert.equal(checkoutOrigin(request(null), environment), 'https://fitness.example');
  for (const caller of ['https://attacker.example', 'null', 'https://fitness.example/path', 'https://fitness.example?redirect=x', 'https://user@fitness.example', 'http://fitness.example']) {
    assert.throws(() => checkoutOrigin(request(caller), environment), error => error.status === 403);
  }
  assert.throws(() => checkoutOrigin(request(null), { ...environment, APP_URL: 'https://fitness.example/path' }), error => error.status === 503);
});

test('checkout requires secure production configuration and permits only loopback development fallback', () => {
  const { checkoutOrigin } = load('lib/checkoutOrigin.ts');
  const remote = new Request('https://fitness.example/api/stripe/embedded-checkout');
  for (const APP_URL of [undefined, 'http://fitness.example', 'https://localhost', 'https://127.0.0.1', 'ftp://fitness.example', 'https://fitness.example#fragment']) {
    assert.throws(() => checkoutOrigin(remote, { APP_URL, NODE_ENV: 'production' }), error => error.status === 503);
  }
  assert.throws(() => checkoutOrigin(remote, { NODE_ENV: 'development' }), error => error.status === 503);
  for (const host of ['localhost', '127.0.0.1', '[::1]']) {
    const origin = `http://${host}:3000`;
    assert.equal(checkoutOrigin(new Request(`${origin}/api/stripe/embedded-checkout`, { headers: { origin } }), { NODE_ENV: 'development' }), origin);
  }
  assert.equal(checkoutOrigin(remote, { NEXT_PUBLIC_APP_URL: 'https://fitness.example', NODE_ENV: 'production' }), 'https://fitness.example');
});

test('checkout route rejects malformed JSON bodies and untrusted origins before payment creation', async () => {
  const route = load('app/api/stripe/embedded-checkout/route.ts');
  for (const body of ['null', '[]', 'true', '"online-coaching"', '{}', '{"planId":42}', '{"planId":"other"}', 'not-json']) {
    const response = await route.POST(new Request('http://localhost:3000/api/stripe/embedded-checkout', { method: 'POST', headers: { 'content-type': 'application/json' }, body }));
    assert.equal(response.status, 400);
  }
  const previous = process.env.APP_URL;
  try {
    process.env.APP_URL = 'https://fitness.example';
    const response = await route.POST(new Request('https://fitness.example/api/stripe/embedded-checkout', { method: 'POST', headers: { origin: 'https://attacker.example', 'content-type': 'application/json' }, body: '{"planId":"online-coaching"}' }));
    assert.equal(response.status, 403);
    assert.match((await response.json()).error, /Sound Fitness app/);
  } finally { if (previous === undefined) delete process.env.APP_URL; else process.env.APP_URL = previous; }
});

test('enrollment confirmation requires completed subscription, matching plan and exact configured price', () => {
  const { checkEnrollmentSession, validCheckoutSessionId } = load('lib/checkoutConfirmation.ts');
  const session = { mode: 'subscription', metadata: { planId: 'online-coaching' }, status: 'complete', payment_status: 'paid', subscription: 'sub_example', customer_details: { email: 'member@example.test' }, line_items: { has_more: false, data: [{ quantity: 1, price: { id: 'price_coaching' } }] } };
  assert.deepEqual(checkEnrollmentSession(session, 'price_coaching'), { state: 'paid', planId: 'online-coaching', email: 'member@example.test' });
  assert.equal(checkEnrollmentSession({ ...session, payment_status: 'no_payment_required', subscription: { id: 'sub_example' } }, 'price_coaching').state, 'paid');
  for (const patch of [{ mode: 'payment' }, { metadata: { planId: 'app-only' } }, { metadata: null }, { subscription: null }, { payment_status: 'unknown' }, { status: 'unknown' }, { line_items: null }, { line_items: { has_more: true, data: session.line_items.data } }, { line_items: { has_more: false, data: [] } }, { line_items: { has_more: false, data: [{ quantity: 2, price: { id: 'price_coaching' } }] } }, { line_items: { has_more: false, data: [{ quantity: 1, price: { id: 'price_other' } }] } }]) assert.equal(checkEnrollmentSession({ ...session, ...patch }, 'price_coaching').state, 'unverified');
  assert.equal(checkEnrollmentSession(session, undefined).state, 'unverified');
  assert.equal(checkEnrollmentSession({ ...session, status: 'open' }, 'price_coaching').state, 'unpaid');
  assert.equal(checkEnrollmentSession({ ...session, status: 'expired' }, 'price_coaching').state, 'unpaid');
  assert.equal(checkEnrollmentSession({ ...session, payment_status: 'unpaid' }, 'price_coaching').state, 'unpaid');
  for (const value of ['cs_test_example123', 'cs_live_example123', 'cs_example123']) assert.equal(validCheckoutSessionId(value), true);
  for (const value of [undefined, null, true, 'other_id', 'cs_test_', 'cs_test_x?other=1', 'cs_test_' + 'x'.repeat(300)]) assert.equal(validCheckoutSessionId(value), false);
});

test('goal labels use exact supported aliases and never inherited or substring matches', () => {
  for (const value of ['toString', 'constructor', '__proto__', 'not Strength', 'Strengthening', 'Build Muscle later', {}, true]) {
    assert.equal(goals.normalizeGoalId(value), undefined);
    assert.deepEqual(goals.normalizeGoals({ primaryGoal: value }).planDirections, []);
  }
  for (const [value, expected] of [[' bulk ', 'Build Muscle'], ['CUT', 'Lose Fat'], ['build strength', 'Strength'], [' Improve Mobility ', 'Mobility'], ['Athletic Performance', 'Performance'], ['Return to Training', 'Recovery'], [' general health ', 'General Health']]) assert.equal(goals.normalizeGoalId(value), expected);
  assert.deepEqual(goals.normalizeGoals({ primaryGoal: 'Strength', secondaryGoal: 'Strength' }).planDirections, ['Strength']);
  assert.deepEqual(goals.normalizeGoals(null).planDirections, []);
});

test('unsupported saved goal directions cannot create plans or overwrite goals and projected profile', () => {
  const valid = { ...sampleGoals(), updatedAt: new Date().toISOString() };
  store.writePlanning(store.planningKeys.profile, { marker: 'preserve' });
  for (const patch of [{ planDirections: ['toString'] }, { planDirections: ['Strength', 'unsupported'] }, { planDirections: ['Strength', 'Mobility', 'Recovery'] }, { primaryGoal: 'not Strength' }, { secondaryGoal: 'constructor' }, { planDirections: 'Strength' }]) {
    const candidate = { ...valid, ...patch };
    store.writePlanning(store.planningKeys.goals, candidate);
    const original = store.planningRecordVersion(store.planningKeys.goals);
    assert.throws(() => goals.requireSavedGoals(), /direction/i);
    assert.throws(() => plans.createWorkoutPlan(), /direction/i);
    assert.throws(() => goals.saveGoalsRecord(candidate, { marker: 'overwrite' }), /direction/i);
    assert.equal(store.planningRecordVersion(store.planningKeys.goals), original);
    assert.equal(store.readPlanning(store.planningKeys.profile, null).marker, 'preserve');
  }
  store.writePlanning(store.planningKeys.goals, { ...valid, planDirections: [' build strength ', 'Improve Mobility'], primaryGoal: 'Build Strength', secondaryGoal: 'Improve Mobility' });
  assert.deepEqual(goals.requireSavedGoals().planDirections, ['Strength', 'Mobility']);
});

