test('saved goal timestamps require text and reject future evidence while explicit goal save can repair the timestamp', () => {
  const now = new Date('2026-10-12T18:00:00Z');
  const valid = { ...sampleGoals(), updatedAt: now.toISOString() };
  assert.equal(goals.savedGoalsIssue(valid, now), null);
  assert.equal(goals.savedGoalsIssue({ ...valid, updatedAt: '2026-10-12T18:04:59Z' }, now), null);
  for (const updatedAt of [now.getTime(), 1, true, [], {}, 'invalid']) {
    assert.match(goals.savedGoalsIssue({ ...valid, updatedAt }, now), /Save your primary goal/);
  }
  assert.match(goals.savedGoalsIssue({ ...valid, updatedAt: '2026-10-12T18:05:01Z' }, now), /future/);
  assert.equal(trainingJourney.trainingJourneyState({ goals: { ...valid, updatedAt: '2026-10-13T18:00:00Z' }, plans: [], logs: [] }, now).recorded.goals, false);
  goals.saveGoalsRecord(sampleGoals());
  const plan = plans.createWorkoutPlan().plan;
  const future = { ...valid, updatedAt: new Date(Date.now() + 86400000).toISOString() };
  store.writePlanning(store.planningKeys.goals, future);
  const before = store.planningSnapshot();
  assert.throws(() => goals.requireSavedGoals(), /future/);
  assert.throws(() => plans.markPlanGoalsReviewed(plan.id, future.updatedAt, plans.capturePlanEditor()), /future/);
  assert.equal(store.planningSnapshot(), before);
  const repaired = goals.saveGoalsRecord(future);
  assert.equal(goals.savedGoalsIssue(repaired), null);
  assert.equal(repaired.targetWeeklySets, future.targetWeeklySets);
  assert.equal(plans.readWorkoutPlans()[0].goalsUpdatedAt, plan.goalsUpdatedAt);
});

test('raw goal metadata and milestone collections refuse silent normalization before saving or planning', () => {
  const valid = { ...sampleGoals(), updatedAt: new Date().toISOString() };
  const invalid = [];
  for (const field of ['constraintGoal', 'goalDeadline', 'goalMilestones', 'goalPriorityRanking', 'benchmarkGoal', 'motivationFocus', 'planDirectionNotes']) {
    for (const value of [true, 123, [], {}]) invalid.push({ ...valid, [field]: value });
  }
  for (const completedMilestones of [true, 'done', [123], [''], ['done', 'done']]) invalid.push({ ...valid, completedMilestones });
  for (const candidate of invalid) {
    store.writePlanning(store.planningKeys.goals, candidate);
    const before = store.planningSnapshot();
    assert.match(goals.savedGoalsIssue(candidate), /Review/);
    assert.match(goals.goalSetupNextStep(candidate), /Review/);
    assert.throws(() => goals.requireSavedGoals(), /Review/);
    assert.throws(() => goals.saveGoalsRecord(candidate, { marker: 'must not save' }), /Review/);
    assert.equal(store.planningSnapshot(), before);
  }
  assert.equal(goals.savedGoalsIssue({ ...valid, completedMilestones: ['First session', 'Review week'] }), null);
  assert.equal(goals.savedGoalsIssue({ ...valid, goalMilestones: undefined, completedMilestones: undefined }), null);
});

test('progress target eligibility uses original goals and the reporting clock without rewriting evidence', () => {
  const now = new Date('2026-10-12T18:00:00Z');
  const valid = { ...sampleGoals(), updatedAt: now.toISOString() };
  const summary = goalsRecord => progress.buildProgressSummary({ logs: [], goals: goalsRecord, plans: [], checkIns: [], journal: [] }, now);
  assert.ok(summary(valid).goals.some(goal => goal.title.includes('workouts this week')));
  for (const candidate of [
    { ...valid, updatedAt: '2026-10-13T18:00:00Z' },
    { ...valid, updatedAt: 1 },
    { ...valid, goalMilestones: true },
    { ...valid, completedMilestones: ['done', 'done'] },
  ]) {
    const original = JSON.stringify(candidate);
    const result = summary(candidate);
    assert.equal(result.goals.some(goal => goal.title.includes('workouts this week') || goal.title.includes('sets this week')), false);
    assert.equal(JSON.stringify(candidate), original);
  }
});


