test('library guidance covers every canonical goal and only shared exact aliases', () => {
  const guidance=load('lib/planning/libraryGoalGuidance.ts');const ids=goals.goalIds;const labels=new Set();for(const goal of ids){const result=guidance.libraryGoalGuidance(goal);assert.equal(result.goalId,goal);assert.notEqual(result.emphasisLabel,'Set goals first');assert.ok(result.goalCue);labels.add(result.emphasisLabel);}assert.equal(labels.size,ids.length);
  for(const alias of ['Bulk','Cut','Build Strength','Improve Mobility','Athletic Performance','Return to Training','  BUILD MUSCLE  '])assert.equal(guidance.libraryGoalGuidance(alias).goalId,goals.normalizeGoalId(alias));
  for(const input of [undefined,null,'','No goal set','Strength and muscle','Hypertrophy','Fat Loss','power','__proto__','constructor','toString',{},[],false]){const result=guidance.libraryGoalGuidance(input);assert.equal(result.goalId,null);assert.equal(result.emphasisLabel,'Set goals first');assert.match(result.goalCue,/Save a supported primary goal/);}
  const first=guidance.libraryGoalGuidance('Strength');first.emphasisLabel='Mutated';assert.notEqual(guidance.libraryGoalGuidance('Strength').emphasisLabel,'Mutated');
});

