  const entries=[base,a,b,{...a,exerciseId:'other'},{...a,exerciseId:undefined},{...a,date:'2026-10-14T12:00:00Z'},{...a,date:'invalid'},{...a,sets:'3bad'},{...a,sets:'0'}];const original=JSON.stringify(entries);
  assert.deepEqual(history.libraryExerciseHistory(entries,{exerciseId:'squat',variationId:'a',scope:'variation'},now),[a]);assert.deepEqual(history.libraryExerciseHistory(entries,{exerciseId:'squat',scope:'exercise'},now),[base,a,b]);assert.deepEqual(history.libraryExerciseHistory(entries,{exerciseId:'missing',variationId:'a',scope:'variation'},now),[]);assert.deepEqual(history.libraryExerciseHistory(entries,{exerciseId:'squat',scope:'variation'},now),[]);
