test('library logger validates complete whole counts and canonical displayed loads before saving', () => {
  const save=load('lib/planning/libraryStatSave.ts');const draft={weight:'20',unit:'kg',reps:'8',sets:'3'};const original=JSON.stringify(draft);const good=save.prepareLibraryStatDraft(draft);assert.equal(good.success,true);assert.equal(good.values.weightUnit,'lb');assert.equal(good.values.reps,'8');assert.ok(Math.abs(Number(good.values.weight)*0.45359237-20)<1e-10);assert.equal(save.prepareLibraryStatDraft({...draft,weight:'0'}).success,true);
  for(const field of ['reps','sets'])for(const value of ['', '3bad','3 sets','0','-1','1.5','2147483648',false,[],{}])assert.equal(save.prepareLibraryStatDraft({...draft,[field]:value}).success,false);
  for(const patch of [{weight:'-1'},{weight:'20kg'},{weight:'Infinity'},{unit:'stones'},{unit:'lb'}])assert.equal(save.prepareLibraryStatDraft({...draft,...patch}).success,false);assert.equal(JSON.stringify(draft),original);
});

test('library activity save protects revisions, malformed collections, quota failures and duplicate submissions', () => {
  const save=load('lib/planning/libraryStatSave.ts');const key=store.planningKeys.exerciseStats;const legacy={exerciseId:'old',exerciseName:'Old',weight:'20',reps:'5',sets:'2',date:new Date(Date.now()-2000).toISOString()};store.writePlanning(key,[legacy]);const editor=save.captureLibraryStatEditor();const entry={exerciseId:'squat',exerciseName:'Squat',weight:'0',weightUnit:'lb',reps:'8',sets:'3',source:'exercise-library',date:new Date(Date.now()-1000).toISOString(),selectedModifierIds:['wide']};const original=store.planningRecordVersion(key);
  failure=true;try{assert.throws(()=>save.saveLibraryStatEntry(entry,editor),/Quota/);}finally{failure=false;}assert.equal(store.planningRecordVersion(key),original);
  const stored=save.saveLibraryStatEntry(entry,editor);assert.deepEqual(store.readPlanning(key,[]),[entry,legacy]);entry.selectedModifierIds.push('mutated');assert.deepEqual(stored.selectedModifierIds,['wide']);const after=store.planningRecordVersion(key);assert.throws(()=>save.saveLibraryStatEntry(entry,editor),/Activity changed/);assert.equal(store.planningRecordVersion(key),after);assert.throws(()=>save.saveLibraryStatEntry(entry,null),/before saving another/);
  store.writePlanning(key,{original:'malformed collection'});const malformed=store.planningRecordVersion(key);assert.throws(()=>save.saveLibraryStatEntry(entry,save.captureLibraryStatEditor()),/Saved activity needs review/);assert.equal(store.planningRecordVersion(key),malformed);
});

