  const save=load('lib/planning/libraryStatSave.ts');const key=store.planningKeys.exerciseStats;const entry={exerciseId:'squat',exerciseName:'Squat',weight:'20',weightUnit:'lb',reps:'8',sets:'3',source:'exercise-library',date:new Date(Date.now()-1000).toISOString()};const editor=save.captureLibraryStatEditor();const original=store.planningRecordVersion(key);
