  await store.initializePlanning('library-save-other');const other=store.planningRecordVersion(key);assert.throws(()=>save.saveLibraryStatEntry(entry,editor),/account changed/);assert.equal(store.planningRecordVersion(key),other);await store.initializePlanning(null);assert.equal(store.planningRecordVersion(key),original);
