test('actual library save handler retains refused inputs and prevents duplicate stale-render submissions', () => {
  const saving=load('lib/planning/libraryStatSave.ts');const source=fs.readFileSync(path.join(root,'app/dashboard/workout-builder/exercise-library/page.tsx'),'utf8');const ast=ts.createSourceFile('library.tsx',source,ts.ScriptTarget.Latest,true,ts.ScriptKind.TSX);let declaration;function visit(node){if(ts.isVariableDeclaration(node)&&node.name.getText(ast)==='saveStatsEntry')declaration=node;ts.forEachChild(node,visit);}visit(ast);assert.ok(declaration);const code=ts.transpileModule('const saveStatsEntry='+declaration.initializer.getText(ast)+';exports.save=saveStatsEntry;',{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;
  function handler(reps){const errors=[];const cleared=[];const ref={current:saving.captureLibraryStatEditor()};const exported={};new Function('exports','statsExercise','statWeight','statReps','statSets','preferredWeightUnit','prepareLibraryStatDraft','saveLibraryStatEntry','statsEditorRef','setStatsSaveError','buildLatestSetInsight','savedExerciseStats','weeklySetsSummary','setSavedExerciseStats','setLatestSetInsight','setStatWeight','setStatReps','setStatSets','statsMenuMode','closeStatsMenu',code)(exported,{id:'squat',name:'Squat'},'20',reps,'3','lbs',saving.prepareLibraryStatDraft,saving.saveLibraryStatEntry,ref,value=>errors.push(value),()=>({}),[],{},()=>{},()=>{},value=>cleared.push(['weight',value]),value=>cleared.push(['reps',value]),value=>cleared.push(['sets',value]),'detail',()=>{});return {save:exported.save,errors,cleared,ref};}
  const invalid=handler('3bad');const before=store.planningRecordVersion(store.planningKeys.exerciseStats);invalid.save();assert.match(invalid.errors.at(-1),/positive whole/);assert.deepEqual(invalid.cleared,[]);assert.equal(store.planningRecordVersion(store.planningKeys.exerciseStats),before);
  const valid=handler('8');failure=true;try{valid.save();}finally{failure=false;}assert.match(valid.errors.at(-1),/Quota/);assert.deepEqual(valid.cleared,[]);assert.equal(store.planningRecordVersion(store.planningKeys.exerciseStats),before);
  valid.save();assert.equal(store.readPlanning(store.planningKeys.exerciseStats,[]).length,1);assert.equal(valid.ref.current,null);assert.equal(valid.cleared.length,3);valid.save();assert.equal(store.readPlanning(store.planningKeys.exerciseStats,[]).length,1);assert.equal(valid.cleared.length,3);assert.match(valid.errors.at(-1),/before saving another/);
  assert.equal((source.match(/statsSaveError \? <p role="alert"/g)||[]).length,2);assert.doesNotMatch(source,/prependExerciseStats/);
});


