test('library momentum requires target evidence and never labels set ratios as readiness or fatigue', () => {
  const {libraryMomentum}=load('lib/planning/libraryMomentum.ts');
  for(const target of [null,0,-1,1.5,NaN,Infinity,Number.MAX_SAFE_INTEGER+1]){const result=libraryMomentum(80,target);assert.equal(result.id,'not-set');assert.equal(result.percentLabel,'—');assert.equal(result.fillPercent,0);}
  for(const percent of [NaN,Infinity,-1])assert.equal(libraryMomentum(percent,10).id,'not-set');
  for(const percent of [0,20,20.5,45,45.5,75,90,90.5,150]){const result=libraryMomentum(percent,10);assert.notEqual(result.id,'not-set');assert.equal(result.fillPercent,Math.min(100,percent));assert.doesNotMatch(result.label,/fresh|hot|fatigue|ready|productive/i);assert.match(result.recommendation,/does not assess/);}
});

