test('plan activation requires exact current goal review across switching, editing and active duplication', () => {
  const saved=goals.saveGoalsRecord(sampleGoals());const first=plans.createWorkoutPlan({title:'Current active week',status:'active'}).plan;const next=plans.duplicatePlanToNextWeek(first.id).plan;store.writePlanning(store.planningKeys.goals,{...saved,targetWeeklySets:'48'});const before=store.planningSnapshot();
  for(const action of [()=>plans.setActiveWorkoutPlan(next.id),()=>plans.updateWorkoutPlan(next.id,{status:'active'}),()=>plans.duplicatePlanToNextWeek(next.id,{status:'active'})]){assert.throws(action,/mark them reviewed before activating/);assert.equal(store.planningSnapshot(),before);assert.equal(plans.getActiveWorkoutPlanId(),first.id);}
  const reviewed=plans.markPlanGoalsReviewed(next.id,saved.updatedAt,plans.capturePlanEditor(next)).plan;assert.deepEqual(reviewed.days,next.days);plans.setActiveWorkoutPlan(next.id);assert.equal(plans.getActiveWorkoutPlanId(),next.id);assert.equal(plans.readWorkoutPlans().find(p=>p.id===first.id).status,'draft');assert.equal(plans.readWorkoutPlans().filter(p=>p.status==='active').length,1);
});

