test('template refresh rechecks originals after cloud fetch and refuses ambiguous cloud identities', async () => {
  authUser={id:'member'};await store.initializePlanning('member');const previousFrom=fakeSupabase.from;const local={id:'merge-original',title:'Local',exercises:[],createdAt:'',updatedAt:''};store.writePlanning(store.planningKeys.templates,[local]);let damage=true;let duplicateCloud=false;
  try{fakeSupabase.from=table=>({select(){return this;},eq(){return this;},in(){return this;},order(){return this;},abortSignal(){if(table==='workout_templates'){if(damage)store.writePlanning(store.planningKeys.templates,[local,{...local,title:'Other local original'}]);return Promise.resolve({data:[{id:'server',client_key:'cloud-id',title:'Cloud',revision:1,created_at:'',updated_at:''},...(duplicateCloud?[{id:'server-two',client_key:'cloud-id',title:'Other cloud original',revision:1,created_at:'',updated_at:''}]:[])],error:null});}return Promise.resolve({data:[],error:null});}});
    let result=await persistence.loadWorkoutTemplatesWithFallback();assert.equal(result.success,false);assert.match(result.error,/library needs review/);assert.deepEqual(store.readPlanning(store.planningKeys.templates,[]),[local,{...local,title:'Other local original'}]);
    damage=false;duplicateCloud=true;store.writePlanning(store.planningKeys.templates,[local]);const before=store.planningSnapshot();result=await persistence.loadWorkoutTemplatesWithFallback();assert.equal(result.success,false);assert.match(result.error,/Cloud workout library needs review/);assert.deepEqual(result.data,[local]);assert.equal(store.planningSnapshot(),before);
    duplicateCloud=false;result=await persistence.loadWorkoutTemplatesWithFallback();assert.equal(result.success,true);assert.equal(result.data.length,2);assert.ok(result.data.some(t=>t.id===local.id));assert.ok(result.data.some(t=>t.id==='cloud-id'));
  }finally{fakeSupabase.from=previousFrom;}
});


