test('actual Builder archive handler preserves its editor on failure and advances only after an atomic keep', () => {
  const source=fs.readFileSync(path.join(root,'app/dashboard/workout-builder/page.tsx'),'utf8');const ast=ts.createSourceFile('builder.tsx',source,ts.ScriptTarget.Latest,true,ts.ScriptKind.TSX);let node;function visit(n){if(ts.isFunctionDeclaration(n)&&n.name?.text==='archiveKeptBuilderDraft')node=n;ts.forEachChild(n,visit);}visit(ast);assert.ok(node);const code=ts.transpileModule(node.getText(ast)+'\nexports.archive=archiveKeptBuilderDraft;',{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;const drafts=load('lib/planning/builderDraft.ts');store.writePlanning(store.planningKeys.builderDraft,{malformed:'Preserve me'});const ref={current:drafts.captureBuilderDraftEditor()};const editor=ref.current;const form=builderDraftFixture();let status='';const exported={};new Function('exports','builderDraftEditorRef','captureBuilderDraftEditor','builderAccount','archiveAndKeepBuilderDraft','currentBuilderDraft','setTemplateStatus',code)(exported,ref,drafts.captureBuilderDraftEditor,store.planningOwner(),drafts.archiveAndKeepBuilderDraft,()=>form,value=>status=value);const before=store.planningSnapshot();failure=true;try{exported.archive();}finally{failure=false;}assert.match(status,/Quota/);assert.equal(ref.current,editor);assert.equal(store.planningSnapshot(),before);exported.archive();assert.match(status,/Previous kept draft archived/);assert.equal(ref.current.reviewed,true);assert.deepEqual(drafts.restoreBuilderDraft(ref.current,form.exercises).form,form);const archive=Object.entries(store.planningSnapshot()).find(([key])=>key.startsWith(drafts.BUILDER_DRAFT_ARCHIVE_PREFIX))[1];assert.deepEqual(archive.originalDraft,{malformed:'Preserve me'});
});

