test('configured plan save rejects birthday rollover without changing Profile, Goals, plans or the open input', () => {
  const RealDate=global.Date;let now=new RealDate(2026,9,12,23,59).getTime();global.Date=class extends RealDate{constructor(...args){super(...(args.length?args:[now]));}static now(){return now;}};
  try{
    goals.saveGoalsRecord(sampleGoals());store.writePlanning(store.planningKeys.profile,{birthday:'1961-10-13'});const input={planId:null,title:'Open reviewed plan',goal:'Strength',weekStartDate:dates.localDate(),settings:{weeklyTarget:'1 workout'},trainingDays:[{day:'Monday',focus:'Strength',notes:'Keep these unsaved choices'}],editor:plans.capturePlanEditor(),assignMatches:false,templates:[],profile:{birthday:'1961-10-13'}};assert.equal(input.editor.recommendationAge,64);const before=store.planningSnapshot();const original=JSON.stringify(input);now=new RealDate(2026,9,13,0,1).getTime();assert.throws(()=>plans.saveWorkoutPlanConfiguration(input),/age context changed/);assert.equal(store.planningSnapshot(),before);assert.equal(JSON.stringify(input),original);const refreshed={...input,editor:plans.capturePlanEditor()};assert.equal(refreshed.editor.recommendationAge,65);const saved=plans.saveWorkoutPlanConfiguration(refreshed).plan;assert.equal(saved.days.find(d=>d.dayOfWeek==='Monday').notes,'Keep these unsaved choices');
  }finally{global.Date=RealDate;}
});

