function occurrenceBuilderHandlerFixture(template, catalog=[]) {
  const source=fs.readFileSync(path.join(root,'app/dashboard/workout-builder/page.tsx'),'utf8');const ast=ts.createSourceFile('builder.tsx',source,ts.ScriptTarget.Latest,true,ts.ScriptKind.TSX);const wanted=new Set(['loadTemplate','buildCurrentTemplate','currentBuilderDraft']);const nodes=[];
  function visit(n){if(ts.isFunctionDeclaration(n)&&wanted.has(n.name?.text))nodes.push(n);ts.forEachChild(n,visit);}visit(ast);assert.equal(nodes.length,3);
  const code=ts.transpileModule(nodes.map(n=>n.getText(ast)).join('\n')+'\nexports.api={loadTemplate,buildCurrentTemplate,currentBuilderDraft};',{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;
  const model=load('lib/planning/builderExerciseOccurrences.ts'),guard=load('lib/planning/builderSelectionEditor.ts'),editor=load('lib/planning/builderTemplateEditor.ts');const selectionRef={current:guard.captureBuilderSelectionEditor()},templateEditorRef={current:null};const context={exports:{},builderAccount:store.planningOwner(),templateEditorRef,...model,...editor,exerciseOptions:catalog,title:'Unsaved',templateSections:emptyOccurrenceLayout(),createTemplateSections:()=>emptyOccurrenceLayout(),writeWorkoutBuilderSelectedExercises:records=>selectionRef.current=guard.commitBuilderSelection(records,selectionRef.current),setSelected:v=>context.selected=v,setTemplateSections:v=>context.templateSections=v,setTitle:v=>context.title=v,setTemplateStatus:v=>context.status=v,getNormalizedTemplateTitle:v=>v.trim(),createLocalTemplateId:()=> 'new-id'};
  // Keep lexical component inputs current between separate simulated renders.
  function render(){const output={};const current={...context,exports:output};new Function(...Object.keys(current),code)(...Object.values(current));return output.api;}
  return {context,render,templateEditorRef,selectionRef,template};
}

