  const context={exports:{},dashboardPlanEvidence:evidence,dashboardSummary:{planSessionsAttended:evidence.completed,planSessionTarget:evidence.target},dashboardDateFormatter:new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric'}),formatHeaderMeterDeadline:date=>date.toISOString(),formatHeaderMeterFullDateTime:date=>date.toISOString()};new Function(...Object.keys(context),code)(...Object.values(context));return context.exports.labels;
