function dashboardCompletionFixture(id,day=13,hour=10) {
  const date=new Date(2026,9,day,hour).toISOString();return {id,title:'Completed workout',completedAt:date,entries:[{id:'entry-'+id,exerciseName:'Row',sets:'2',reps:'5',weight:'10',weightUnit:'kg',date,source:'workout-session'}]};
}

test('dashboard sessions count completion identities rather than exercise dates or rows', () => {
  const helper=load('lib/planning/dashboardSessionEvidence.ts'),now=new Date(2026,9,14,12),first=dashboardCompletionFixture('first'),second=dashboardCompletionFixture('second',13,15),old=dashboardCompletionFixture('old',11),result=helper.projectDashboardSessions([{...first,entries:[...first.entries,{...first.entries[0],id:'repeat'}]},second,old],now);
  assert.equal(result.total,3);assert.equal(result.weekly,2);assert.equal(result.days[1].count,2);assert.equal(result.days.filter(day=>day.trained).length,1);assert.equal(result.latestAt,Date.parse(second.completedAt));assert.deepEqual(result.dates,['2026-10-11','2026-10-13']);assert.ok(result.days.every(day=>day.missed===false));assert.equal(result.issue,'');
});

