function actualDashboardGoalAdapters(targets,completed=2) {
  const source=fs.readFileSync(path.join(root,'components/dashboard/DashboardExperience.tsx'),'utf8'),ast=ts.createSourceFile('dashboard.tsx',source,ts.ScriptTarget.Latest,true,ts.ScriptKind.TSX),names=['weeklySessionGoal','weeklySessionProgress','weeklySetGoal','weeklySets','weeklySetProgress','getDashboardWeeklySessionPositionStyle'],nodes=[],meters=[];
  function visit(node){if(ts.isVariableDeclaration(node)&&names.includes(node.name.getText(ast)))nodes.push('const '+node.getText(ast)+';');if(ts.isJsxOpeningElement(node)&&node.attributes.properties.some(prop=>prop.name?.getText(ast)==='aria-valuemax'&&prop.getText(ast).includes('dashboardWeeklySessionGoal.available'))){meters.push('<div '+node.attributes.properties.filter(prop=>['aria-label','aria-valuemax','aria-valuemin','aria-valuenow','role'].includes(prop.name?.getText(ast))).map(prop=>prop.getText(ast)).join(' ')+' />');}ts.forEachChild(node,visit);}visit(ast);assert.equal(nodes.length,6);assert.equal(meters.length,3);
  const helper=load('lib/planning/dashboardGoalTargets.ts'),React=require('react'),context={exports:{},require,dashboardGoalTargets:targets,workoutsThisWeek:completed,exerciseStats:[],dashboardRecordedWeeklySets:()=>5,dashboardSessionGoalLabels:helper.dashboardSessionGoalLabels,clampDashboardPercent:value=>Math.max(0,Math.min(100,value)),dashboardWeeklySessionGoal:helper.dashboardSessionGoalLabels(completed,targets.sessions),dashboardWeeklySessionResetFullLabel:'Sunday',dashboardSummary:{weeklySessionDays:Array(7).fill({}),weeklySessionGoal:targets.sessions??0,workoutsThisWeek:completed}};
  const code=ts.transpileModule(nodes.join('\n')+'\nexports.result={weeklySessionGoal,weeklySessionProgress,weeklySetGoal,weeklySets,weeklySetProgress,style:getDashboardWeeklySessionPositionStyle(1),meters:['+meters.join(',')+']};',{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022,jsx:ts.JsxEmit.ReactJSX}}).outputText;new Function(...Object.keys(context),code)(...Object.values(context));return {...context.exports.result,render:require('react-dom/server').renderToStaticMarkup};
}

test('actual dashboard target adapters keep seven calendar cells while applying saved weekly sessions and sets', () => {
  const actual=actualDashboardGoalAdapters({sessions:3,sets:20});assert.equal(actual.weeklySessionGoal,3);assert.equal(actual.weeklySetGoal,20);assert.equal(actual.weeklySetProgress,25);assert.ok(Math.abs(actual.weeklySessionProgress-200/3)<0.00001);assert.equal(actual.style['--dashboard-week-session-section-height'],100/7+'%');for(const meter of actual.meters){const markup=actual.render(meter);assert.match(markup,/role="meter"/);assert.match(markup,/aria-valuemax="3"/);assert.match(markup,/aria-valuenow="2"/);}
});

