function actualConflictReviewControls() {
  const source=fs.readFileSync(path.join(root,'components/dashboard/WorkoutTemplateConflicts.tsx'),'utf8'),ast=ts.createSourceFile('conflicts.tsx',source,ts.ScriptTarget.Latest,true,ts.ScriptKind.TSX);let inspect,mount;function visit(node){if(ts.isVariableDeclaration(node)&&node.name.getText(ast)==='inspect')inspect=node.initializer;if(ts.isCallExpression(node)&&node.expression.getText(ast)==='useEffect')mount=node.arguments[0];ts.forEachChild(node,visit);}visit(ast);assert.ok(inspect&&mount);let listener=null;const state={review:null,message:'',loading:false,items:[]},requests=[],context={exports:{},requestRef:{current:0},mountedRef:{current:true},planningOwner:store.planningOwner,planningAccountGeneration:store.planningAccountGeneration,conflicts:()=>[],subscribePlanning:callback=>{listener=callback;return()=>{listener=null;};},setReview:value=>state.review=value,setMessage:value=>state.message=value,setLoading:value=>state.loading=value,setItems:value=>state.items=value,reviewWorkoutTemplateConflict:()=>new Promise((resolve,reject)=>requests.push({resolve,reject}))};const code=ts.transpileModule('exports.inspect='+inspect.getText(ast)+';exports.mount='+mount.getText(ast)+';',{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;new Function(...Object.keys(context),code)(...Object.values(context));const cleanup=context.exports.mount();return {...context.exports,state,requests,cleanup,changed:()=>listener?.()};
}

