function actualNutritionSessionControls(file,env,mutationPattern) {
  const source=fs.readFileSync(path.join(root,file),'utf8'),ast=ts.createSourceFile(file,source,ts.ScriptTarget.Latest,true,ts.ScriptKind.TSX),nodes={},actions=[];function visit(n){if(ts.isVariableDeclaration(n)&&['act','update','reload','edit','reset'].includes(n.name.getText(ast)))nodes[n.name.getText(ast)]=n.initializer;if(ts.isCallExpression(n)&&n.expression.getText(ast)==='act'&&mutationPattern.test(n.arguments[0]?.getText(ast)||''))actions.push(n.arguments[0]);ts.forEachChild(n,visit);}visit(ast);
  function compile(node){assert.ok(node);const code=ts.transpileModule('exports.callback='+node.getText(ast)+';',{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;new Function(...Object.keys(env),code)(...Object.values(env));return env.exports.callback;}
  env.act=(...args)=>compile(nodes.act)(...args);return {run:(name,...args)=>compile(nodes[name])(...args),action:index=>env.act(compile(actions[index]),'Saved'),count:actions.length};
}

