  const end = source.indexOf('</div>}', start) + '</div>}'.length;
  assert.ok(start >= 0 && end > start);
  const expression = source.slice(start + 1, end - 1);
  const compiled = ts.transpileModule('return (' + expression + ');', { compilerOptions: { jsx: ts.JsxEmit.React, target: ts.ScriptTarget.ES2022 } }).outputText;
  const React = require('react'), Link = props => React.createElement('a', { href: props.href }, props.children);
  const render = summary => require('react-dom/server').renderToStaticMarkup(new Function('React', 'Link', 'ROUTES', 'saved', 'saveSummary', 'assignMatches', compiled)(React, Link, { dashboard: { plan: '/dashboard/my-plan' } }, true, summary, false));
  const before = store.planningSnapshot();
  const html = render({ scheduledSessions: 3, trainingDaysWithWorkouts: 2, addedAssignments: 1, retainedDays: [{ id: 'monday', day: 'Monday', sessions: 2 }], unfilledDays: [] });
  assert.match(html, /3 scheduled sessions across 2 training days/);
  assert.match(html, /Monday: 2 sessions retained/);
