function historyExportControls(env) {
  const source = fs.readFileSync(path.join(root, 'components/dashboard/WorkoutHistoryView.tsx'), 'utf8');
  const ast = ts.createSourceFile('history.tsx', source, ts.ScriptTarget.Latest, true, ts.ScriptKind.TSX), names = ['download', 'downloadConflicts', 'downloadPending'], declarations = [];
  function visit(node) { if (ts.isVariableDeclaration(node) && names.includes(node.name.getText(ast))) declarations.push('exports.' + node.name.getText(ast) + '=' + node.initializer.getText(ast) + ';'); ts.forEachChild(node, visit); }
  visit(ast); assert.equal(declarations.length, 3);
  const output = ts.transpileModule(declarations.join('\n'), { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 } }).outputText;
  const exports = {}; new Function('exports', ...Object.keys(env), output)(exports, ...Object.values(env)); return exports;
}
