test('larger recommended weeks choose spaced availability subsets independently of weekday input order', () => {
  const input = { age: '35', trainingAge: 'Advanced', preferredDays: ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday'] }, goal = { primaryGoal: 'Strength', targetWeeklySessions: '4' }, before = JSON.stringify({ input, goal });
  const result = recommendations.recommendPlan(input, goal);
  assert.deepEqual(result.days.filter(day => day.training).map(day => day.day), ['Monday', 'Tuesday', 'Thursday', 'Friday']);
  assert.deepEqual(recommendations.recommendPlan({ ...input, preferredDays: [...input.preferredDays].reverse() }, goal).days, result.days);
  assert.equal(result.split, 'Upper / Lower'); assert.equal(result.sessions, 4); assert.ok(result.reasons.some(reason => /favor spacing across the week/.test(reason))); assert.equal(JSON.stringify({ input, goal }), before);
});

test('four to seven session recommendations maximize availability then minimize cyclic spacing across every preferred subset', () => {
  const days = recommendations.weekdays, indexes = mask => days.flatMap((_, index) => mask & (1 << index) ? [index] : []);
  const cost = selected => selected.reduce((sum, day, index) => sum + ((selected[(index + 1) % selected.length] - day + 7) % 7 || 7) ** 2, 0);
  for (let sessions = 4; sessions <= 7; sessions++) for (let preferredMask = 1; preferredMask < 128; preferredMask++) {
    const preferred = indexes(preferredMask), result = recommendations.recommendPlan({ age: '35', trainingAge: 'Advanced', preferredDays: preferred.map(index => days[index]) }, { primaryGoal: 'Strength', targetWeeklySessions: String(sessions) });
    const selected = result.days.flatMap((day, index) => day.training ? [index] : []), coverage = selected.filter(index => preferred.includes(index)).length;
    assert.equal(selected.length, sessions); assert.equal(coverage, Math.min(sessions, preferred.length));
    const eligible = Array.from({ length: 127 }, (_, index) => indexes(index + 1)).filter(candidate => candidate.length === sessions && candidate.filter(index => preferred.includes(index)).length === coverage);
    assert.equal(cost(selected), Math.min(...eligible.map(cost)), 'session target ' + sessions + ', availability mask ' + preferredMask);
  }
});

test('larger recommendation defaults and existing schedules remain untouched while actual card previews spaced choices', () => {
  for (const [sessions, expected] of [[4, ['Monday', 'Tuesday', 'Thursday', 'Friday']], [5, ['Monday', 'Tuesday', 'Wednesday', 'Friday', 'Saturday']], [6, ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']], [7, recommendations.weekdays]]) {
    assert.deepEqual(recommendations.recommendPlan({}, { primaryGoal: 'Strength', targetWeeklySessions: String(sessions) }).days.filter(day => day.training).map(day => day.day), expected);
  }
  goals.saveGoalsRecord({ ...sampleGoals(), targetWeeklySessions: '4' }); store.writePlanning(store.planningKeys.profile, { age: '35', trainingAge: 'Advanced', preferredDays: ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday'] });
  const before = store.planningSnapshot(), React = require('react'), Card = load('components/dashboard/PlanRecommendationCard.tsx').default, html = require('react-dom/server').renderToStaticMarkup(React.createElement(Card));
  assert.match(html, /Monday: Upper Body/); assert.match(html, /Tuesday: Lower Body/); assert.match(html, /Thursday: Upper Body/); assert.match(html, /Friday: Lower Body/); assert.doesNotMatch(html, /Wednesday: Upper Body/); assert.equal(store.planningSnapshot(), before);
});


