  const saved=mealTemplates.createMealTemplate('first-authored',changes,version,account,generation),before=store.planningSnapshot();assert.throws(()=>mealTemplates.createMealTemplate('second-authored',changes,version,account,generation),/library changed/);assert.equal(store.planningSnapshot(),before);
