function actualStatsClockEffect(read=()=>({reportedAt:Date.now()})) {
  const source=fs.readFileSync(path.join(root,'app/dashboard/stats/page.tsx'),'utf8'),ast=ts.createSourceFile('stats.tsx',source,ts.ScriptTarget.Latest,true,ts.ScriptKind.TSX);let node;function visit(n){if(ts.isCallExpression(n)&&n.expression.getText(ast)==='useEffect'&&n.arguments[0]?.getText(ast).includes('const syncStats ='))node=n.arguments[0];ts.forEachChild(n,visit);}visit(ast);assert.ok(node);
  const state={snapshots:[],issues:[],cleared:[],unsubscribed:false},win=new EventTarget(),doc=new EventTarget();let timer,subscription;win.setInterval=(callback,ms)=>{assert.equal(ms,60000);timer=callback;return 41;};win.clearInterval=id=>state.cleared.push(id);const env={exports:{},window:win,document:doc,setSnapshot:value=>state.snapshots.push(value),getStatsFromLocalStorage:read,captureWorkoutHistoryRecovery:()=>({issues:state.issues}),subscribePlanning:callback=>{subscription=callback;return()=>state.unsubscribed=true;}},code=ts.transpileModule('exports.mount='+node.getText(ast)+';',{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;new Function(...Object.keys(env),code)(...Object.values(env));const cleanup=env.exports.mount();return {state,cleanup,tick:()=>timer(),notify:()=>subscription(),focus:()=>win.dispatchEvent(new Event('focus')),visible:()=>doc.dispatchEvent(new Event('visibilitychange')),storage:()=>win.dispatchEvent(new Event('storage'))};
}

