test('water history recovery export rejects stale source, draft and account and retains damaged device originals', async () => {
  authUser={id:'member'};await store.initializePlanning('member');const generation=store.planningAccountGeneration(),raw={keep:'Original water collection'},draft={unsupported:'Original unfinished entry'};store.writePlanningValues({[hydration.HYDRATION_KEY]:raw,[hydration.WATER_DRAFT_KEY]:draft});let version=hydration.waterHistoryVersion();store.writePlanning(hydration.WATER_DRAFT_KEY,{...draft,changed:true});assert.throws(()=>hydration.exportWaterHistory(version,'member',generation),/saved draft changed/);version=hydration.waterHistoryVersion();store.writePlanning(hydration.HYDRATION_KEY,{...raw,changed:true});assert.throws(()=>hydration.exportWaterHistory(version,'member',generation),/history or the saved draft changed/);version=hydration.waterHistoryVersion();await cycleSamePlanningAccount();const before=store.planningSnapshot();assert.throws(()=>hydration.exportWaterHistory(version,'member',generation),/account changed/);const exported=JSON.parse(hydration.exportWaterHistory(hydration.waterHistoryVersion(),'member',store.planningAccountGeneration()));assert.equal(exported.deviceCache.blocked,true);const originals=JSON.parse(exported.deviceCache.originalText).values;assert.deepEqual(originals[hydration.HYDRATION_KEY],{...raw,changed:true});assert.deepEqual(originals[hydration.WATER_DRAFT_KEY],{...draft,changed:true});assert.match(hydration.inspectWaterHistory().issue,/needs recovery/);assert.equal(store.planningSnapshot(),before);await store.initializePlanning('other-water-review');assert.throws(()=>hydration.exportWaterHistory(hydration.waterHistoryVersion(),'member',store.planningAccountGeneration()),/account changed/);
});

