test('calendar original export guards every source, account generation and preserved device cache', async () => {
 authUser={id:'member'};await store.initializePlanning('member');const generation=store.planningAccountGeneration(),keys=[store.planningKeys.plans,store.planningKeys.calendar,store.planningKeys.dashboardCalendar];store.writePlanningValues(Object.fromEntries(keys.map(key=>[key,{keep:key}])));for(const key of keys){const version=calendar.calendarSourcesVersion();store.writePlanning(key,{keep:key,changed:true});assert.throws(()=>calendar.exportCalendarSources(version,'member',generation),/sources changed/);}const version=calendar.calendarSourcesVersion();await cycleSamePlanningAccount();const before=store.planningSnapshot();assert.throws(()=>calendar.exportCalendarSources(version,'member',generation),/account changed/);const exported=JSON.parse(calendar.exportCalendarSources(calendar.calendarSourcesVersion(),'member',store.planningAccountGeneration()));assert.equal(exported.deviceCache.blocked,true);const originals=JSON.parse(exported.deviceCache.originalText).values;for(const key of keys)assert.deepEqual(originals[key],{keep:key,changed:true});assert.match(calendar.inspectCalendarSources().issue,/needs recovery/);assert.equal(store.planningSnapshot(),before);await store.initializePlanning('other-calendar-export');assert.throws(()=>calendar.exportCalendarSources(calendar.calendarSourcesVersion(),'member',store.planningAccountGeneration()),/account changed/);
});

test('actual calendar original download refuses stale data then releases the successful download URL', () => {
 const source=fs.readFileSync(path.join(root,'app/dashboard/calendar/page.tsx'),'utf8'),ast=ts.createSourceFile('calendar.tsx',source,ts.ScriptTarget.Latest,true,ts.ScriptKind.TSX);let callback;function visit(n){if(ts.isVariableDeclaration(n)&&n.name.getText(ast)==='exportOriginals')callback=n.initializer;ts.forEachChild(n,visit);}visit(ast);assert.ok(callback);const original={keep:'Calendar original'};store.writePlanning(store.planningKeys.calendar,original);const state={created:0,downloads:[],revoked:[]},env={exports:{},...calendar,sourcesVersion:calendar.calendarSourcesVersion(),exportOwner:{current:{account:store.planningOwner(),generation:store.planningAccountGeneration()}},setCalendarError:v=>state.error=v,setExportStatus:v=>state.status=v,Blob:class{constructor(parts){this.parts=parts;}},URL:{createObjectURL:blob=>{state.created++;state.blob=blob;return 'calendar-download';},revokeObjectURL:url=>state.revoked.push(url)},document:{createElement:()=>({click:()=>state.downloads.push(JSON.parse(state.blob.parts[0]))})}};function run(){const code=ts.transpileModule('exports.callback='+callback.getText(ast)+';',{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;new Function(...Object.keys(env),code)(...Object.values(env));env.exports.callback();}store.writePlanning(store.planningKeys.calendar,{...original,changed:true});const before=store.planningSnapshot();run();assert.match(state.error,/sources changed/);assert.equal(state.created,0);env.sourcesVersion=calendar.calendarSourcesVersion();run();assert.equal(state.error,'');assert.deepEqual(state.downloads[0].values[store.planningKeys.calendar],{...original,changed:true});assert.deepEqual(state.revoked,['calendar-download']);assert.equal(store.planningSnapshot(),before);
});


