test('calendar refuses unprojectable independent originals before saving visible events or treating them as deletions', () => {
 const visible={id:'visible-independent',date:'2026-10-12',time:'12:00',title:'Visible walk',notes:'Original notes',status:'Planned'},cases=[{id:'hidden-independent',custom:{keep:'Opaque original'}},{...visible,id:undefined},{...visible,id:'invalid-date',date:'2026-02-30'},{...visible,id:'legacy-time',date:undefined,scheduledAt:'2026-10-12T12:00:00Z'}];
 for(const hidden of cases){store.writePlanning(store.planningKeys.calendar,[visible,hidden]);const before=store.planningSnapshot(),editor=calendar.captureCalendarEditor();for(const changes of [[],[{...visible,title:'Changed visible event'}]]){assert.throws(()=>calendar.saveCalendarItems(changes,editor),/Original events are preserved/);assert.equal(store.planningSnapshot(),before);}assert.match(calendar.inspectCalendarSources().issue,/Independent calendar records need review/);const exported=JSON.parse(calendar.exportCalendarSources(calendar.calendarSourcesVersion(),store.planningOwner(),store.planningAccountGeneration()));assert.deepEqual(exported.values[store.planningKeys.calendar],JSON.parse(JSON.stringify([visible,hidden])));assert.equal(store.planningSnapshot(),before);}
});

test('calendar independent event edits retain original extra metadata and unrelated siblings until explicit reviewed deletion', () => {
 const event={id:'independent-metadata',date:'2026-10-12',time:'12:00',title:'Walk',notes:'Original notes',status:'Planned',sourceMetadata:{keep:'Original event context'},customTag:'Keep original tag'},other={...event,id:'other-independent',title:'Other walk',sourceMetadata:{keep:'Sibling context'}};store.writePlanning(store.planningKeys.calendar,[event,other]);calendar.saveCalendarItems([{id:event.id,date:event.date,time:'13:00',title:'Reviewed walk',notes:'Reviewed notes',status:'Planned'},other],calendar.captureCalendarEditor());let originals=store.planningSnapshot()[store.planningKeys.calendar],changed=originals.find(x=>x.id===event.id);assert.deepEqual(changed.sourceMetadata,event.sourceMetadata);assert.equal(changed.customTag,event.customTag);assert.equal(changed.time,'13:00');assert.deepEqual(originals.find(x=>x.id===other.id),other);const before=store.planningSnapshot();failure=true;try{assert.throws(()=>calendar.saveCalendarItems([other],calendar.captureCalendarEditor()),/Quota/);}finally{failure=false;}assert.equal(store.planningSnapshot(),before);calendar.saveCalendarItems([other],calendar.captureCalendarEditor());assert.deepEqual(store.planningSnapshot()[store.planningKeys.calendar],[other]);
});


test('calendar refuses damaged saved reflection originals before normalization replacement or deletion', () => {
 const event={id:'original-reflection',date:'2026-10-12',time:'12:00',title:'Walk',type:'cardio',notes:'Keep notes',status:'Planned'},keys=[store.planningKeys.calendar,store.planningKeys.dashboardCalendar];
 for(const key of keys)for(const reflection of [null,false,[],{difficulty:'5'},{energy:11},{painNotes:{keep:'Original'}}]){store.writePlanningValues({[store.planningKeys.calendar]:[],[store.planningKeys.dashboardCalendar]:[]});store.writePlanning(key,[{...event,reflection}]);const before=store.planningSnapshot(),editor=calendar.captureCalendarEditor();for(const items of [[],[{...event,id:key===store.planningKeys.calendar?event.id:'dashboard-entry:'+event.id,reflection:calendar.emptyCalendarReflection()}]]){assert.throws(()=>calendar.saveCalendarItems(items,editor),/reflection|Reflection/);assert.equal(store.planningSnapshot(),before);}assert.match(calendar.inspectCalendarSources().issue,/reflection|Reflection/);const exported=JSON.parse(calendar.exportCalendarSources(calendar.calendarSourcesVersion(),store.planningOwner(),store.planningAccountGeneration()));assert.deepEqual(exported.values[key],[{...event,reflection}]);assert.equal(store.planningSnapshot(),before);}
});

test('calendar reflection edits retain omitted answers and metadata while explicit null and empty notes clear reviewed fields', () => {
 const event={id:'reflection-context',date:'2026-10-12',time:'12:00',title:'Walk',type:'cardio',notes:'Keep notes',status:'Planned',reflection:{...calendar.emptyCalendarReflection(),difficulty:5,energy:7,wentWell:'Original answer',sourceMetadata:{keep:'Original reflection context'}}};
 for(const key of [store.planningKeys.calendar,store.planningKeys.dashboardCalendar]){store.writePlanningValues({[store.planningKeys.calendar]:[],[store.planningKeys.dashboardCalendar]:[]});store.writePlanning(key,[event]);const id=key===store.planningKeys.calendar?event.id:'dashboard-entry:'+event.id;calendar.saveCalendarItems([{...event,id,reflection:{wentWell:'Reviewed answer'}}],calendar.captureCalendarEditor());let saved=store.planningSnapshot()[key][0];assert.equal(saved.reflection.difficulty,5);assert.equal(saved.reflection.energy,7);assert.equal(saved.reflection.wentWell,'Reviewed answer');assert.deepEqual(saved.reflection.sourceMetadata,event.reflection.sourceMetadata);calendar.saveCalendarItems([{...event,id,reflection:undefined}],calendar.captureCalendarEditor());assert.deepEqual(store.planningSnapshot()[key][0].reflection,saved.reflection);calendar.saveCalendarItems([{...event,id,reflection:{difficulty:null,wentWell:''}}],calendar.captureCalendarEditor());saved=store.planningSnapshot()[key][0];assert.equal(saved.reflection.difficulty,null);assert.equal(saved.reflection.wentWell,'');assert.equal(saved.reflection.energy,7);assert.deepEqual(saved.reflection.sourceMetadata,event.reflection.sourceMetadata);}
});


test('workout completion preserves explicit malformed history and statistics collections before recording or clearing drafts', () => {
 const date=new Date(Date.now()-1000).toISOString(),entry={exerciseId:'guarded-completion-squat',exerciseName:'Squat',date,sets:'2',reps:'8',weight:'0',weightUnit:'lb'},input={sessionId:'guarded-original-collections',title:'Recorded workout',completedAt:date,entries:[entry]},record={...input,id:input.sessionId},draft={id:input.sessionId,logs:{0:{sets:'2',reps:'8',weight:'0',weightUnit:'lb'}}};
 for(const key of [store.planningKeys.logs,store.planningKeys.exerciseStats])for(const original of [null,false,{},'Original unsupported collection']){store.writePlanningValues({[store.planningKeys.logs]:[],[store.planningKeys.exerciseStats]:[],'loggerDraft:default':draft});store.writePlanning(key,original);const before=store.planningSnapshot();assert.throws(()=>logs.recordPlanningLog(record),/needs review|need review/);assert.equal(store.planningSnapshot(),before);const result=persistence.saveCompletedWorkoutLogToLocalStorage(input);assert.equal(result.success,false);assert.equal(result.data.workoutLogId,null);assert.match(result.error,/needs review|need review/);assert.equal(store.planningSnapshot(),before);assert.deepEqual(store.readPlanning('loggerDraft:default',null),draft);assert.deepEqual(store.planningSnapshot()[key],original);}
});

test('workout immutable local retries return original evidence without rewriting unavailable statistics', () => {
 const date=new Date(Date.now()-1000).toISOString(),entry={exerciseId:'immutable-retry-squat',exerciseName:'Squat',date,sets:'2',reps:'8',weight:'0',weightUnit:'lb'},input={sessionId:'immutable-stats-retry',title:'Original workout',completedAt:date,entries:[entry]};assert.equal(persistence.saveCompletedWorkoutLogToLocalStorage(input).success,true);const original=logs.readPlanningLogs()[0];store.writePlanning(store.planningKeys.exerciseStats,null);const before=store.planningSnapshot(),result=persistence.saveCompletedWorkoutLogToLocalStorage({...input,title:'Changed caller title',entries:[{...entry,sets:'9'}]});assert.equal(result.success,true);assert.deepEqual(result.data.entries,original.entries);assert.equal(result.data.workoutLogId,original.id);assert.equal(store.planningSnapshot(),before);assert.equal(store.planningSnapshot()[store.planningKeys.exerciseStats],null);
});


test('exercise statistics prepend refuses raw malformed originals and preserves valid legacy siblings', () => {
 const data=load('lib/localData/workoutData.ts'),entry={exerciseId:'safe-prepend',exerciseName:'Squat',date:new Date().toISOString(),sets:'2',reps:'8',weight:'0'},key=store.planningKeys.exerciseStats;
 for(const original of [null,false,0,{},'Original statistics']){store.writePlanning(key,original);const before=store.planningSnapshot();for(const write of [()=>data.prependExerciseStats(entry),()=>data.saveWorkoutSessionExerciseStats([entry])]){assert.throws(write,/statistics need review/);assert.equal(store.planningSnapshot(),before);assert.deepEqual(store.planningSnapshot()[key],original);}}
 const legacy={exerciseName:'Older report',custom:{keep:'Original metadata'}};store.writePlanning(key,[legacy]);const result=data.prependExerciseStats(entry);assert.deepEqual(result,[entry,legacy]);assert.deepEqual(store.planningSnapshot()[key],[entry,legacy]);
});

