 const api=load('lib/planning/dashboardManualStats.ts'),legacy='Unclaimed browser notes';storage.set(api.DASHBOARD_MANUAL_STATS_KEY,legacy);assert.deepEqual(api.inspectDashboardManualStats().entries,[]);
