test('manual stats review preserves input and originals while adopting only the exact reviewed account sources',async()=>{
 const api=load('lib/planning/dashboardManualStats.ts'),editor=api.captureDashboardManualStatsEditor();store.writePlanning(api.DASHBOARD_MANUAL_STATS_KEY,[dashboardManualFixture('changed-note')]);const before=store.planningSnapshot(),review=api.reviewDashboardManualStats(editor);assert.equal(store.planningSnapshot(),before);assert.equal(review.entries[0].id,'changed-note');assert.equal(api.dashboardManualStatsReviewBelongsToCurrentAccount(review),true);review.entries[0].notes='Detached preview change';assert.equal(store.planningSnapshot()[api.DASHBOARD_MANUAL_STATS_KEY][0].notes,'Keep this note');const accepted=api.acceptDashboardManualStatsReview(review);assert.equal(store.planningSnapshot(),before);const saved=api.saveDashboardManualStat(dashboardManualFixture(),accepted);assert.equal(saved.entries.length,2);assert.equal(saved.entries[1].notes,'Keep this note');assert.throws(()=>api.acceptDashboardManualStatsReview(review),/changed again/);const current=api.reviewDashboardManualStats(accepted);await store.initializePlanning('manual-review-other');assert.equal(api.dashboardManualStatsReviewBelongsToCurrentAccount(current),false);assert.throws(()=>api.acceptDashboardManualStatsReview(current),/account changed/);assert.throws(()=>api.reviewDashboardManualStats(editor),/account changed/);await store.initializePlanning(null);assert.throws(()=>api.acceptDashboardManualStatsReview(current),/account changed/);
});
