test('phase saves detach nested form and original data while preserving an independent exact undo snapshot',()=>{
 const key=store.planningKeys.phases,original={phases:[{id:'detached-phase',name:'Original phase',status:'draft',custom:{notes:['Original annotation']}}],backendContext:{version:2}},exact=structuredClone(original);store.writePlanning(key,original);const input=[{id:'detached-phase',name:'Reviewed phase',status:'draft',custom:{notes:['Reviewed annotation']}}],undo=phaseMutations.commitPhaseRecords(input,store.planningOwner(),store.planningRecordVersion(key),store.planningAccountGeneration()),stored=store.readPlanning(key,null);assert.deepEqual(undo.previous,exact);assert.notEqual(undo.previous,original);assert.notEqual(stored.phases[0].custom,input[0].custom);original.phases[0].custom.notes.push('Changed original form');original.backendContext.version=999;input[0].custom.notes.push('Changed open editor');assert.deepEqual(stored.phases[0].custom.notes,['Reviewed annotation']);assert.equal(stored.backendContext.version,2);assert.deepEqual(undo.previous,exact);phaseMutations.undoPhaseRemoval(undo);assert.deepEqual(store.readPlanning(key,null),exact);undo.previous.phases[0].custom.notes.push('Changed old undo after restore');assert.deepEqual(store.readPlanning(key,null),exact);
});

test('phase undo refuses a changed snapshot and preserves current library on payload or storage failure',()=>{
 const key=store.planningKeys.phases,original={phases:[{id:'undo-integrity',name:'Original',status:'active',custom:{keep:true}}],annotations:{notes:['Keep wrapper']} };store.writePlanning(key,original);const undo=phaseMutations.commitPhaseRecords([],store.planningOwner(),store.planningRecordVersion(key),store.planningAccountGeneration()),before=store.planningSnapshot(),changed=structuredClone(undo);changed.previous.phases[0].custom.keep=false;assert.throws(()=>phaseMutations.undoPhaseRemoval(changed),/undo snapshot changed/);assert.equal(store.planningSnapshot(),before);const missing={...undo};delete missing.previousVersion;assert.throws(()=>phaseMutations.undoPhaseRemoval(missing),/undo snapshot changed/);assert.equal(store.planningSnapshot(),before);failure=true;try{assert.throws(()=>phaseMutations.undoPhaseRemoval(undo),/Quota/);}finally{failure=false;}assert.equal(store.planningSnapshot(),before);assert.deepEqual(undo.previous,original);phaseMutations.undoPhaseRemoval(undo);assert.deepEqual(store.readPlanning(key,null),original);
});


test('Sessions template milestones use eligible unique workouts independently of damaged siblings and unresolved versions',async()=>{
 const ready={id:'journey-ready',title:'Ready workout',exercises:[{id:'squat',name:'Squat',equipment:'Bodyweight'}]},offline={...ready,id:'journey-offline-ready',syncPending:true,syncError:'Cloud unavailable'},conflict={...ready,id:'journey-conflicted',syncPending:true,syncError:'Workout template sync conflict'},bad={...ready,id:'journey-bad',exercises:[null]},duplicate={...ready,id:'journey-duplicate'},oversized=sessionSizeTemplate('journey-oversized',101),excluded=[null,bad,conflict,duplicate,{...duplicate,title:'Other original'},oversized];for(const candidates of [[ready,...excluded],[...excluded,ready],[offline,...excluded]]){const original=JSON.stringify(candidates),before=store.planningSnapshot(),result=sessionJourney.sessionJourneyEvidence(before,candidates,[]);assert.equal(result.templates,true);assert.equal(result.library,true);assert.equal(result.templateReviewCount,excluded.length);assert.equal(result.history,false);assert.equal(JSON.stringify(candidates),original);assert.equal(store.planningSnapshot(),before);}const only=sessionJourney.sessionJourneyEvidence(store.planningSnapshot(),excluded,[]);assert.equal(only.templates,false);assert.equal(only.library,false);assert.equal(only.templateReviewCount,excluded.length);const old=store.planningSnapshot();await store.initializePlanning('different-template-journey-account');const stale=sessionJourney.sessionJourneyEvidence(old,[ready,...excluded],[]);assert.equal(stale.templates,false);assert.equal(stale.library,false);assert.equal(stale.templateReviewCount,0);
});

