test('workout semantic review presents recorded values and known modifier labels without rebuilding or mutating originals',()=>{
 const helper=load('lib/planning/workoutSemanticReview.ts'),entry={exerciseName:'Squat',generatedTitle:'Paused Front Squat',semanticVariationName:'Front Squat',semanticVariationId:'front',coreMovementPattern:'squat',selectedModifierIds:['equipment:barbell','movementIntent:strength'],custom:{notes:'Keep original'}},original=JSON.stringify(entry),review=helper.workoutSemanticReview(entry);assert.equal(review.issue,'');assert.deepEqual(review.details.slice(0,3),[{label:'Recorded title',value:'Paused Front Squat'},{label:'Recorded variation',value:'Front Squat'},{label:'Recorded movement',value:'squat'}]);assert.match(review.details[3].value,/Equipment: Barbell/);assert.match(review.details[3].value,/Movement Intent: Strength/);assert.equal(JSON.stringify(entry),original);assert.deepEqual(helper.workoutSemanticReview({exerciseName:'Legacy squat'}),{details:[],issue:''});assert.deepEqual(helper.workoutSemanticReview(null),{details:[],issue:''});assert.equal(helper.workoutSemanticReview({selectedModifierIds:[]}).details[0].value,'No modifiers recorded');const unknown={...entry,selectedModifierIds:['equipment:future-device']},unknownOriginal=JSON.stringify(unknown);assert.match(helper.workoutSemanticReview(unknown).issue,/not recognized/);assert.match(helper.workoutSemanticReview(unknown).details[3].value,/equipment:future-device/);assert.equal(JSON.stringify(unknown),unknownOriginal);const malformed={generatedTitle:{keep:'Original title'},semanticVariationName:['Original name'],coreMovementPattern:false,selectedModifierIds:{keep:true}},before=JSON.stringify(malformed),bad=helper.workoutSemanticReview(malformed);assert.match(bad.issue,/need review/);assert.ok(bad.details.every(detail=>typeof detail.value==='string'));assert.equal(JSON.stringify(malformed),before);assert.ok(helper.workoutSemanticReview({generatedTitle:'x'.repeat(1000)}).details[0].value.length<600);
});

