test('completion recording detaches caller history and statistics snapshots and rolls back atomically',()=>{
 const date=new Date(Date.now()-1000).toISOString(),old={id:'old-detached',title:'Old',completedAt:date,entries:[{exerciseId:'old',exerciseName:'Original',sets:'1',reps:'3',weight:'0',date,custom:{notes:['Old annotation']}}]},priorStats=[{...old.entries[0],custom:{notes:['Old statistic']}}];store.writePlanningValues({[store.planningKeys.logs]:[old],[store.planningKeys.exerciseStats]:priorStats});const incoming={id:'new-detached',title:'New',completedAt:date,entries:[{exerciseId:'new',exerciseName:'Squat',sets:'2',reps:'8',weight:'20',date,selectedModifierIds:['equipment:barbell'],custom:{notes:['Keep annotation']}}]},before=store.planningSnapshot();failure=true;try{assert.throws(()=>logs.recordPlanningLog(incoming),/Quota/);}finally{failure=false;}assert.equal(store.planningSnapshot(),before);logs.recordPlanningLog(incoming);const history=store.readPlanning(store.planningKeys.logs,[]),stats=store.readPlanning(store.planningKeys.exerciseStats,[]);incoming.entries[0].sets='99';incoming.entries[0].selectedModifierIds.push('movementIntent:power');incoming.entries[0].custom.notes.push('Caller mutation');old.entries[0].custom.notes.push('Old source mutation');priorStats[0].custom.notes.push('Old stats mutation');assert.equal(history[1].entries[0].sets,'2');assert.equal(stats[0].sets,'2');assert.deepEqual(history[1].entries[0].selectedModifierIds,['equipment:barbell']);assert.deepEqual(stats[0].custom.notes,['Keep annotation']);assert.deepEqual(history[0].entries[0].custom.notes,['Old annotation']);assert.deepEqual(stats[1].custom.notes,['Old statistic']);assert.notEqual(history[1].entries[0],stats[0]);assert.notEqual(history[1].entries[0].custom,stats[0].custom);const committed=store.planningSnapshot();logs.recordPlanningLog({...incoming,title:'Retry title'});assert.equal(store.planningSnapshot(),committed);
});

test('new completion results and idempotent retry results cannot mutate saved history or statistics',()=>{
 const persistence=load('lib/data/workoutPersistence.ts'),date=new Date(Date.now()-1000).toISOString(),entry={exerciseId:'result-squat',exerciseName:'Squat',sets:'2',reps:'8',weight:'20',weightUnit:'kg',date,coreMovementPattern:'squat',selectedModifierIds:['equipment:barbell']},input={sessionId:'detached-completion-result',title:'Recorded workout',completedAt:date,entries:[entry]},first=persistence.saveCompletedWorkoutLogToLocalStorage(input);assert.equal(first.success,true,first.error);const expected=structuredClone(store.readPlanning(store.planningKeys.logs,[])),expectedStats=structuredClone(store.readPlanning(store.planningKeys.exerciseStats,[]));first.data.entries[0].sets='99';first.data.entries[0].selectedModifierIds.push('movementIntent:power');entry.selectedModifierIds.push('movementIntent:strength');assert.deepEqual(store.readPlanning(store.planningKeys.logs,[]),expected);assert.deepEqual(store.readPlanning(store.planningKeys.exerciseStats,[]),expectedStats);const before=store.planningSnapshot(),retry=persistence.saveCompletedWorkoutLogToLocalStorage({...input,title:'Different title',entries:[]});assert.equal(retry.success,true,retry.error);assert.deepEqual(retry.data.entries,expected[0].entries);retry.data.entries[0].weight='999';retry.data.entries[0].selectedModifierIds.push('movementIntent:mobility');assert.equal(store.planningSnapshot(),before);assert.deepEqual(store.readPlanning(store.planningKeys.logs,[]),expected);assert.deepEqual(store.readPlanning(store.planningKeys.exerciseStats,[]),expectedStats);
});


