test('completion conflict review detects explicit template identity disagreements but preserves missing legacy links',()=>{
 const date=new Date(Date.now()-1000).toISOString(),local={id:'same-template-session',cloudLogId:'11111111-2222-4333-8444-555555555555',templateId:'original-template',title:'Recorded session',completedAt:date,entries:[{exerciseId:'squat',exerciseName:'Squat',sets:'2',reps:'8',weight:'20',date}]};for(const identity of [{id:local.id},{id:local.cloudLogId,cloudLogId:undefined},{id:'cloud-view',cloudLogId:local.id}]){const remote={...local,...identity,templateId:'different-template'},original=JSON.stringify([local,remote]),conflicts=availableLogs.workoutCompletionConflicts([local],[remote]);assert.equal(conflicts.length,1);assert.equal(conflicts[0].kind,'identity');assert.equal(conflicts[0].planning,local);assert.equal(conflicts[0].cloud,remote);assert.equal(JSON.stringify([local,remote]),original);assert.equal(availableLogs.mergeAvailableWorkoutLogs([local],[remote]).length,1);}for(const templateId of [undefined,null,'',local.templateId]){assert.deepEqual(availableLogs.workoutCompletionConflicts([local],[{...local,templateId}]),[]);assert.deepEqual(availableLogs.workoutCompletionConflicts([{...local,templateId}],[local]),[]);}const independent={...local,id:'another-session',cloudLogId:undefined,templateId:'different-template'};assert.deepEqual(availableLogs.workoutCompletionConflicts([local],[independent]),[]);
});

