test('workout failure feedback distinguishes a saved local record from absent malformed or other-session evidence without writes',()=>{
 const helper=logs.workoutSaveFailureMessage,date=new Date(Date.now()-1000).toISOString(),record={id:'recorded-before-followup-failed',title:'Recorded',completedAt:date,entries:[{exerciseId:'squat',exerciseName:'Squat',sets:'2',reps:'8',weight:'20',date}]};for(const history of [[],[{...record,id:'other-session'}],null,{},[null]]){store.writePlanning(store.planningKeys.logs,history);const before=store.planningSnapshot();assert.equal(helper(record.id,new Error('Quota exceeded')),'Quota exceeded');assert.equal(store.planningSnapshot(),before);}store.writePlanning(store.planningKeys.logs,[record]);const before=store.planningSnapshot(),message=helper(record.id,new Error('Upload not confirmed'));assert.match(message,/Upload not confirmed/);assert.match(message,/already saved in History/);assert.match(message,/Open History to review/);assert.equal(store.planningSnapshot(),before);assert.deepEqual(store.readPlanning(store.planningKeys.logs,[]),[record]);assert.doesNotMatch(helper('different-id',null),/already saved/);
});

test('actual logger failed follow-up identifies its saved workout without navigating clearing draft or claiming successful finalization',async()=>{
 const f=actualLoggerCompletionFixture(),date=new Date(Date.now()-1000).toISOString(),draft={id:f.sessionKeyRef.current,logs:{2:{sets:'2',reps:'8',weight:'0',weightUnit:'lb'}},custom:{notes:'Keep unfinished recovery'}};store.writePlanning('loggerDraft:default',draft);const request=f.save();const record={id:f.sessionKeyRef.current,title:'Recorded workout',completedAt:date,entries:[{exerciseId:'squat',exerciseName:'Squat',sets:'2',reps:'8',weight:'0',date}]};logs.recordPlanningLog(record);const before=store.planningSnapshot();f.finish({success:false,source:'localStorage',error:'Cloud save was not confirmed'});await request;const message=f.state.updates.filter(([field])=>field==='message').at(-1)[1];assert.match(message,/Cloud save was not confirmed/);assert.match(message,/already saved in History/);assert.deepEqual(f.state.navigations,[]);assert.deepEqual(f.state.timers,[]);assert.deepEqual(f.state.writes,[]);assert.equal(f.state.updates.filter(([field])=>field==='lastSaved').at(-1)[1],null);assert.equal(store.planningSnapshot(),before);assert.deepEqual(store.readPlanning('loggerDraft:default',null),draft);assert.deepEqual(store.readPlanning(store.planningKeys.logs,[]),[record]);f.cleanup();
});


test('shared workout chronology preserves date-only day precision and rejects impossible exercise or start times without mutation',()=>{
 const helper=load('lib/planning/workoutChronology.ts'),now=new Date(2026,9,14,20).getTime(),ended=new Date(2026,9,13,12).toISOString(),entry={date:new Date(2026,9,13,13).toISOString()},original=JSON.stringify(entry);assert.throws(()=>helper.assertWorkoutChronology([entry],ended,{now}),/after the workout completion/);assert.doesNotThrow(()=>helper.assertWorkoutChronology([entry],'2026-10-13',{now}));assert.throws(()=>helper.assertWorkoutChronology([{date:new Date(2026,9,14,1).toISOString()}],'2026-10-13',{now}),/after the workout completion/);for(const startedAt of [false,'invalid',new Date(2026,9,13,13).toISOString()])assert.throws(()=>helper.assertWorkoutChronology([{date:ended}],ended,{now,startedAt}),/start date needs review/);assert.doesNotThrow(()=>helper.assertWorkoutChronology([{date:ended}],ended,{now,startedAt:new Date(2026,9,13,11).toISOString()}));assert.throws(()=>helper.assertWorkoutChronology([{date:'invalid'}],ended,{now}),/activity time needs review/);assert.throws(()=>helper.assertWorkoutChronology([{date:ended}],'invalid',{now}),/completion time needs review/);assert.equal(JSON.stringify(entry),original);
});

