test('Sessions weekly workload combines explicit pounds and kilograms without inferring unknown units',()=>{
 const now=new Date(2026,9,14,20),date=new Date(2026,9,13,12).toISOString(),entry={exerciseId:'squat',exerciseName:'Squat',sets:'2',reps:'10',weight:'100',weightUnit:'lb',date},log={id:'unit-week',completedAt:date,entries:[entry,{...entry,weight:'45.359237',weightUnit:'kg'}]},original=JSON.stringify(log),before=store.planningSnapshot();
 let result=sessionReporting.sessionWeekWorkload([log],now);assert.ok(Math.abs(result.volumePounds-4000)<0.00001);assert.equal(result.label,'4,000 lb·reps');assert.equal(result.complete,true);
 result=sessionReporting.sessionWeekWorkload([{...log,entries:[...log.entries,{...entry,weightUnit:undefined}]}],now);assert.equal(result.label,'4,000 lb·reps (partial)');assert.equal(result.unknownEntries,1);
 assert.equal(sessionReporting.sessionWeekWorkload([{...log,entries:[{...entry,weight:'0',weightUnit:undefined}]}],now).label,'Volume unavailable');
 assert.equal(sessionReporting.sessionWeekWorkload([{...log,entries:[{...entry,weight:'0'}]}],now).label,'0 lb·reps');assert.equal(JSON.stringify(log),original);assert.equal(store.planningSnapshot(),before);
});

