test('meal template save results and no-op retries are detached from canonical saved values',()=>{
 const account=store.planningOwner(),generation=store.planningAccountGeneration(),changes={title:'Original reusable meal',kind:'Dinner',notes:'Keep reported values',calories:null,protein:0,carbs:30,fat:10};
 const created=mealTemplates.createMealTemplate('detached-template',changes,mealTemplates.mealTemplateLibraryVersion(),account,generation),stored=mealTemplates.readMealTemplates()[0],before=store.planningSnapshot();assert.notEqual(created,stored);created.title='Caller edit';changes.notes='Caller input edit';assert.equal(stored.title,'Original reusable meal');assert.equal(stored.notes,'Keep reported values');assert.equal(store.planningSnapshot(),before);
 const retry=mealTemplates.createMealTemplate(stored.id,{...changes,notes:stored.notes},'stale-library-token',account,generation);assert.notEqual(retry,stored);retry.notes='Mutated retry';assert.equal(stored.notes,'Keep reported values');assert.equal(store.planningSnapshot(),before);
 const update={...changes,title:'Reviewed title',notes:'Reviewed notes'},updated=mealTemplates.updateMealTemplate(stored.id,update,mealTemplates.mealTemplateVersion(stored.id),account,generation),current=mealTemplates.readMealTemplates()[0],snapshot=store.planningSnapshot();assert.notEqual(updated,current);updated.title='Mutated return';update.title='Mutated input';assert.equal(current.title,'Reviewed title');assert.equal(stored.title,'Original reusable meal');
 const unchanged=mealTemplates.updateMealTemplate(current.id,{title:current.title,kind:current.kind,notes:current.notes,calories:current.calories,protein:current.protein,carbs:current.carbs,fat:current.fat},mealTemplates.mealTemplateVersion(current.id),account,generation);assert.notEqual(unchanged,current);unchanged.notes='Mutated no-op';assert.equal(current.notes,'Reviewed notes');assert.equal(store.planningSnapshot(),snapshot);
});

test('meal-derived template updates retain extra annotations and detach archive snapshots and returned nested data',()=>{
 const account=store.planningOwner(),generation=store.planningAccountGeneration(),meal=meals.saveMeal(templateSourceMeal(),undefined,account,generation),created=mealTemplates.saveMealAsTemplate(meal.id,meals.mealVersion(meal.id),undefined,account,generation);
 const annotated={...created,custom:{notes:['Keep template annotation']}},other={...created,id:'other-annotated-template',custom:{notes:['Keep other annotation']}};store.writePlanning(store.planningKeys.mealTemplates,[annotated,other]);const previous=mealTemplates.readMealTemplates(),previousBytes=JSON.stringify(previous);
 const updatedMeal=meals.saveMeal({...templateSourceMeal(),protein:20},meals.mealVersion(meal.id),account,generation),updated=mealTemplates.saveMealAsTemplate(meal.id,meals.mealVersion(updatedMeal.id),mealTemplates.mealTemplateVersion(created.id),account,generation),stored=mealTemplates.readMealTemplates().find(item=>item.id===created.id);assert.deepEqual(stored.custom,annotated.custom);assert.equal(stored.protein,20);assert.equal(JSON.stringify(previous),previousBytes);updated.custom.notes.push('Caller mutation');assert.deepEqual(stored.custom,{notes:['Keep template annotation']});assert.deepEqual(annotated.custom,{notes:['Keep template annotation']});
 const retry=mealTemplates.saveMealAsTemplate(meal.id,meals.mealVersion(meal.id),undefined,account,generation);retry.custom.notes.push('No-op caller mutation');assert.deepEqual(stored.custom,{notes:['Keep template annotation']});const archiveBefore=mealTemplates.readMealTemplates(),archiveBytes=JSON.stringify(archiveBefore);mealTemplates.setMealTemplateArchived(created.id,true,mealTemplates.mealTemplateVersion(created.id),account,generation);assert.equal(JSON.stringify(archiveBefore),archiveBytes);archiveBefore.find(item=>item.id===other.id).custom.notes.push('Old snapshot mutation');assert.deepEqual(mealTemplates.readMealTemplates().find(item=>item.id===other.id).custom,{notes:['Keep other annotation']});
 const before=store.planningSnapshot(),bytes=JSON.stringify(mealTemplates.readMealTemplates());failure=true;try{assert.throws(()=>mealTemplates.setMealTemplateArchived(created.id,false,mealTemplates.mealTemplateVersion(created.id),account,generation),/Quota/);}finally{failure=false;}assert.equal(store.planningSnapshot(),before);assert.equal(JSON.stringify(mealTemplates.readMealTemplates()),bytes);
});


