test('meal drafts removal snapshots and failed atomic completion remain detached and preserved',()=>{
 const account=store.planningOwner(),generation=store.planningAccountGeneration(),first=meals.saveMeal(templateSourceMeal(),undefined,account,generation),second=meals.saveMeal({...templateSourceMeal(),id:'other-saved-meal',title:'Other meal'},undefined,account,generation);store.writePlanning(meals.MEALS_KEY,[{...first,custom:{notes:['Keep first']}},{...second,custom:{notes:['Keep other']}}]);
 const draft={...meals.emptyMealDraft(dates.localDate()),id:first.id,title:first.title,date:first.date,time:first.time,kind:first.kind,notes:first.notes,protein:'30',baseVersion:meals.mealVersion(first.id),custom:{notes:['Keep draft annotation']}};meals.saveMealDraft(draft,meals.mealDraftVersion(),account,generation);const savedDraft=meals.readMealDraft(),version=meals.mealDraftVersion(),before=store.planningSnapshot();assert.notEqual(savedDraft,draft);draft.title='Caller form mutation';draft.custom.notes.push('Caller draft mutation');assert.equal(savedDraft.title,first.title);assert.deepEqual(savedDraft.custom,{notes:['Keep draft annotation']});
 failure=true;try{assert.throws(()=>meals.saveMeal(meals.mealInputFromDraft(savedDraft),savedDraft.baseVersion,account,generation,new Date(),version),/Quota/);}finally{failure=false;}assert.equal(store.planningSnapshot(),before);assert.deepEqual(meals.readMealDraft(),savedDraft);
 const result=meals.saveMeal(meals.mealInputFromDraft(savedDraft),savedDraft.baseVersion,account,generation,new Date(),version);assert.equal(meals.readMealDraft(),null);assert.equal(result.protein,30);assert.deepEqual(result.custom,{notes:['Keep first']});
 const old=meals.readMeals(),bytes=JSON.stringify(old);meals.removeMeal(first.id,meals.mealVersion(first.id),account,generation);assert.equal(JSON.stringify(old),bytes);old.find(item=>item.id===second.id).custom.notes.push('Old snapshot mutation');assert.deepEqual(meals.readMeals()[0].custom,{notes:['Keep other']});
});


test('workout backup receipt results cannot mutate stored confirmation or bypass revision guards',async()=>{
 authUser={id:'member'};await store.initializePlanning('member');const helper=load('lib/planning/workoutSyncReceipt.ts'),operation=helper.createWorkoutSyncOperation(),ticket=operation.begin(),counts={syncedTemplates:1,syncedLogs:2,skippedItems:0},saved=operation.record(ticket,counts,'2026-10-13T18:05:00Z'),expected={schemaVersion:1,completedAt:'2026-10-13T18:05:00Z',...counts},canonical=store.readPlanning(helper.WORKOUT_SYNC_RECEIPT_KEY,null),before=store.planningSnapshot();assert.notEqual(saved,canonical);saved.syncedLogs=999;saved.completedAt='invalid';counts.syncedTemplates=999;assert.deepEqual(store.readPlanning(helper.WORKOUT_SYNC_RECEIPT_KEY,null),expected);const read=helper.readWorkoutSyncReceipt();assert.notEqual(read,canonical);read.syncedLogs=888;assert.deepEqual(helper.readWorkoutSyncReceipt(),expected);assert.equal(store.planningSnapshot(),before);assert.throws(()=>operation.record(ticket,counts),/receipt changed/);assert.equal(operation.finish(ticket),true);const retry=operation.begin();failure=true;try{assert.throws(()=>operation.record(retry,{syncedTemplates:3,syncedLogs:4,skippedItems:0}));}finally{failure=false;}assert.equal(store.planningSnapshot(),before);assert.deepEqual(helper.readWorkoutSyncReceipt(),expected);assert.equal(operation.finish(retry),true);
});
